INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92546, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "制版", "is_correct": true, "explanation": "正确。制版指排好文字图片，做出印刷用的版面。"}, {"text": "纸板", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，纸板指用纸做的硬板，意思不同。"}, {"text": "直板", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，直板指形状平直的板子，意思不同。"}, {"text": "置办", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，置办指购置、准备物品，意思不同。"}, {"text": "治本", "is_correct": false, "explanation": "běn 与 bǎn 韵母不同（en 与 an），治本指从根本上解决问题，意思不同。"}, {"text": "试版", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），试版指试印的版本，意思不同。"}], "explanations": {"制版": "正确。制版指排好文字图片，做出印刷用的版面。", "纸板": "zhǐ（第三声）与 zhì（第四声）声调不同，纸板指用纸做的硬板，意思不同。", "直板": "zhí（第二声）与 zhì（第四声）声调不同，直板指形状平直的板子，意思不同。", "置办": "bàn（第四声）与 bǎn（第三声）声调不同，置办指购置、准备物品，意思不同。", "治本": "běn 与 bǎn 韵母不同（en 与 an），治本指从根本上解决问题，意思不同。", "试版": "shì 与 zhì 声母不同（sh 与 zh），试版指试印的版本，意思不同。"}, "sentence_index": null, "correct_answer": "制版"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是衣物、身体等，不能用来洗画册。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”一般用于食物，不说烤画册。"}, {"text": "制版", "is_correct": true, "explanation": "正确。为这本画册做印刷用的版面，符合句中语境。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”用于食物，画册不能煮。"}], "explanations": {"洗": "语义：“洗”的对象是衣物、身体等，不能用来洗画册。", "烤": "搭配：“烤”一般用于食物，不说烤画册。", "制版": "正确。为这本画册做印刷用的版面，符合句中语境。", "煮": "语义：“煮”用于食物，画册不能煮。"}, "sentence_index": 0, "correct_answer": "制版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他制版了那台旧电视。", "explanation": "这里应该用〈修理〉。制版指做印刷版面，修理坏掉的电器要用修理。"}, {"text": "她每天在厨房里制版饼干。", "explanation": "这里应该用〈烤〉。制版指制作印刷版面，烘烤饼干要用烤。"}, {"text": "他用木头制版了一把椅子。", "explanation": "这里应该用〈制作〉。制版专指做印刷用的版，做椅子要用制作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "炒", "is_correct": false, "explanation": "语义：“炒”用于菜肴等食物，菜单不能炒。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”一般用于食物，不说烤菜单。"}, {"text": "熬", "is_correct": false, "explanation": "语义：“熬”用于煮粥、煮药等，菜单不能熬。"}, {"text": "制版", "is_correct": true, "explanation": "正确。公司请他给菜单做印刷用的版，符合句中语境。"}], "explanations": {"炒": "语义：“炒”用于菜肴等食物，菜单不能炒。", "烤": "搭配：“烤”一般用于食物，不说烤菜单。", "熬": "语义：“熬”用于煮粥、煮药等，菜单不能熬。", "制版": "正确。公司请他给菜单做印刷用的版，符合句中语境。"}, "sentence_index": 6, "correct_answer": "制版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用毛线制版了一条围巾。", "explanation": "这里应该用〈编织〉。制版指做印刷版面，织围巾要用编织。"}, {"text": "这位工程师制版了一座新桥。", "explanation": "这里应该用〈设计〉。制版只用于印刷版面，设计桥梁要用设计。"}, {"text": "他用胶水制版了那只破杯子。", "explanation": "这里应该用〈修补〉。制版指制作印刷版面，修补破杯子要用修补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "编辑已经制版完了。", "corrected_sentence": "编辑已经制完版了。", "error_description": "“完”应紧接动词“制”，说“制完版”；说“制版完”把补语放到宾语之后，是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前制版过，现在也懂一些。", "corrected_sentence": "他以前制过版，现在也懂一些。", "error_description": "“过”应紧接动词“制”，说“制过版”；说“制版过”把“过”放到宾语之后，是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
