INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92547, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "似的是说这个东西好像那个东西。", "primary_collocate": null, "pronunciation": "sì de", "ipa": "sɹ̩˥˩ tə", "syllable_count": 2, "sentences": [{"text": "他高兴得像孩子似的。", "target_word": "似的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空蓝得像海似的。", "target_word": "似的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的脸红得像苹果似的。", "target_word": "似的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得像飞似的。", "target_word": "似的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的头发白得像雪似的。", "target_word": "似的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗像个孩子似的跟着我。", "target_word": "似的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天热得像夏天似的。", "target_word": "似的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手冰得像冰块似的。", "target_word": "似的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭得像泪人似的。", "target_word": "似的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里安静得像没有人似的。", "target_word": "似的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "用在比喻之后，说这个像那个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92547, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "似的", "is_correct": true, "explanation": "似的：用在比喻之后，表示“像孩子那样”。"}, {"text": "了", "is_correct": false, "explanation": "体貌：“了”表示完成，比喻结构之后不能接“了”。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”表示持续或状态，比喻结构之后不能接“着”。"}, {"text": "的", "is_correct": false, "explanation": "搭配：“得”引出的补语要用“似的”收尾，单用“的”不成立。"}], "explanations": {"似的": "似的：用在比喻之后，表示“像孩子那样”。", "了": "体貌：“了”表示完成，比喻结构之后不能接“了”。", "着": "体貌：“着”表示持续或状态，比喻结构之后不能接“着”。", "的": "搭配：“得”引出的补语要用“似的”收尾，单用“的”不成立。"}, "sentence_index": 0, "correct_answer": "似的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比哥哥似的高。", "explanation": "这里应该删去〈似的〉。“比”已表示比较，不能再接“似的”，说“他比哥哥高”即可。"}, {"text": "我喜欢似的苹果。", "explanation": "语序：“似的”须接在比喻成分之后，不能放在名词前，这里应删去“似的”。"}, {"text": "她的笑容比花似的灿烂。", "explanation": "这里应该删去〈似的〉。“比”已表示比较，不能再接“似的”，说“她的笑容比花还灿烂”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "似的", "is_correct": true, "explanation": "似的：用在比喻之后，表示“像夏天那样”。"}, {"text": "过", "is_correct": false, "explanation": "体貌：“过”表示经历，比喻结构之后不能接“过”。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”用来修饰动词，不能在比喻补语位置收尾。"}, {"text": "所", "is_correct": false, "explanation": "搭配：“所”只能用于“所＋动词”结构，不能接在比喻之后。"}], "explanations": {"似的": "似的：用在比喻之后，表示“像夏天那样”。", "过": "体貌：“过”表示经历，比喻结构之后不能接“过”。", "地": "搭配：“地”用来修饰动词，不能在比喻补语位置收尾。", "所": "搭配：“所”只能用于“所＋动词”结构，不能接在比喻之后。"}, "sentence_index": 6, "correct_answer": "似的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个杯子比那个似的大。", "explanation": "这里应该删去〈似的〉。“比”已表示比较，不能再接“似的”，说“这两个杯子比那个大”即可。"}, {"text": "书、笔似的很多。", "explanation": "这里应该用〈之类〉。“似的”表示像某物，不能直接充当列举，应说“书、笔之类的东西很多”。"}, {"text": "她的声音比银铃似的清脆。", "explanation": "这里应该删去〈似的〉。“比”已表示比较，不能再接“似的”，说“她的声音比银铃还清脆”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的眼睛亮像星星似的。", "corrected_sentence": "她的眼睛亮得像星星似的。", "error_description": "错误：“亮像星星似的”。正确：“亮得像星星似的”。“像……似的”作补语，前面的“亮”要用“得”连接，漏掉“得”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的声音像音乐一样似的，很好听。", "corrected_sentence": "他的声音像音乐似的，很好听。", "error_description": "错误在重复：“像……似的”已经是完整的比喻，再加“一样”重复表达，只用其一即可。正确说法是“像音乐似的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
