INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "传说中的百鸟之王，羽毛华丽。", "primary_collocate": null, "pronunciation": "fèng huáng", "ipa": "fɤŋ˥˩ xuɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "传说凤凰是百鸟之王。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凤凰的羽毛五颜六色，非常华丽。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人认为凤凰出现，是好事。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的衣服上绣着一只凤凰。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，凤凰是美好的象征。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说中，凤凰一飞，百鸟都跟着它。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她头上戴着凤凰形状的饰品。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凤凰和龙常常一起出现在婚礼上。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说凤凰在火里重生。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇后的衣服上常常有凤凰。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只凤凰", "label": "量词"}, {"form": "鳳凰", "label": "繁体"}], "register": "书面", "sense_fingerprint": "传说中的百鸟之王，象征吉祥与美好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a97372-e185-4f36-8342-f0d88b211b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凤凰", "is_correct": true, "explanation": "凤凰：传说中的百鸟之王，羽毛华丽。句中“百鸟之王”指的正是它。"}, {"text": "狮子", "is_correct": false, "explanation": "搭配：“狮子”与“百兽之王”搭配，不能说“百鸟之王”。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象不是鸟，不能称为百鸟之王。"}, {"text": "麻雀", "is_correct": false, "explanation": "语义：麻雀是普通小鸟，与“传说中”的百鸟之王相矛盾。"}], "explanations": {"凤凰": "凤凰：传说中的百鸟之王，羽毛华丽。句中“百鸟之王”指的正是它。", "狮子": "搭配：“狮子”与“百兽之王”搭配，不能说“百鸟之王”。", "大象": "语义：大象不是鸟，不能称为百鸟之王。", "麻雀": "语义：麻雀是普通小鸟，与“传说中”的百鸟之王相矛盾。"}, "sentence_index": 0, "correct_answer": "凤凰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的衣服上绣着一本凤凰。", "explanation": "这里应该用〈只〉。凤凰是鸟，计量鸟类用“只”，“本”用于书籍。"}, {"text": "妈妈在客厅里挂了一座凤凰。", "explanation": "这里应该用〈只〉。凤凰是鸟，计量鸟类用“只”，“座”多用于山、建筑等。"}, {"text": "我在草地上看到一匹凤凰。", "explanation": "这里应该用〈只〉。凤凰是鸟，计量鸟类用只，匹用于马等牲口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凤凰", "is_correct": true, "explanation": "凤凰：传说中的百鸟之王，羽毛华丽。“凤凰形状的饰品”指以它为样式的饰品。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子形状的饰品”不符合常见的饰品样式，句意不通。"}, {"text": "锅", "is_correct": false, "explanation": "语义：锅形状的头饰不符合常理，也与句中“戴着”的美感语境不符。"}, {"text": "地板", "is_correct": false, "explanation": "搭配：“地板”不能作为饰品的形状样式，与“头上戴着”搭配不当。"}], "explanations": {"凤凰": "凤凰：传说中的百鸟之王，羽毛华丽。“凤凰形状的饰品”指以它为样式的饰品。", "桌子": "语义：“桌子形状的饰品”不符合常见的饰品样式，句意不通。", "锅": "语义：锅形状的头饰不符合常理，也与句中“戴着”的美感语境不符。", "地板": "搭配：“地板”不能作为饰品的形状样式，与“头上戴着”搭配不当。"}, "sentence_index": 6, "correct_answer": "凤凰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古人在宫殿里养了一颗凤凰。", "explanation": "这里应该用〈只〉。凤凰是鸟，计量鸟类用“只”，“颗”用于粒状或球形的东西。"}, {"text": "妈妈在厨房里杀了一只凤凰，准备炖汤。", "explanation": "这里应该用〈鸡〉。凤凰是传说中的瑞鸟，不能宰杀炖汤；炖汤的家禽要说鸡。"}, {"text": "宫门口有一棵凤凰。", "explanation": "这里应该用〈只〉。凤凰是鸟，计量鸟类用“只”，“棵”用于树木。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在古代，那条凤凰象征吉祥。", "corrected_sentence": "在古代，那只凤凰象征吉祥。", "error_description": "量词用错：“凤凰”是鸟，应用量词“只”，不能用“条”（“条”用于细长的物件）。应为“那只凤凰象征吉祥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宫殿的墙上把画着一只凤凰。", "corrected_sentence": "宫殿的墙上画着一只凤凰。", "error_description": "“把”用错：“画”后直接接宾语，不需要“把”，应为“宫殿的墙上画着一只凤凰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
