INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92551, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "视察是到现场看看做得怎么样。", "primary_collocate": null, "pronunciation": "shì chá", "ipa": "ʂʐ̩⁵¹ ʈʂʰa³⁵", "syllable_count": 2, "sentences": [{"text": "经理明天要去工厂视察。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长上午视察了新学校。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板常到店里视察工作。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导正在视察新修的路。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们去视察过那个小村子。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长视察了每一个教室。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理视察完工地，就回公司了。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长下周来我们这里视察。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理亲自到车间视察生产。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板今天视察了三家分店。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "视察了", "label": "体标"}, {"form": "视察过", "label": "体标"}], "register": "书面", "sense_fingerprint": "视察：到现场看看做得怎么样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92551, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "视察", "is_correct": true, "explanation": "正确：视察，shì chá，指到现场察看做得怎么样。"}, {"text": "视差", "is_correct": false, "explanation": "chā（第一声）与 chá（第二声）声调不同，意思是视差（从两处看同一物体的方向差别）。"}, {"text": "时差", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）、chā（第一声）与 chá（第二声）声调都不同，意思是时差（两地的时间差别）。"}, {"text": "施茶", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是施茶（给过路人送茶）。"}], "explanations": {"视察": "正确：视察，shì chá，指到现场察看做得怎么样。", "视差": "chā（第一声）与 chá（第二声）声调不同，意思是视差（从两处看同一物体的方向差别）。", "时差": "shí（第二声）与 shì（第四声）、chā（第一声）与 chá（第二声）声调都不同，意思是时差（两地的时间差别）。", "施茶": "shī（第一声）与 shì（第四声）声调不同，意思是施茶（给过路人送茶）。"}, "sentence_index": null, "correct_answer": "视察"}, "level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：去工厂“睡觉”与出差去察看的目的不符，不合常理。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”需要带宾语，“去工厂喜欢”缺少宾语，句子不完整。"}, {"text": "视察", "is_correct": true, "explanation": "正确：视察指到现场察看工作，与“去工厂”搭配自然。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：工厂不是游泳的地方，“去工厂游泳”与句意不符。"}], "explanations": {"睡觉": "语义：去工厂“睡觉”与出差去察看的目的不符，不合常理。", "喜欢": "配价：“喜欢”需要带宾语，“去工厂喜欢”缺少宾语，句子不完整。", "视察": "正确：视察指到现场察看工作，与“去工厂”搭配自然。", "游泳": "语义：工厂不是游泳的地方，“去工厂游泳”与句意不符。"}, "sentence_index": 0, "correct_answer": "视察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小孩正在视察生日蛋糕。", "explanation": "这里应该用〈端详〉。视察指到现场看看做得怎么样，小孩看蛋糕要用“端详”。"}, {"text": "游客正在视察新开的公园。", "explanation": "这里应该用〈参观〉。视察指到现场看看做得怎么样，游客看景点要用“参观”。"}, {"text": "科学家正在视察新发现的岛屿。", "explanation": "这里应该用〈考察〉。视察指到现场看看做得怎么样，科学家实地调查岛屿要用“考察”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92551, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "视察", "is_correct": true, "explanation": "正确：视察，shì chá，指到现场察看做得怎么样。"}, {"text": "细茶", "is_correct": false, "explanation": "xì（第四声）与 shì 声母不同（x / sh），声调相同，意思是质地细嫩的茶。"}, {"text": "赐茶", "is_correct": false, "explanation": "cì（第四声）与 shì 声母不同（c / sh），声调相同，意思是把茶赐给别人。"}, {"text": "制茶", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），声调相同，意思是制茶（做茶）。"}], "explanations": {"视察": "正确：视察，shì chá，指到现场察看做得怎么样。", "细茶": "xì（第四声）与 shì 声母不同（x / sh），声调相同，意思是质地细嫩的茶。", "赐茶": "cì（第四声）与 shì 声母不同（c / sh），声调相同，意思是把茶赐给别人。", "制茶": "zhì 与 shì 声母不同（zh 与 sh），声调相同，意思是制茶（做茶）。"}, "sentence_index": null, "correct_answer": "视察"}, "level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：“喝工地”不通，工地不能喝。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“工地”作宾语。"}, {"text": "视察", "is_correct": true, "explanation": "正确：经理视察完工地，符合“就回公司了”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：工地不能吃，“吃完工地”与句意不符。"}], "explanations": {"喝": "语义：“喝工地”不通，工地不能喝。", "睡": "配价：“睡”是不及物动词，不能带“工地”作宾语。", "视察": "正确：经理视察完工地，符合“就回公司了”的语境。", "吃": "语义：工地不能吃，“吃完工地”与句意不符。"}, "sentence_index": 6, "correct_answer": "视察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "顾客今天视察了三家分店。", "explanation": "这里应该用〈光顾〉。视察指到现场看看做得怎么样，顾客到店里买东西要用“光顾”。"}, {"text": "学生今天视察了三家分店。", "explanation": "这里应该用〈参观〉。视察指到现场看看做得怎么样，学生去分店看看要用“参观”。"}, {"text": "妈妈今天视察了三家分店，买了两件衣服。", "explanation": "这里应该用〈逛〉。视察指到现场看看工作做得怎么样，妈妈去商店买衣服要用“逛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市长上午去学校视察着。", "corrected_sentence": "市长上午去学校视察了。", "error_description": "错误：“着”用错了。“上午”的动作已经完成，应用表示完成的“了”，应为“去学校视察了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "局长今天社区视察。", "corrected_sentence": "局长今天去社区视察。", "error_description": "错误：缺少“去”。“视察”前要有“去社区”表示去向，应为“去社区视察”，不能直接说“社区视察”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
