INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上级到下面去察看工作情况。", "primary_collocate": null, "pronunciation": "shì chá", "ipa": "ʂʐ̩⁵¹ ʈʂʰa³⁵", "syllable_count": 2, "sentences": [{"text": "省长下个月来我们县视察。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导到基层视察工作。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长视察了这家医院。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长昨天视察了农村的学校。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上级派人来视察我们的工作。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理到各地分公司视察。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导视察过很多村子。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厅长到山区视察教育工作。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长今天去社区视察。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书记视察了新建的水厂。", "target_word": "视察", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "视察了", "label": "体标"}, {"form": "视察过", "label": "体标"}], "register": "书面", "sense_fingerprint": "视察：上级到下面察看工作情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92552, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "视察", "is_correct": true, "explanation": "正确：视察，shì chá，指上级到下面察看工作情况。"}, {"text": "视差", "is_correct": false, "explanation": "chā（第一声）与 chá（第二声）声调不同，意思是视差（从两处看同一物体的方向差别）。"}, {"text": "时差", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）、chā（第一声）与 chá（第二声）声调都不同，意思是时差（两地的时间差别）。"}, {"text": "施茶", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是施茶（给过路人送茶）。"}], "explanations": {"视察": "正确：视察，shì chá，指上级到下面察看工作情况。", "视差": "chā（第一声）与 chá（第二声）声调不同，意思是视差（从两处看同一物体的方向差别）。", "时差": "shí（第二声）与 shì（第四声）、chā（第一声）与 chá（第二声）声调都不同，意思是时差（两地的时间差别）。", "施茶": "shī（第一声）与 shì（第四声）声调不同，意思是施茶（给过路人送茶）。"}, "sentence_index": null, "correct_answer": "视察"}, "level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：省长来县是为了工作，“来我们县游泳”与视察的目的不符。"}, {"text": "视察", "is_correct": true, "explanation": "正确：视察指上级到下面察看工作，与“省长下个月来我们县”相符。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”需要带宾语，“来我们县喜欢”缺少宾语，句子不完整。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：省长来县是为了工作，“来我们县放弃”与句意不符。"}], "explanations": {"游泳": "语义：省长来县是为了工作，“来我们县游泳”与视察的目的不符。", "视察": "正确：视察指上级到下面察看工作，与“省长下个月来我们县”相符。", "喜欢": "配价：“喜欢”需要带宾语，“来我们县喜欢”缺少宾语，句子不完整。", "放弃": "语义：省长来县是为了工作，“来我们县放弃”与句意不符。"}, "sentence_index": 0, "correct_answer": "视察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班昨天视察了农村的学校。", "explanation": "这里应该用〈参观〉。视察是上级到下面察看工作，学生去学校看看要用“参观”。"}, {"text": "记者昨天视察了农村的学校。", "explanation": "这里应该用〈访问〉。视察是上级察看工作，记者到学校采访要用“访问”。"}, {"text": "学生们昨天视察了农村的学校。", "explanation": "这里应该用〈调查〉。视察用于上级察看工作，学生了解学校情况要用“调查”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92552, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "视察", "is_correct": true, "explanation": "正确：视察，shì chá，指上级到下面察看工作情况。"}, {"text": "细茶", "is_correct": false, "explanation": "xì（第四声）与 shì 声母不同（x / sh），声调相同，意思是质地细嫩的茶。"}, {"text": "赐茶", "is_correct": false, "explanation": "cì（第四声）与 shì 声母不同（c / sh），声调相同，意思是把茶赐给别人。"}, {"text": "制茶", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），声调相同，意思是制茶（做茶）。"}], "explanations": {"视察": "正确：视察，shì chá，指上级到下面察看工作情况。", "细茶": "xì（第四声）与 shì 声母不同（x / sh），声调相同，意思是质地细嫩的茶。", "赐茶": "cì（第四声）与 shì 声母不同（c / sh），声调相同，意思是把茶赐给别人。", "制茶": "zhì 与 shì 声母不同（zh 与 sh），声调相同，意思是制茶（做茶）。"}, "sentence_index": null, "correct_answer": "视察"}, "level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：“喝过很多村子”不通，村子不能喝。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃过很多村子”不通，村子不能吃。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“很多村子”作宾语。"}, {"text": "视察", "is_correct": true, "explanation": "正确：视察过很多村子，符合领导下到基层察看工作的语境。"}], "explanations": {"喝": "语义：“喝过很多村子”不通，村子不能喝。", "吃": "语义：“吃过很多村子”不通，村子不能吃。", "哭": "配价：“哭”是不及物动词，不能带“很多村子”作宾语。", "视察": "正确：视察过很多村子，符合领导下到基层察看工作的语境。"}, "sentence_index": 6, "correct_answer": "视察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游客视察了新建的公园。", "explanation": "这里应该用〈游览〉。视察是上级察看工作，游客逛公园要用“游览”。"}, {"text": "顾客视察了新建的商场。", "explanation": "这里应该用〈光顾〉。顾客到商场买东西要用“光顾”，视察是上级察看工作。"}, {"text": "保安视察了新建的小区。", "explanation": "这里应该用〈巡查〉。保安在小区里巡逻检查要用“巡查”，视察是上级到下面察看工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCL