INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府、机关或团体向公众发布的正式通知。", "primary_collocate": null, "pronunciation": "gōng gào", "ipa": "kʊŋ˥ kaʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "市政府发布了一则公告。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公告说，下月起调整地铁票价。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校发出公告，提醒家长注意安全。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府的公告要求大家少开车。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行在网上发布公告，说明新规定。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份公告由公司正式发出。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公安局的公告提醒市民不要相信陌生电话。", "target_word": "公告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里的公告已经在报纸上登出来了。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司公告里说，这个月底会开大会。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车站发布公告，明天有些车次停开。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份公告", "label": "量词"}, {"form": "一则公告", "label": "量词"}, {"form": "公告栏", "label": "复合"}, {"form": "招标公告", "label": "复合"}], "register": "正式", "sense_fingerprint": "政府、机关或团体对公众正式发布的通知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1928561-c547-4f0d-a7bb-b100578bce76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公告", "is_correct": true, "explanation": "正确：“公告”是政府发布的正式通知，与“市政府发布了一则”搭配自然。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：政府不会发布笑话，与句中的“市政府”不相符。"}, {"text": "谣言", "is_correct": false, "explanation": "语义：政府不会发布谣言，与“发布”的正式语境相矛盾。"}, {"text": "小道消息", "is_correct": false, "explanation": "语域：“小道消息”是非正式的传闻，与政府正式发布的语境不符。"}], "explanations": {"公告": "正确：“公告”是政府发布的正式通知，与“市政府发布了一则”搭配自然。", "笑话": "语义：政府不会发布笑话，与句中的“市政府”不相符。", "谣言": "语义：政府不会发布谣言，与“发布”的正式语境相矛盾。", "小道消息": "语域：“小道消息”是非正式的传闻，与政府正式发布的语境不符。"}, "sentence_index": 0, "correct_answer": "公告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天照着公告做饭。", "explanation": "这里应该用〈菜谱〉。“公告”是正式通知，做饭要照着“菜谱”，不能用“公告”。"}, {"text": "孩子们在操场上玩公告。", "explanation": "这里应该用〈游戏〉。“公告”不能用于“玩”，孩子们在操场上玩的是“游戏”。"}, {"text": "他在冰箱上留了一张公告。", "explanation": "这里应该用〈便条〉。“公告”面向公众，给家人留言要用“便条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公告", "is_correct": true, "explanation": "正确：“公告”是面向公众的正式通知，适合用来提醒市民。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是消费或欠款的凭证，不用来提醒市民防骗。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱用于做菜，与提醒市民防骗无关。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单用于点餐，不用来提醒市民防骗。"}], "explanations": {"公告": "正确：“公告”是面向公众的正式通知，适合用来提醒市民。", "账单": "语义：账单是消费或欠款的凭证，不用来提醒市民防骗。", "食谱": "语义：食谱用于做菜，与提醒市民防骗无关。", "菜单": "语义：菜单用于点餐，不用来提醒市民防骗。"}, "sentence_index": 6, "correct_answer": "公告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写下了一份公告，把房子留给了儿子。", "explanation": "这里应该用〈遗嘱〉。“公告”面向公众，财产的安排要用“遗嘱”。"}, {"text": "他写了一首公告。", "explanation": "这里应该用〈诗〉。“公告”是正式通知，不是诗歌，不能说“写了一首公告”。"}, {"text": "他给我发了一条公告，说今晚一起吃饭。", "explanation": "这里应该用〈短信〉。“公告”面向公众，私人的约饭要用“短信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市教育局发布了一只公告。", "corrected_sentence": "市教育局发布了一则公告。", "error_description": "错误：“一只公告”。正确：“一则公告”。“只”多用于动物等，通知类的公告应该用量词“则”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电视台播出了一根公告。", "corrected_sentence": "电视台播出了一则公告。", "error_description": "错误：“一根公告”。正确：“一则公告”。“根”用于细长的东西，通知类的公告应该用量词“则”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
