INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92555, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里担心，坐不住。", "primary_collocate": null, "pronunciation": "bù ān", "ipa": "pu˥˩ an˥", "syllable_count": 2, "sentences": [{"text": "女儿还没回家，妈妈心里很不安。", "target_word": "不安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把事情做错了，心里一直不安。", "target_word": "不安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有收到他的信，我有点不安。", "target_word": "不安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想到明天的面试，她很不安。", "target_word": "不安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生还没出来，家人都很不安。", "target_word": "不安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不安地看着手机，等朋友的电话。", "target_word": "不安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师还没公布成绩，大家都有些不安。", "target_word": "不安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这件事一直感到不安。", "target_word": "不安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，爸爸还没回来，我很不安。", "target_word": "不安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不安地站在门口，不知道怎么办。", "target_word": "不安", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "心里担心、着急，坐立不定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad1d3580-2f81-4f34-89f3-d63ae05c6f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92555, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不安", "is_correct": true, "explanation": "正确：“心里很不安”指心里担心、坐不住，与“还没回家”的语境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”与“女儿还没回家”的担心语境冲突。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不说心里很热情。"}, {"text": "严肃", "is_correct": false, "explanation": "搭配：“严肃”形容神情或态度，不用来描述心里的感受。"}], "explanations": {"不安": "正确：“心里很不安”指心里担心、坐不住，与“还没回家”的语境相符。", "高兴": "语义：“高兴”与“女儿还没回家”的担心语境冲突。", "热情": "搭配：“热情”形容人的态度，不说心里很热情。", "严肃": "搭配：“严肃”形容神情或态度，不用来描述心里的感受。"}, "sentence_index": 0, "correct_answer": "不安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件新毛衣穿在身上很不安，又软又暖和。", "explanation": "这里应该用〈舒服〉。不安形容人心里担心、坐不住，衣物穿着的感受要说舒服。"}, {"text": "孩子已经平安到家，妈妈终于很不安了。", "explanation": "这里应该用〈放心〉。不安表示担心，孩子平安到家后应说放心。"}, {"text": "听到录取的消息，她很不安。", "explanation": "这里应该用〈欣喜〉。不安表示心里忐忑，得知录取这类好消息要说欣喜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不安", "is_correct": true, "explanation": "正确：“大家都有些不安”指大家都心里担心，与“还没公布成绩”相符。"}, {"text": "慷慨", "is_correct": false, "explanation": "搭配：“慷慨”形容人的品格，不用来形容大家的心情。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能形容人的心情。"}, {"text": "奔放", "is_correct": false, "explanation": "搭配：“奔放”形容风格或性格，不用来描述此时的心情。"}], "explanations": {"不安": "正确：“大家都有些不安”指大家都心里担心，与“还没公布成绩”相符。", "慷慨": "搭配：“慷慨”形容人的品格，不用来形容大家的心情。", "清脆": "语义：“清脆”形容声音，不能形容人的心情。", "奔放": "搭配：“奔放”形容风格或性格，不用来描述此时的心情。"}, "sentence_index": 6, "correct_answer": "不安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他陶醉在音乐里，不安地闭着眼睛。", "explanation": "这里应该用〈放松〉。不安表示坐立难安、心神不定，闭眼沉浸在音乐里的神态要说放松。"}, {"text": "他对结果很不安，心里有很大的把握。", "explanation": "这里应该用〈放心〉。不安表示没有把握、心神不定，对结果有把握、心里踏实要说放心。"}, {"text": "这条河的宽度很不安。", "explanation": "这里应该用〈宽阔〉。不安形容人心里忐忑、坐不住，河面的宽窄不能用它来说，要说宽阔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不安的等在医院门口，没有说话。", "corrected_sentence": "我不安地等在医院门口，没有说话。", "error_description": "错误在“的”。“不安”在这里作状语修饰动词“等”，应用“地”，不能用“的”。应说“我不安地等在医院门口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一种不安地情绪，一直坐不住。", "corrected_sentence": "他有一种不安的情绪，一直坐不住。", "error_description": "错误在“不安”后的“地”。“不安”在这里修饰名词“情绪”，应用“的”，不能用“地”。应说“一种不安的情绪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
