INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92557, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "订单是写着你要买什么的单子。", "primary_collocate": null, "pronunciation": "dìng dān", "ipa": "tiŋ⁵¹ tan⁵⁵", "syllable_count": 2, "sentences": [{"text": "我在网上下了一个订单。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "订单上写着三本书和两支笔。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看一下订单上的名字。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张订单是昨天下的。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店收到订单后，就会送货。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把订单放在桌子上了。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "订单上的地址写错了。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在订单上多写了一杯茶。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我看了她的订单。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "订单的右上角有一个号码。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "订单号", "label": "复合"}, {"form": "訂單", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写着要买什么东西的单子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5538bf12-020f-423d-a46d-0a1f06c15aac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菜单", "is_correct": false, "explanation": "搭配：“下”用于订单，网上点菜一般说点菜，不说下菜单。"}, {"text": "订单", "is_correct": true, "explanation": "正确。“下订单”即在网上提交购买清单，符合句中语境。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：账单是收费通知，不能“下”，应说“开”账单。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历记录病情，与网上购买东西无关。"}], "explanations": {"菜单": "搭配：“下”用于订单，网上点菜一般说点菜，不说下菜单。", "订单": "正确。“下订单”即在网上提交购买清单，符合句中语境。", "账单": "搭配：账单是收费通知，不能“下”，应说“开”账单。", "病历": "语义：病历记录病情，与网上购买东西无关。"}, "sentence_index": 0, "correct_answer": "订单"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我拿着这张订单坐上了火车。", "explanation": "这里应该用〈车票〉。订单是买东西时下的单据，坐火车要用车票。"}, {"text": "他吃了一份订单。", "explanation": "订单是买东西时下的单据，不是食物，不能用“吃”；这里应该说“下”订单。"}, {"text": "这张订单写着我这个月用了多少电。", "explanation": "这里应该用〈账单〉。订单是买东西时下的单据，记录用电金额要用账单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐", "is_correct": false, "explanation": "语义：音乐是听的，上面不能写地址，不说“音乐上的地址”。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词是歌曲的内容，不会写地址。"}, {"text": "订单", "is_correct": true, "explanation": "正确。订单是写有购买信息的单据，上面可以写地址，符合句中语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不是能写字的东西，不说“天气上的地址”。"}], "explanations": {"音乐": "语义：音乐是听的，上面不能写地址，不说“音乐上的地址”。", "歌词": "语义：歌词是歌曲的内容，不会写地址。", "订单": "正确。订单是写有购买信息的单据，上面可以写地址，符合句中语境。", "天气": "搭配：“天气”不是能写字的东西，不说“天气上的地址”。"}, "sentence_index": 6, "correct_answer": "订单"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张订单记录了我的身高和体重。", "explanation": "这里应该用〈体检表〉。订单是买东西时下的单据，记录身高体重要用体检表。"}, {"text": "他生病了，写了一张订单给老师，明天不能来上课。", "explanation": "这里应该用〈请假条〉。写给老师请假要用请假条，订单是买东西时下的单据。"}, {"text": "班主任发了一张订单给家长，说明明天要开家长会。", "explanation": "这里应该用〈通知〉。订单是买东西时下的单据，告知开会的事要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在网上下了一只订单。", "corrected_sentence": "我昨天在网上下了一张订单。", "error_description": "量词错误：订单是纸质单据，应说“一张订单”，不说“一只订单”（“只”多用于动物、成对器官等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些订单们都在桌子上。", "corrected_sentence": "这些订单都在桌子上。", "error_description": "“们”只用于指人，不能加在“订单”后面，应说“这些订单”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
