INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92558, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "买卖双方约定的订货单据。", "primary_collocate": null, "pronunciation": "dìng dān", "ipa": "tiŋ⁵¹ tan⁵⁵", "syllable_count": 2, "sentences": [{"text": "公司和客户签了一份订单。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂今年接到了很多订单。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份订单要在下个月交货。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "订单上写着价格和数量。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板对着订单检查了货物。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们取消了那份订单。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为订单太多，工人天天加班。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户的订单昨天发到了公司。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张订单一共要一千件衣服。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在看新来的订单。", "target_word": "订单", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "订单号", "label": "复合"}, {"form": "訂單", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买卖双方约定订货的单据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5538bf12-020f-423d-a46d-0a1f06c15aac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报纸", "is_correct": false, "explanation": "搭配：“签”用于合同、文件，报纸应说“订”，不说签报纸。"}, {"text": "订单", "is_correct": true, "explanation": "正确。买卖双方签约确认的订货单据，符合句中语境。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“签”指签字，蛋糕不能签，也不是约定单据。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送人的东西，不是双方签字确认的单据。"}], "explanations": {"报纸": "搭配：“签”用于合同、文件，报纸应说“订”，不说签报纸。", "订单": "正确。买卖双方签约确认的订货单据，符合句中语境。", "蛋糕": "语义：“签”指签字，蛋糕不能签，也不是约定单据。", "礼物": "语义：礼物是送人的东西，不是双方签字确认的单据。"}, "sentence_index": 0, "correct_answer": "订单"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张订单写着他的各科分数。", "explanation": "这里应该用〈成绩单〉。订单是买卖双方约定的订货单据，记录分数要用成绩单。"}, {"text": "他写了一张订单，向朋友借了五百元。", "explanation": "这里应该用〈借条〉。借钱要写借条，订单是买卖双方约定的订货单据。"}, {"text": "医生给他开了一张订单，让他去药房拿药。", "explanation": "这里应该用〈药方〉。医生开的取药单据是药方，订单是买卖双方约定的订货单据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气多不会让工人加班，句中因果关系说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气好坏与工人天天加班没有因果关系，句意说不通。"}, {"text": "订单", "is_correct": true, "explanation": "正确。订单多，工人就要天天加班，符合句中因果关系。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情多与工人加班之间没有因果关系。"}], "explanations": {"空气": "语义：空气多不会让工人加班，句中因果关系说不通。", "天气": "语义：天气好坏与工人天天加班没有因果关系，句意说不通。", "订单": "正确。订单多，工人就要天天加班，符合句中因果关系。", "感情": "语义：感情多与工人加班之间没有因果关系。"}, "sentence_index": 6, "correct_answer": "订单"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿着订单进了电影院看电影。", "explanation": "这里应该用〈电影票〉。进电影院要用电影票，订单是买卖双方约定的订货单据。"}, {"text": "妈妈给亲戚寄了一张订单，邀请他们参加婚礼。", "explanation": "这里应该用〈请帖〉。请帖是邀请客人的卡片，邀请亲戚参加婚礼要用请帖，订单是买卖双方约定的订货单据。"}, {"text": "老师在订单上写下了学生的考试分数。", "explanation": "这里应该用〈成绩单〉。记录分数要用成绩单，订单是买卖双方约定的订货单据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些订单们都已经发出了。", "corrected_sentence": "这些订单都已经发出了。", "error_description": "“们”只用于指人，不能加在“订单”后面，应说“这些订单”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司昨天收到了一只订单。", "corrected_sentence": "我们公司昨天收到了一份订单。", "error_description": "量词错误：订单应说“一份订单”，不说“一只订单”（“只”不用于单据）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
