INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92559, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "再度是又一次。", "primary_collocate": null, "pronunciation": "zài dù", "ipa": "tsai˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司去年破产，今年再度开张。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一个冬天，花园里再度开满了鲜花。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在比赛中再度受伤，只好退出。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位老朋友在机场再度相遇。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，大家再度回到工作岗位。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，村子再度安静下来。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她再度打开那封信，认真地读了一遍。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市再度成为旅游热点。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话再度响起，他连忙跑去接。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，太阳再度出现在天空中。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "副词，表示同一件事又发生一次，多用于书面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a1638f-b64a-4caa-8649-66c87ab87a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再度", "is_correct": true, "explanation": "再度：又一次，符合“去年破产、今年又一次开张”的语境。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有，与“去年破产、今年又一次开张”的语境相反。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“破产后又一次开张”的转折不符。"}, {"text": "曾经", "is_correct": false, "explanation": "搭配：“曾经”指过去发生过，与“今年”的时间背景不搭。"}], "explanations": {"再度": "再度：又一次，符合“去年破产、今年又一次开张”的语境。", "从未": "语义：“从未”表示从来没有，与“去年破产、今年又一次开张”的语境相反。", "一直": "语义：“一直”表示持续不断，与“破产后又一次开张”的转折不符。", "曾经": "搭配：“曾经”指过去发生过，与“今年”的时间背景不搭。"}, "sentence_index": 0, "correct_answer": "再度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是他第一次再度参加比赛。", "explanation": "这里应该用〈首次〉。“再度”表示又一次，前面必须已经发生过同样的事；他是第一次参加，应说“首次参加”。"}, {"text": "他第一次去上海，就再度游览了外滩。", "explanation": "这里应该用〈首次〉。“再度”表示又一次，之前必须已经去过；他是第一次去上海，应说“首次游览”或直接说“游览”。"}, {"text": "她刚学会骑车，又再度学会了游泳。", "explanation": "这里应该用〈又〉。“再度”表示又一次做同样的事，学会骑车和学会游泳不是同一件事，不能用“再度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再度", "is_correct": true, "explanation": "再度：又一次，符合“前面已经打开过一次”的语境。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有，与“打开那封信，认真地读了一遍”的已发生动作矛盾。"}, {"text": "还没", "is_correct": false, "explanation": "语义：“还没”表示尚未发生，与“读了一遍”已经发生的动作矛盾。"}, {"text": "始终", "is_correct": false, "explanation": "搭配：“始终”表示一直如此，与“打开那封信”这种一次性动作搭配不当。"}], "explanations": {"再度": "再度：又一次，符合“前面已经打开过一次”的语境。", "从未": "语义：“从未”表示从来没有，与“打开那封信，认真地读了一遍”的已发生动作矛盾。", "还没": "语义：“还没”表示尚未发生，与“读了一遍”已经发生的动作矛盾。", "始终": "搭配：“始终”表示一直如此，与“打开那封信”这种一次性动作搭配不当。"}, "sentence_index": 6, "correct_answer": "再度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他比昨天再度努力了。", "explanation": "这里应该用〈更〉。“再度”只表示又一次重复，不表示程度的加深；比较程度要用“更”。"}, {"text": "他会说英语，再度会说法语。", "explanation": "这里应该用〈也〉。“再度”表示又一次，不表示并列补充，补充要用“也”。"}, {"text": "他没有吃饭，却再度去吃饭了。", "explanation": "这里应去掉〈再度〉，说“他还没吃饭，就去吃饭了”。“再度”表示又一次，前面必须已经有过相同的动作，而这里他之前并没有吃过饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停后，他再度一次出门散步。", "corrected_sentence": "雨停后，他再度出门散步。", "error_description": "数量词错误：“再度”已表示“又一次”，后面不能再加“一次”，应说“再度出门散步”，“再度一次”属于重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座古城再度的成为游客的焦点。", "corrected_sentence": "这座古城再度成为游客的焦点。", "error_description": "修饰错误：“再度”是副词，修饰动词“成为”时后面不能加“的”，应说“再度成为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
