INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92560, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，再一次；第二次。", "primary_collocate": null, "pronunciation": "zài dù", "ipa": "tsai˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "他们在北京再度见面，都很高兴。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师再度提醒大家按时交作业。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济危机过后，物价再度上涨。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手再度获得了音乐奖。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明年将再度来到这里旅行。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再度失败，但是没有放弃。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生再度检查了病人的身体。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的冠军今年再度夺冠。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，小鸟再度飞回北方。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她再度站在舞台上，心情很激动。", "target_word": "再度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "副词，再一次、第二次，修饰动作或变化的重复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a1638f-b64a-4caa-8649-66c87ab87a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再度", "is_correct": true, "explanation": "再度：又一次，符合“再一次见面、都很高兴”的语境。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示没有过，与“再一次见面”的前提矛盾。"}, {"text": "不再", "is_correct": false, "explanation": "语义：“不再”表示停止，与“再一次见面”的重复义相反，与“都很高兴”的语境也不合。"}, {"text": "尚未", "is_correct": false, "explanation": "语义：“尚未”表示还没有发生，与“再一次见面”的前提矛盾。"}], "explanations": {"再度": "再度：又一次，符合“再一次见面、都很高兴”的语境。", "从未": "语义：“从未”表示没有过，与“再一次见面”的前提矛盾。", "不再": "语义：“不再”表示停止，与“再一次见面”的重复义相反，与“都很高兴”的语境也不合。", "尚未": "语义：“尚未”表示还没有发生，与“再一次见面”的前提矛盾。"}, "sentence_index": 0, "correct_answer": "再度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们第一次去爬山，就再度爬上了山顶。", "explanation": "这里应该用〈首次〉。“再度”表示又一次，前面必须已经做过同样的事；第一次爬山不能说“再度爬上”。"}, {"text": "这是他第一次再度获奖。", "explanation": "这里应该用〈首次〉。“再度”表示又一次获奖，前面要有过获奖的经历；他是第一次获奖，应说“首次获奖”。"}, {"text": "他今年刚开始学汉语，这是他再度学习外语。", "explanation": "这里应该用〈第一次〉。“再度”表示又一次，前面必须已经有过同样的经历；他刚开始学外语，是第一次，不能说“再度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再度", "is_correct": true, "explanation": "再度：又一次，符合“医生又一次检查病人”的语境。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有，与“检查了”这一已发生的动作矛盾。"}, {"text": "还没", "is_correct": false, "explanation": "语义：“还没”表示尚未，与“检查了”已完成的动作矛盾。"}, {"text": "始终", "is_correct": false, "explanation": "搭配：“始终”表示持续，与“检查了”这一次性动作不搭配。"}], "explanations": {"再度": "再度：又一次，符合“医生又一次检查病人”的语境。", "从未": "语义：“从未”表示从来没有，与“检查了”这一已发生的动作矛盾。", "还没": "语义：“还没”表示尚未，与“检查了”已完成的动作矛盾。", "始终": "搭配：“始终”表示持续，与“检查了”这一次性动作不搭配。"}, "sentence_index": 6, "correct_answer": "再度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他比上次再度考得好。", "explanation": "这里应该用〈更〉。“再度”只表示又一次重复，不表示程度的加深；比较程度要用“更”。"}, {"text": "我会弹钢琴，再度会唱歌。", "explanation": "这里应该用〈也〉。表示并列补充要用“也”，“再度”不表示补充。"}, {"text": "我从来没去过上海，明年将再度去上海。", "explanation": "这里应该用〈第一次〉。“再度”表示又一次，但“从来没去过”说明以前没去过，应说“明年将第一次去上海”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的生意再度一次好起来了。", "corrected_sentence": "这家店的生意再度好起来了。", "error_description": "数量词错误：“再度”已表示“又一次”，后面不能再加“一次”，应说“再度好起来”，“再度一次”属于重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师再度的站在讲台上讲课。", "corrected_sentence": "老师再度站在讲台上讲课。", "error_description": "修饰错误：“再度”修饰动词“站”时后面不能加“的”，应说“再度站在讲台上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
