INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92561, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语气是说话时的口气，听起来的感觉。", "primary_collocate": null, "pronunciation": "yǔ qì", "ipa": "y˨˩˦ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "他说话的语气很温柔。", "target_word": "语气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听他的语气，他好像不太高兴。", "target_word": "语气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用很严肃的语气跟我们说话。", "target_word": "语气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别用这种语气跟妈妈说话。", "target_word": "语气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的语气让我觉得很舒服。", "target_word": "语气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话里，他的语气听起来很着急。", "target_word": "语气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同样一句话，语气不同，意思也不一样。", "target_word": "语气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直用开玩笑的语气说这件事。", "target_word": "语气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听出了她语气里有一点儿生气。", "target_word": "语气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把语气放轻一点儿，孩子会害怕的。", "target_word": "语气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种语气", "label": "量词"}, {"form": "语气词", "label": "复合词"}], "register": "中性", "sense_fingerprint": "说话时的口气，听者感受到的态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8eeb9b7-da00-4ad1-a443-5d1569c7e006') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92561, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "玉器", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，玉器指玉制的器物。"}, {"text": "语气", "is_correct": true, "explanation": "正确：语气（yǔqì）指说话时的口气。"}, {"text": "预期", "is_correct": false, "explanation": "yǔ 与 yù、qì 与 qī 两处声调都不同（第四声、第一声），预期指事先的期望。"}, {"text": "语系", "is_correct": false, "explanation": "qì 与 xì 声母不同（q 与 x），声调都是第四声；语系指语言的系属。"}, {"text": "雨季", "is_correct": false, "explanation": "qì 与 jì 声母不同（q 与 j），声调相同；雨季指雨水多的季节。"}], "explanations": {"玉器": "yǔ（第三声）与 yù（第四声）声调不同，玉器指玉制的器物。", "语气": "正确：语气（yǔqì）指说话时的口气。", "预期": "yǔ 与 yù、qì 与 qī 两处声调都不同（第四声、第一声），预期指事先的期望。", "语系": "qì 与 xì 声母不同（q 与 x），声调都是第四声；语系指语言的系属。", "雨季": "qì 与 jì 声母不同（q 与 j），声调相同；雨季指雨水多的季节。"}, "sentence_index": null, "correct_answer": "语气"}, "level_3": {"options": [{"text": "音量", "is_correct": false, "explanation": "搭配：“音量”说声音的大小，不说“温柔”，“他说话的音量很温柔”不成立。"}, {"text": "语气", "is_correct": true, "explanation": "正确：“语气”指说话的口气，能与“说话的”和“温柔”搭配。"}, {"text": "语法", "is_correct": false, "explanation": "语义：“语法”指语言的规则，与说话的感觉无关，不能是“温柔”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形特征，不能用来描述说话的样子。"}], "explanations": {"音量": "搭配：“音量”说声音的大小，不说“温柔”，“他说话的音量很温柔”不成立。", "语气": "正确：“语气”指说话的口气，能与“说话的”和“温柔”搭配。", "语法": "语义：“语法”指语言的规则，与说话的感觉无关，不能是“温柔”。", "身高": "体貌：“身高”是人的外形特征，不能用来描述说话的样子。"}, "sentence_index": 0, "correct_answer": "语气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的语气很标准。", "explanation": "这里应该用〈语音〉。“标准”说的是发音，语气指说话时的口气，不能说“语气很标准”。"}, {"text": "他会说三种语气。", "explanation": "这里应该用〈语言〉。“会说”后面接的是语言，语气指说话时的口气，不能说“会说三种语气”。"}, {"text": "这幅画的语气很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，语气指说话时的口气和感情，不能用“鲜艳”来形容语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92561, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "与其", "is_correct": false, "explanation": "yǔqì 与 yǔqí 的第二个音节声调不同（第四声与第二声）；与其是连词，意思是“与其……不如……”。"}, {"text": "语气", "is_correct": true, "explanation": "正确：语气（yǔqì）指说话时的口气。"}, {"text": "雨期", "is_correct": false, "explanation": "qì（第四声）与 qī（第一声）声调不同，雨期指下雨的时期。"}, {"text": "武器", "is_correct": false, "explanation": "yǔ 与 wǔ 声母不同（y 与 w），声调都是第三声；武器指作战用的器械。"}], "explanations": {"与其": "yǔqì 与 yǔqí 的第二个音节声调不同（第四声与第二声）；与其是连词，意思是“与其……不如……”。", "语气": "正确：语气（yǔqì）指说话时的口气。", "雨期": "qì（第四声）与 qī（第一声）声调不同，雨期指下雨的时期。", "武器": "yǔ 与 wǔ 声母不同（y 与 w），声调都是第三声；武器指作战用的器械。"}, "sentence_index": null, "correct_answer": "语气"}, "level_3": {"options": [{"text": "字数", "is_correct": false, "explanation": "语义：“同样一句话”说明字数相同，不能说“字数不同”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与一句话的意思无关，“颜色不同，意思也不一样”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的身体特征，不能用来说明一句话的不同。"}, {"text": "语气", "is_correct": true, "explanation": "正确：“语气”指说话的口气，同样的话语气不同，意思就不同。"}], "explanations": {"字数": "语义：“同样一句话”说明字数相同，不能说“字数不同”。", "颜色": "语义：颜色与一句话的意思无关，“颜色不同，意思也不一样”不成立。", "体重": "体貌：体重是人的身体特征，不能用来说明一句话的不同。", "语气": "正确：“语气”指说话的口气，同样的话语气不同，意思就不同。"}, "sentence_index": 6, "correct_answer": "语气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感冒了，语气很哑。", "explanation": "这里应该用〈嗓音〉。“哑”形容嗓子或声音发不出清亮的声音，语气指说话时的口气和感情，不能用“哑”来形容语气。"}, {"text": "这碗汤的语气很咸。", "explanation": "这里应该用〈味道〉。“咸”形容食物的味道，语气指说话时的口气和感情，不能用“咸”来形容语气。"}, {"text": "这块布的语气很粗糙。", "explanation": "这里应该用〈质地〉。“粗糙”形容物体表面的质地，语气指说话时的口气和感情，不能用“粗糙”来形容语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用一只很温和的语气跟我说话。", "corrected_sentence": "她用一种很温和的语气跟我说话。", "error_description": "量词用错：“语气”应用量词“种”，不能用“只”。应说“一种很温和的语气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用很温柔地语气跟孩子说话。", "corrected_sentence": "她用很温柔的语气跟孩子说话。", "error_description": "错误：“温柔地语气”，正确：“温柔的语气”。修饰名词“语气”应该用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
