INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92566, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使用语言听、说、读、写的能力。", "primary_collocate": null, "pronunciation": "yǔ yán néng lì", "ipa": "y˨˩˦ jɛn˧˥ nɤŋ˧˥ li˥˩", "syllable_count": 4, "sentences": [{"text": "学外语可以提高听说读写的语言能力。", "target_word": "语言能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个考试主要测试学生的语言能力。", "target_word": "语言能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书、多写作能提高语言能力。", "target_word": "语言能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国生活一年，他的语言能力进步很快。", "target_word": "语言能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司招人时很重视语言能力。", "target_word": "语言能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的语言能力比去年强多了。", "target_word": "语言能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想提高语言能力，每天都要练习听和说。", "target_word": "语言能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的语言能力很强，会说四种语言。", "target_word": "语言能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看英文电影有助于提高听力和语言能力。", "target_word": "语言能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种课程重点培养学生的语言能力。", "target_word": "语言能力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "語言能力", "label": "繁体"}, {"form": "语言能力测试", "label": "复合"}], "register": "中性", "sense_fingerprint": "听说读写运用语言的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df752ed1-047e-4fbd-b779-b0ded6150625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语言能力", "is_correct": true, "explanation": "语言能力指听说读写运用语言的能力，与“提高”搭配，填入后句意通顺。"}, {"text": "体力", "is_correct": false, "explanation": "语义：“体力”指身体的力量，与听说读写的能力无关。"}, {"text": "视力", "is_correct": false, "explanation": "语义：“视力”指眼睛看清东西的能力，与听说读写无关。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“提高”不与“距离”搭配，应说“缩短距离”。"}], "explanations": {"语言能力": "语言能力指听说读写运用语言的能力，与“提高”搭配，填入后句意通顺。", "体力": "语义：“体力”指身体的力量，与听说读写的能力无关。", "视力": "语义：“视力”指眼睛看清东西的能力，与听说读写无关。", "距离": "搭配：“提高”不与“距离”搭配，应说“缩短距离”。"}, "sentence_index": 0, "correct_answer": "语言能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车的语言能力很好，一小时能跑一百公里。", "explanation": "这里应该用〈性能〉。语言能力指人听说读写的本领，汽车跑得快说的是〈性能〉。"}, {"text": "这台冰箱的语言能力很强，能自动调节温度。", "explanation": "这里应该用〈温控功能〉。语言能力指人听说读写语言的本领，冰箱调节温度应说〈温控功能〉。"}, {"text": "这个司机的语言能力很强，能躲开突然出现的车。", "explanation": "这里应该用〈反应能力〉。语言能力指听说读写的本领，躲车靠的是〈反应能力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语言能力", "is_correct": true, "explanation": "语言能力是运用语言的能力，“要想提高语言能力，每天都要练习听和说”句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高度，与练习听和说无关。"}, {"text": "房价", "is_correct": false, "explanation": "语义：“房价”指房屋的售价，与练习听和说毫无关系。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“提高”多用于能力、水平等正面事物，“噪音”一般不说“提高”。"}], "explanations": {"语言能力": "语言能力是运用语言的能力，“要想提高语言能力，每天都要练习听和说”句意通顺。", "身高": "语义：“身高”指身体的高度，与练习听和说无关。", "房价": "语义：“房价”指房屋的售价，与练习听和说毫无关系。", "噪音": "搭配：“提高”多用于能力、水平等正面事物，“噪音”一般不说“提高”。"}, "sentence_index": 6, "correct_answer": "语言能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她有一条很强的语言能力，能用三种语言写作。", "explanation": "这里“条”用错了。“条”用于细长的事物，不能用来计量“语言能力”这样的抽象能力。"}, {"text": "这栋大楼的语言能力很好，能接待各国客人。", "explanation": "这里应该用〈服务水平〉。语言能力指人听说读写的本领，大楼的水平应说〈服务水平〉。"}, {"text": "他的语言能力很强，每天能跑十公里。", "explanation": "这里应该用〈体能〉。语言能力指听说读写语言的本领，跑步靠的是〈体能〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐的语言能力很多。", "corrected_sentence": "我姐姐的语言能力很强。", "error_description": "错误：搭配不当。“语言能力”说强弱、高低，不能说“很多”，应为“语言能力很强”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的语言能力很高大，会说四种语言。", "corrected_sentence": "她的语言能力很强，会说四种语言。", "error_description": "错误：搭配不当。“高大”形容身材或建筑，不能形容“语言能力”。语言能力应说强弱、高低，所以要说“语言能力很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "添加", "is_correct": true, "explanation": "添加：与“删除”相反，指把字词加进去。"}, {"text": "打开", "is_correct": false, "explanation": "打开：指使内容可见，与“删除”没有反义关系。"}, {"text": "浏览", "is_correct": false, "explanation": "浏览：指快速看一看，与“删除”没有反义关系。"}, {"text": "复制", "is_correct": false, "explanation": "复制：指做出一份相同的内容，不是“删除”的反义词。"}], "correct_answer": "添加", "explanations": {"添加": "添加：与“删除”相反，指把字词加进去。", "打开": "打开：指使内容可见，与“删除”没有反义关系。", "浏览": "浏览：指快速看一看，与“删除”没有反义关系。", "复制": "复制：指做出一份相同的内容，不是“删除”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "添加", "is_correct": true, "explanation": "添加：与“删除”相反，指把字词加进去。"}, {"text": "查找", "is_correct": false, "explanation": "查找：指寻找，与“删除”没有反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译：指换成另一种语言，与“删除”没有反义关系。"}, {"text": "核对", "is_correct": false, "explanation": "核对：指比较检查，与“删除”没有反义关系。"}], "correct_answer": "添加", "explanations": {"添加": "添加：与“删除”相反，指把字词加进去。", "查找": "查找：指寻找，与“删除”没有反义关系。", "翻译": "翻译：指换成另一种语言，与“删除”没有反义关系。", "核对": "核对：指比较检查，与“删除”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "删除是把不要的字去掉。", "primary_collocate": null, "pronunciation": "shān chú", "ipa": "ʂan˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "请把这个字删除。", "target_word": "删除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我删除这句话。", "target_word": "删除", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "句子里没用的词，要删除。", "target_word": "删除", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把多写的两个字删除了。", "target_word": "删除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话太长，请删除几个字。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明写多了，就把多余的字删除。", "target_word": "删除", "complexity_tier": "T3", "furigana": "xiǎo míng xiě duō le， jiù bǎ duō yú de zì shān chú。", "sentence_source": "generated"}, {"text": "这句话没有用，我删除了它。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把重复的字都删除。", "target_word": "删除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章时，多余的词要删除。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看了一遍，删除了三个字。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "删除了", "label": "体标"}, {"form": "删除过", "label": "体标"}, {"form": "刪除", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把文章里多余、不要的字词去掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36673f00-f0bc-43d7-a615-18caeb0a4ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "删除", "is_correct": true, "explanation": "删除：去掉这个多余的字，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象须是食物，“字”不能吃。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”后要带处所，如“放在……”，句子里没有地点。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量或程度的变化，不能说把一个字“增加”。"}], "explanations": {"删除": "删除：去掉这个多余的字，符合句意。", "吃": "语义：“吃”的对象须是食物，“字”不能吃。", "放": "配价：“放”后要带处所，如“放在……”，句子里没有地点。", "增加": "搭配：“增加”说数量或程度的变化，不能说把一个字“增加”。"}, "sentence_index": 0, "correct_answer": "删除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把汤里的葱删除了。", "explanation": "这里应该用〈去掉〉。删除用于字词，不用于食材，汤里的葱要说去掉。"}, {"text": "他把地上的垃圾删除了。", "explanation": "这里应该用〈扔掉〉。删除用于字词，不用于实物，地上的垃圾要说扔掉。"}, {"text": "他把坏掉的旧雨伞删除了。", "explanation": "这里应该用〈丢掉〉。删除用于字词，不用于实物，坏掉的旧雨伞要说丢掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "删除", "is_correct": true, "explanation": "删除：去掉这句话，符合“没有用”的语境。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，“它”指一句话，不能喝。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”用于人或作品的优点，与“没有用”的评价矛盾。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”的对象是人或动物，不能拥抱一句话。"}], "explanations": {"删除": "删除：去掉这句话，符合“没有用”的语境。", "喝": "语义：“喝”的对象是液体，“它”指一句话，不能喝。", "赞美": "搭配：“赞美”用于人或作品的优点，与“没有用”的评价矛盾。", "拥抱": "语义：“拥抱”的对象是人或动物，不能拥抱一句话。"}, "sentence_index": 6, "correct_answer": "删除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我删除了那只小猫。", "explanation": "这里删除被当作“让某个生物消失”的意思来用，但删除只指去掉字词或数据，不能用于动物。"}, {"text": "她删除了那张书桌。", "explanation": "这里删除被当作“搬走或丢弃家具”的意思来用，但删除只指去掉字词或数据，不能用于家具。"}, {"text": "爸爸删除了那棵大树。", "explanation": "这里删除被当作“砍掉、移走树木”的意思来用，但删除只指去掉字词或数据，不能用于植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你这个错字删除。", "corrected_sentence": "请你把这个错字删除。", "error_description": "语序错误：宾语“这个错字”放在了“删除”前面，却没有用“把”。应说“请你把这个错字删除”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
