INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92568, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "添加", "is_correct": true, "explanation": "添加：与“删除”相反，指把文件、数据加进去。"}, {"text": "下载", "is_correct": false, "explanation": "下载：指从网络取得文件，与“删除”没有反义关系。"}, {"text": "打开", "is_correct": false, "explanation": "打开：指使文件可用，与“删除”不是反义词。"}, {"text": "发送", "is_correct": false, "explanation": "发送：指把文件传给他人，与“删除”不构成反义。"}], "correct_answer": "添加", "explanations": {"添加": "添加：与“删除”相反，指把文件、数据加进去。", "下载": "下载：指从网络取得文件，与“删除”没有反义关系。", "打开": "打开：指使文件可用，与“删除”不是反义词。", "发送": "发送：指把文件传给他人，与“删除”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
