INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92569, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变作是变成另一个样子。", "primary_collocate": null, "pronunciation": "biàn zuò", "ipa": "pjɛn⁵¹ tswo⁵¹", "syllable_count": 2, "sentences": [{"text": "那只丑小鸭后来变作了白天鹅。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，男孩一下子变作了大狗。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的水汽到了天上变作云。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的担心慢慢变作了害怕。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩梦见自己变作了一条鱼。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个故事里，树叶变作了小鸟。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水遇冷，白气变作了小水珠。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "魔法棒一挥，老鼠变作了马。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孙悟空变作一只小虫飞进去。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败的痛苦后来变作了他前进的力量。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变作了", "label": "体标"}, {"form": "变作过", "label": "体标"}, {"form": "變作", "label": "繁体"}], "register": "书面", "sense_fingerprint": "变成另一个样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5538bf12-020f-423d-a46d-0a1f06c15aac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92569, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变作", "is_correct": true, "explanation": "正确答案：变作 biàn zuò，意思是变成另一个样子。"}, {"text": "扮作", "is_correct": false, "explanation": "bàn（扮）与 biàn（变）只差一个 i，意思是装扮成。"}, {"text": "变奏", "is_correct": false, "explanation": "zòu（奏）与 zuò（作）韵母不同，zuò 是 uo，zòu 是 ou，意思是乐曲的变奏。"}, {"text": "变造", "is_correct": false, "explanation": "zào（造）与 zuò（作）韵母不同，zào 是 ao，意思是改动或伪造。"}], "explanations": {"变作": "正确答案：变作 biàn zuò，意思是变成另一个样子。", "扮作": "bàn（扮）与 biàn（变）只差一个 i，意思是装扮成。", "变奏": "zòu（奏）与 zuò（作）韵母不同，zuò 是 uo，zòu 是 ou，意思是乐曲的变奏。", "变造": "zào（造）与 zuò（作）韵母不同，zào 是 ao，意思是改动或伪造。"}, "sentence_index": null, "correct_answer": "变作"}, "level_3": {"options": [{"text": "生长", "is_correct": false, "explanation": "配价：“生长”是不及物动词，后面不能直接带“白天鹅”作宾语。"}, {"text": "变作", "is_correct": true, "explanation": "正确：变作表示变成另一个样子，与丑小鸭变成白天鹅相符。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”表示占有某物，与丑小鸭变成天鹅的意思不符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示舍去某物，与“丑小鸭变成白天鹅”的意思不符。"}], "explanations": {"生长": "配价：“生长”是不及物动词，后面不能直接带“白天鹅”作宾语。", "变作": "正确：变作表示变成另一个样子，与丑小鸭变成白天鹅相符。", "拥有": "语义：“拥有”表示占有某物，与丑小鸭变成天鹅的意思不符。", "放弃": "语义：“放弃”表示舍去某物，与“丑小鸭变成白天鹅”的意思不符。"}, "sentence_index": 0, "correct_answer": "变作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他变作了篮球队。", "explanation": "这里应该用〈加入〉。加入表示成为某个团体的成员；变作表示事物变成另一种事物，不能说人“变作”一个团队。"}, {"text": "他变作学生代表发了言。", "explanation": "这里应该用〈作为〉。作为表示以某种身份行事；变作表示事物变成另一种事物，不能用来表示身份。"}, {"text": "舞台上的灯光不停地变作颜色。", "explanation": "这里应该用〈变换〉。变换可以接“颜色”作宾语；变作表示变成另一种事物，不能说灯光“变作颜色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92569, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消散", "is_correct": false, "explanation": "配价：“消散”是不及物动词，后面不能直接带“小水珠”作宾语。"}, {"text": "变作", "is_correct": true, "explanation": "正确：变作表示变成另一个样子，与白气遇冷变成小水珠相符。"}, {"text": "融化", "is_correct": false, "explanation": "配价：“融化”是不及物动词，不能直接带“小水珠”作宾语。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”指液体变成固体，与白气遇冷变成小水珠的意思不符。"}], "explanations": {"消散": "配价：“消散”是不及物动词，后面不能直接带“小水珠”作宾语。", "变作": "正确：变作表示变成另一个样子，与白气遇冷变成小水珠相符。", "融化": "配价：“融化”是不及物动词，不能直接带“小水珠”作宾语。", "冻结": "语义：“冻结”指液体变成固体，与白气遇冷变成小水珠的意思不符。"}, "sentence_index": 6, "correct_answer": "变作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他变作了一个微笑。", "explanation": "这里应该用〈露出〉。露出表示表情或神色显现出来；变作表示事物变成另一种事物，“微笑”不是可以变成的新事物。"}, {"text": "我变作了一件红色的外套。", "explanation": "这里应该用〈穿〉。穿表示把衣服套在身上；变作表示事物变成另一种事物，人不能“变作”一件衣服。"}, {"text": "他变作了一个决定。", "explanation": "这里应该用〈作出〉。作出表示做出决定或判断；变作表示事物变成另一种事物，一个人不能“变作”一个决定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92569, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小猫在梦里变作成了一只老虎。", "corrected_sentence": "这只小猫在梦里变作了一只老虎。", "error_description": "“变作成了”多了“成”。变作本身已表示“变成”，不能再加“成”，应说“变作了一只老虎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92569, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "魔术师把这块木头变作成了一张桌子。", "corrected_sentence": "魔术师把这块木头变作了一张桌子。", "error_description": "错误：「变作成了」。「成」多余：变作本身已表示「变成」，应说「变作了一张桌子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
