INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变成。", "primary_collocate": null, "pronunciation": "biàn zuò", "ipa": "pjɛn⁵¹ tswo⁵¹", "syllable_count": 2, "sentences": [{"text": "毛毛虫后来变作了美丽的蝴蝶。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "魔法让南瓜变作一辆马车。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰遇到热就会变作水。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里，老人变作一只白鹤飞走了。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，雪都变作了小河的水。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把石头变作金子。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的哭声慢慢变作了笑声。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "魔术师把一朵花变作了小鸟。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的小雨，今天变作了大雪。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云变作雨落了下来。", "target_word": "变作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变作了", "label": "体标"}, {"form": "变作过", "label": "体标"}, {"form": "變作", "label": "繁体"}], "register": "书面", "sense_fingerprint": "由一种事物变成另一种事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5538bf12-020f-423d-a46d-0a1f06c15aac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
