DED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，后面不能直接带“笑声”作宾语。"}, {"text": "变作", "is_correct": true, "explanation": "正确：变作表示变成另一种事物，哭声变成笑声正相符。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变成液体，不能用来描述声音的变化。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“冷却”指温度降低，与哭声变成笑声的意思不符。"}], "explanations": {"消失": "配价：“消失”是不及物动词，后面不能直接带“笑声”作宾语。", "变作": "正确：变作表示变成另一种事物，哭声变成笑声正相符。", "融化": "语义：“融化”指固体遇热变成液体，不能用来描述声音的变化。", "冷却": "语义：“冷却”指温度降低，与哭声变成笑声的意思不符。"}, "sentence_index": 6, "correct_answer": "变作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他变作了一个微笑。", "explanation": "这里应该用〈露出〉。露出表示表情或神色显现出来；变作表示事物变成另一种事物，“微笑”不是可以变成的新事物。"}, {"text": "我变作了一件红色的外套。", "explanation": "这里应该用〈穿〉。穿表示把衣服套在身上；变作表示事物变成另一种事物，人不能“变作”一件衣服。"}, {"text": "他变作了一个决定。", "explanation": "这里应该用〈作出〉。作出表示做出决定或判断；变作表示事物变成另一种事物，一个人不能“变作”一个决定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只青蛙在童话里变作成了一位王子。", "corrected_sentence": "这只青蛙在童话里变作了一位王子。", "error_description": "“变作成了”多了“成”。变作本身已表示“变成”，不能再加“成”，应说“变作了一位王子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
