INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92571, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "剧是人们在台上或电视里演的故事。", "primary_collocate": null, "pronunciation": "jù", "ipa": "tɕy˥˩", "syllable_count": 1, "sentences": [{"text": "这部剧我昨天看完了。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天晚上都看剧。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部剧演的是一家人的故事。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在电视上看一部刚播的剧。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近在追一部好剧。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上正在演一部很多人都爱看的剧。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想在家看剧。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部剧一共有三十集。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶爱看剧，一看就是两个小时。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的小朋友在台上演了一部剧。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "劇", "label": "繁体"}], "register": "口语", "sense_fingerprint": "台上或电视里演出的故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92571, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "剧", "is_correct": true, "explanation": "剧 jù（第四声）：台上或电视里演的故事，正是目标词。"}, {"text": "举", "is_correct": false, "explanation": "举 jǔ（第三声）与 jù（第四声）声调不同，意思是举起。"}, {"text": "局", "is_correct": false, "explanation": "局 jú（第二声）与 jù（第四声）声调不同，意思是局面、棋局。"}, {"text": "居", "is_correct": false, "explanation": "居 jū（第一声）与 jù（第四声）声调不同，意思是居住。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 jù 声母不同（q / j），声调相同，意思是去。"}], "explanations": {"剧": "剧 jù（第四声）：台上或电视里演的故事，正是目标词。", "举": "举 jǔ（第三声）与 jù（第四声）声调不同，意思是举起。", "局": "局 jú（第二声）与 jù（第四声）声调不同，意思是局面、棋局。", "居": "居 jū（第一声）与 jù（第四声）声调不同，意思是居住。", "去": "qù 与 jù 声母不同（q / j），声调相同，意思是去。"}, "sentence_index": null, "correct_answer": "剧"}, "level_3": {"options": [{"text": "剧", "is_correct": true, "explanation": "剧：此处指演出的作品，“这部”和“看完了”搭配成立。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是用来吃的，不能“看完”。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“饭”的量词是顿或份，不说“这部饭”。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“歌”的量词是首，不说“这部歌”。"}], "explanations": {"剧": "剧：此处指演出的作品，“这部”和“看完了”搭配成立。", "蛋糕": "语义：蛋糕是用来吃的，不能“看完”。", "饭": "搭配：“饭”的量词是顿或份，不说“这部饭”。", "歌": "搭配：“歌”的量词是首，不说“这部歌”。"}, "sentence_index": 0, "correct_answer": "剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每周五晚上都看综艺剧。", "explanation": "这里应该用〈节目〉。剧是有情节的表演作品，综艺节目是综合性的娱乐节目，不是剧。"}, {"text": "我们在电视上看一幅刚播的剧。", "explanation": "这里应该用〈部〉。剧用“部”计量，“幅”用于画等平面作品，不用于剧。"}, {"text": "我们在电视上看一张刚播的剧。", "explanation": "这里应该用〈部〉。剧用“部”计量，“张”多用于桌子、纸、票等，不用于剧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92571, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "剧", "is_correct": true, "explanation": "剧 jù（第四声）：台上或电视里演的故事，正是目标词。"}, {"text": "居", "is_correct": false, "explanation": "jū（第一声）与 jù（第四声）声母韵母相同，只是声调不同，意思是居住。"}, {"text": "续", "is_correct": false, "explanation": "xù 与 jù 声母不同（x / j），声调相同，意思是继续、接着。"}, {"text": "菊", "is_correct": false, "explanation": "菊 jú（第二声）与 jù（第四声）声调不同，意思是菊花。"}], "explanations": {"剧": "剧 jù（第四声）：台上或电视里演的故事，正是目标词。", "居": "jū（第一声）与 jù（第四声）声母韵母相同，只是声调不同，意思是居住。", "续": "xù 与 jù 声母不同（x / j），声调相同，意思是继续、接着。", "菊": "菊 jú（第二声）与 jù（第四声）声调不同，意思是菊花。"}, "sentence_index": null, "correct_answer": "剧"}, "level_3": {"options": [{"text": "剧", "is_correct": true, "explanation": "剧：此处指演出的作品，“看剧”是正常说法。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“看”一般不跟“桌子”搭配，桌子是用来放东西的家具。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不是可以“看”来消遣的对象，“看”的对象应是影视或书籍。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是用来吃的，不能“看”。"}], "explanations": {"剧": "剧：此处指演出的作品，“看剧”是正常说法。", "桌子": "搭配：“看”一般不跟“桌子”搭配，桌子是用来放东西的家具。", "水": "语义：水不是可以“看”来消遣的对象，“看”的对象应是影视或书籍。", "饼干": "语义：饼干是用来吃的，不能“看”。"}, "sentence_index": 6, "correct_answer": "剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校的小朋友在台上演了一首剧。", "explanation": "这里应该用〈部〉。剧用“部”计量，“首”用于歌曲、诗词。"}, {"text": "学校的小朋友在台上演了一条剧。", "explanation": "这里应该用〈部〉。“条”多用于鱼、路、消息等，不用于剧。"}, {"text": "学校的小朋友在台上演了一座剧。", "explanation": "这里应该用〈部〉。“座”用于山、桥、建筑等，剧不用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首剧昨晚在电视上播出了。", "corrected_sentence": "这部剧昨晚在电视上播出了。", "error_description": "错误在量词：“剧”应该用“部”，“首”用于歌曲、诗词。正确说法是“这部剧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸周末喜欢看这部剧们。", "corrected_sentence": "爸爸周末喜欢看这部剧。", "error_description": "错误在词尾：“剧”后面不能加“们”，“们”只用于指人的名词。正确说法是“这部剧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
