INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92572, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "戏剧、电影或电视剧等表演作品。", "primary_collocate": null, "pronunciation": "jù", "ipa": "tɕy˥˩", "syllable_count": 1, "sentences": [{"text": "这部剧很受年轻人喜欢。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部剧的演员都很有名。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一部很有名的剧。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一起排了一部剧。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部剧在电视上很火。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他演过很多部剧。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部剧里的音乐真好听。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢看有意思的剧。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那部剧下个月开演。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部剧让我哭了好几次。", "target_word": "剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "劇", "label": "繁体"}], "register": "口语", "sense_fingerprint": "戏剧、影视等表演作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92572, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "剧", "is_correct": true, "explanation": "剧 jù（第四声）：戏剧、电影或电视剧等表演作品，正是目标词。"}, {"text": "居", "is_correct": false, "explanation": "居 jū（第一声）与 jù（第四声）声调不同，意思是居住。"}, {"text": "举", "is_correct": false, "explanation": "举 jǔ（第三声）与 jù（第四声）声调不同，意思是举起。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 jù 声母不同（q / j），声调相同，意思是去。"}], "explanations": {"剧": "剧 jù（第四声）：戏剧、电影或电视剧等表演作品，正是目标词。", "居": "居 jū（第一声）与 jù（第四声）声调不同，意思是居住。", "举": "举 jǔ（第三声）与 jù（第四声）声调不同，意思是举起。", "去": "qù 与 jù 声母不同（q / j），声调相同，意思是去。"}, "sentence_index": null, "correct_answer": "剧"}, "level_3": {"options": [{"text": "剧", "is_correct": true, "explanation": "剧：指影视或戏剧作品，“这部”和“很受年轻人喜欢”搭配成立。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“饭”的量词是顿或份，不说“这部饭”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“蛋糕”的量词是块或个，不说“这部蛋糕”。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是场所，不是作品，“这部公园”不成立。"}], "explanations": {"剧": "剧：指影视或戏剧作品，“这部”和“很受年轻人喜欢”搭配成立。", "饭": "搭配：“饭”的量词是顿或份，不说“这部饭”。", "蛋糕": "搭配：“蛋糕”的量词是块或个，不说“这部蛋糕”。", "公园": "语义：公园是场所，不是作品，“这部公园”不成立。"}, "sentence_index": 0, "correct_answer": "剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们一起排了一只剧。", "explanation": "这里应该用〈部〉。剧用“部”计量，“只”多用于动物等。"}, {"text": "同学们一起排了一条剧。", "explanation": "这里应该用〈部〉。“条”多用于鱼、路、消息等，不用于剧。"}, {"text": "同学们一起排了一幅剧。", "explanation": "这里应该用〈部〉。“幅”用于画等平面作品，不用于剧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92572, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "剧", "is_correct": true, "explanation": "剧 jù（第四声）：戏剧、电影或电视剧等表演作品，正是目标词。"}, {"text": "居", "is_correct": false, "explanation": "jū（第一声）与 jù（第四声）声母韵母相同，只是声调不同，意思是居住。"}, {"text": "续", "is_correct": false, "explanation": "xù 与 jù 声母不同（x / j），声调相同，意思是继续、接着。"}, {"text": "菊", "is_correct": false, "explanation": "菊 jú（第二声）与 jù（第四声）声调不同，意思是菊花。"}], "explanations": {"剧": "剧 jù（第四声）：戏剧、电影或电视剧等表演作品，正是目标词。", "居": "jū（第一声）与 jù（第四声）声母韵母相同，只是声调不同，意思是居住。", "续": "xù 与 jù 声母不同（x / j），声调相同，意思是继续、接着。", "菊": "菊 jú（第二声）与 jù（第四声）声调不同，意思是菊花。"}, "sentence_index": null, "correct_answer": "剧"}, "level_3": {"options": [{"text": "剧", "is_correct": true, "explanation": "剧：指作品，“这部”和“剧里的音乐”搭配成立。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“歌”的量词是首，不说“这部歌”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”的量词是张，不说“这部桌子”，桌子里也没有音乐。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“房子”的量词是座或栋，不说“这部房子”。"}], "explanations": {"剧": "剧：指作品，“这部”和“剧里的音乐”搭配成立。", "歌": "搭配：“歌”的量词是首，不说“这部歌”。", "桌子": "搭配：“桌子”的量词是张，不说“这部桌子”，桌子里也没有音乐。", "房子": "搭配：“房子”的量词是座或栋，不说“这部房子”。"}, "sentence_index": 6, "correct_answer": "剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首剧让我哭了好几次。", "explanation": "这里应该用〈部〉。剧用“部”计量，“首”用于歌曲、诗词。"}, {"text": "这座剧让我哭了好几次。", "explanation": "这里应该用〈部〉。“座”用于山、桥、建筑等，剧不用“座”。"}, {"text": "这支剧让我哭了好几次。", "explanation": "这里应该用〈部〉。“支”多用于歌曲、笔、队伍等，剧要用“部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只剧的结局让人难忘。", "corrected_sentence": "这部剧的结局让人难忘。", "error_description": "错误在量词：“剧”应该用“部”，“只”多用于动物。正确说法是“这部剧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈每天晚上都看这部剧们。", "corrected_sentence": "我妈妈每天晚上都看这部剧。", "error_description": "错误在词尾：“剧”后面不能加“们”，“们”只用于指人的名词。正确说法是“这部剧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
