INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面向南方时靠西的一边；与“左”相对。", "primary_collocate": null, "pronunciation": "yòu", "ipa": "jou˥˩", "syllable_count": 1, "sentences": [{"text": "前面有红绿灯，请向右转。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了马路往右走，银行就在那儿。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站出来往右走，就能看到银行。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，汽车一般靠右行驶。", "target_word": "右", "complexity_tier": "T3", "furigana": "zài Zhōngguó, qìchē yìbān kào yòu xíngshǐ.", "sentence_source": "generated"}, {"text": "看地图，北在上，东在右。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向左走是学校，向右走是公园。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先往右拐，再一直往前走。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红绿灯前不能向右转，要等一等。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，过马路时先看左，再看右。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上楼梯的时候，请大家靠右走。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "右边", "label": "复合"}, {"form": "右转", "label": "复合"}], "register": "中性", "sense_fingerprint": "右·面向南时靠西的一边，与左相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f149c945-cf41-413d-b166-ecfc5601d7e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92574, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "右", "is_correct": true, "explanation": "yòu（第四声）指面向南方时靠西的一边，与“左”相对，是正确答案。"}, {"text": "有", "is_correct": false, "explanation": "yǒu（第三声）与 yòu（第四声）声调不同，意思是“有”，不是方位。"}, {"text": "游", "is_correct": false, "explanation": "yóu（第二声）与 yòu（第四声）声调不同，意思是“游览”。"}, {"text": "忧", "is_correct": false, "explanation": "yōu（第一声）与 yòu（第四声）声调不同，意思是“忧愁”。"}], "explanations": {"右": "yòu（第四声）指面向南方时靠西的一边，与“左”相对，是正确答案。", "有": "yǒu（第三声）与 yòu（第四声）声调不同，意思是“有”，不是方位。", "游": "yóu（第二声）与 yòu（第四声）声调不同，意思是“游览”。", "忧": "yōu（第一声）与 yòu（第四声）声调不同，意思是“忧愁”。"}, "sentence_index": null, "correct_answer": "右"}, "level_3": {"options": [{"text": "右", "is_correct": true, "explanation": "“右”表示向这一侧转弯，与“红绿灯”的路口语境相合。"}, {"text": "旁", "is_correct": false, "explanation": "搭配：“旁”单用不表示方向，要说“旁边”。"}, {"text": "下", "is_correct": false, "explanation": "语义：“下”指向下，不是路口拐弯的方向。"}, {"text": "中", "is_correct": false, "explanation": "搭配：“向中”不能单独表示转弯的方向。"}], "explanations": {"右": "“右”表示向这一侧转弯，与“红绿灯”的路口语境相合。", "旁": "搭配：“旁”单用不表示方向，要说“旁边”。", "下": "语义：“下”指向下，不是路口拐弯的方向。", "中": "搭配：“向中”不能单独表示转弯的方向。"}, "sentence_index": 0, "correct_answer": "右"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的解法很右，老师点头表扬了。", "explanation": "这里应该用〈对〉。〈右〉表示方位，不能用来判断解法对错，表示正确要用〈对〉。"}, {"text": "他的成绩比我右，所以排在前面。", "explanation": "这里应该用〈好〉。〈右〉不表示成绩好坏，形容成绩好要用〈好〉。"}, {"text": "这把椅子右得很，坐上去特别舒服。", "explanation": "这里应该用〈舒服〉。〈右〉表示方位，不能形容舒适程度，形容舒适要用〈舒服〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92574, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "右", "is_correct": true, "explanation": "yòu（第四声）指面向南方时靠西的一边，是正确答案。"}, {"text": "油", "is_correct": false, "explanation": "yóu（第二声）与 yòu（第四声）声调不同，意思是“油”。"}, {"text": "友", "is_correct": false, "explanation": "yǒu（第三声）与 yòu（第四声）声调不同，意思是“朋友”。"}, {"text": "优", "is_correct": false, "explanation": "yōu（第一声）与 yòu（第四声）声调不同，意思是“优秀”。"}, {"text": "由", "is_correct": false, "explanation": "yóu（第二声）与 yòu（第四声）声调不同，意思是“由于”。"}], "explanations": {"右": "yòu（第四声）指面向南方时靠西的一边，是正确答案。", "油": "yóu（第二声）与 yòu（第四声）声调不同，意思是“油”。", "友": "yǒu（第三声）与 yòu（第四声）声调不同，意思是“朋友”。", "优": "yōu（第一声）与 yòu（第四声）声调不同，意思是“优秀”。", "由": "yóu（第二声）与 yòu（第四声）声调不同，意思是“由于”。"}, "sentence_index": null, "correct_answer": "右"}, "level_3": {"options": [{"text": "右", "is_correct": true, "explanation": "“右”表示向这一侧拐弯，与“请先往…拐”的语境相合。"}, {"text": "上", "is_correct": false, "explanation": "语义：“上”指上方，不是拐弯的方向。"}, {"text": "底", "is_correct": false, "explanation": "搭配：“底”不作方位词，不能说“往底拐”。"}, {"text": "面", "is_correct": false, "explanation": "搭配：“面”不单独表示方向，不能说“往面拐”。"}], "explanations": {"右": "“右”表示向这一侧拐弯，与“请先往…拐”的语境相合。", "上": "语义：“上”指上方，不是拐弯的方向。", "底": "搭配：“底”不作方位词，不能说“往底拐”。", "面": "搭配：“面”不单独表示方向，不能说“往面拐”。"}, "sentence_index": 6, "correct_answer": "右"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他比我右一级，所以他说了算。", "explanation": "这里应该用〈高〉。现代汉语中〈右〉表示方位，一般不用来比较职位高低（“无出其右”等固定说法除外），比较职位要用〈高〉。"}, {"text": "我的电脑比他的右，运行得更快。", "explanation": "这里应该用〈好〉。〈右〉不能比较性能好坏，比较性能要用〈好〉。"}, {"text": "这次比赛他的表现很右，观众都鼓掌。", "explanation": "这里应该用〈精彩〉。〈右〉不能形容表现的精彩程度，形容表现精彩要用〈精彩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面路口请向右的拐。", "corrected_sentence": "前面路口请向右拐。", "error_description": "错误在“向右”后面多加了“的”。“向右”修饰动词时要直接接动词，应说“向右拐”，“右”和动词之间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在中国，汽车要靠右的行驶。", "corrected_sentence": "在中国，汽车要靠右行驶。", "error_description": "错误在“靠右”后面多加了“的”。“靠右”修饰动词时直接接动词，应说“靠右行驶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92576, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无产阶级", "is_correct": true, "explanation": "正确：“资产阶级”占有生产资料，“无产阶级”只能出卖劳动力，二者构成反义。"}, {"text": "历史", "is_correct": false, "explanation": "不构成反义：“历史”指过去的事件或过程，与阶级无反义关系。"}, {"text": "民主", "is_correct": false, "explanation": "不构成反义：“民主”是政治制度或理念，不是与资产阶级相对的一类人。"}, {"text": "友谊", "is_correct": false, "explanation": "不构成反义：“友谊”是人与人之间的感情，与阶级无反义关系。"}], "correct_answer": "无产阶级", "explanations": {"无产阶级": "正确：“资产阶级”占有生产资料，“无产阶级”只能出卖劳动力，二者构成反义。", "历史": "不构成反义：“历史”指过去的事件或过程，与阶级无反义关系。", "民主": "不构成反义：“民主”是政治制度或理念，不是与资产阶级相对的一类人。", "友谊": "不构成反义：“友谊”是人与人之间的感情，与阶级无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92576, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无产阶级", "is_correct": true, "explanation": "正确：“资产阶级”占有生产资料，“无产阶级”只能出卖劳动力，二者构成反义。"}, {"text": "河流", "is_correct": false, "explanation": "不构成反义：“河流”是自然事物，与阶级无关。"}, {"text": "音乐", "is_correct": false, "explanation": "不构成反义：“音乐”是艺术形式，与阶级无反义关系。"}, {"text": "数学", "is_correct": false, "explanation": "不构成反义：“数学”是学科，不是阶级，与资产阶级无反义关系。"}], "correct_answer": "无产阶级", "explanations": {"无产阶级": "正确：“资产阶级”占有生产资料，“无产阶级”只能出卖劳动力，二者构成反义。", "河流": "不构成反义：“河流”是自然事物，与阶级无关。", "音乐": "不构成反义：“音乐”是艺术形式，与阶级无反义关系。", "数学": "不构成反义：“数学”是学科，不是阶级，与资产阶级无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "占有生产资料、雇佣工人的社会阶级。", "primary_collocate": null, "pronunciation": "zī chǎn jiē jí", "ipa": "tsɨ˥ tʂʰan˨˩ tɕjɛ˥ tɕi˧˥", "syllable_count": 4, "sentences": [{"text": "资产阶级占有生产资料，雇佣工人。", "target_word": "资产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资产阶级和无产阶级是两个不同的阶级。", "target_word": "资产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的主人属于资产阶级。", "target_word": "资产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资产阶级靠工人的劳动赚钱。", "target_word": "资产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书介绍了资产阶级的形成过程。", "target_word": "资产阶级", "complexity_tier": "T3", "furigana": "lì shǐ shū jiè shào le zī chǎn jiē jí de xíng chéng guò chéng", "sentence_source": "generated"}, {"text": "资产阶级出现在工业发展以后。", "target_word": "资产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马克思分析过资产阶级的特点。", "target_word": "资产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资产阶级雇了很多工人来工作。", "target_word": "资产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的资产阶级越来越强大。", "target_word": "资产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在课上，我们讨论了资产阶级的作用。", "target_word": "资产阶级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "資產階級", "label": "繁体"}, {"form": "小资产阶级", "label": "复合"}], "register": "书面", "sense_fingerprint": "占有生产资料、雇佣工人的社会阶级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee2df57-fb87-4f86-b7e0-dc23161c9f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资产阶级", "is_correct": true, "explanation": "正确：“资产阶级”占有生产资料、雇佣工人，符合句意。"}, {"text": "工人", "is_correct": false, "explanation": "语义：“工人”是被雇佣的人，不占有生产资料，也不雇佣工人。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”不占有生产资料，与“雇佣工人”的描述不符。"}, {"text": "树", "is_correct": false, "explanation": "配价：“占有”要求拥有者是人或机构，“树”不能占有生产资料。"}], "explanations": {"资产阶级": "正确：“资产阶级”占有生产资料、雇佣工人，符合句意。", "工人": "语义：“工人”是被雇佣的人，不占有生产资料，也不雇佣工人。", "学生": "语义：“学生”不占有生产资料，与“雇佣工人”的描述不符。", "树": "配价：“占有”要求拥有者是人或机构，“树”不能占有生产资料。"}, "sentence_index": 0, "correct_answer": "资产阶级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的邻居每天早上吃一个资产阶级。", "explanation": "这里应该用〈鸡蛋〉。资产阶级是社会阶级，不是食物，不能用来吃。"}, {"text": "资产阶级是一种社会制度。", "explanation": "这里应该用〈资本主义〉。资产阶级是指人群，不是社会制度。"}, {"text": "资产阶级的身高是一米八。", "explanation": "这里应该用〈富豪〉。资产阶级是阶级的集体概念，没有身高这类个人特征；指单个有钱人要说〈富豪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资产阶级", "is_correct": true, "explanation": "正确：“资产阶级”是马克思分析的对象之一，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“分析”的对象多为社会现象，天气的特点不是马克思分析的对象。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是社会阶层，不宜作为马克思分析的社会对象。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“分析……的特点”搭配的对象应是社会或理论问题，不能说“厨房的特点”。"}], "explanations": {"资产阶级": "正确：“资产阶级”是马克思分析的对象之一，符合句意。", "天气": "语义：“分析”的对象多为社会现象，天气的特点不是马克思分析的对象。", "河流": "语义：河流不是社会阶层，不宜作为马克思分析的社会对象。", "厨房": "搭配：“分析……的特点”搭配的对象应是社会或理论问题，不能说“厨房的特点”。"}, "sentence_index": 6, "correct_answer": "资产阶级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一大笔资产阶级。", "explanation": "这里应该用〈资产〉。资产阶级指人群，不能指财产。"}, {"text": "资产阶级的眼睛很大。", "explanation": "这里应该用〈富人〉。资产阶级指阶级整体，不能说它的眼睛大小；指个人要说〈富人〉。"}, {"text": "工人们雇了资产阶级来上班。", "explanation": "这里把资产阶级用成了〈雇员〉的角色。资产阶级是雇主，应说“资产阶级雇了工人”，不能被工人雇来上班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "资产阶级的占有了生产资料。", "corrected_sentence": "资产阶级占有了生产资料。", "error_description": "多余的“的”：“资产阶级”直接作主语，“占有了”前不能加“的”，应说“资产阶级占有了生产资料”，不能说“资产阶级的占有了生产资料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把资产阶级的推翻了。", "corrected_sentence": "工人把资产阶级推翻了。", "error_description": "多余的“的”：“把”字句中，“资产阶级”后不能加“的”，“的”使其变成名词性短语，打断了“把”字句结构。正确应为“工人把资产阶级推翻了”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
