INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92577, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吻是用嘴轻轻碰一下，表示喜欢。", "primary_collocate": null, "pronunciation": "wěn", "ipa": "wən˨˩˦", "syllable_count": 1, "sentences": [{"text": "小女孩轻轻吻了一下她的小狗。", "target_word": "吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临走的时候，他吻了吻妻子的脸。", "target_word": "吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把脸靠过去，他在她脸上吻了一下。", "target_word": "吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出门前，总会吻一下我的头。", "target_word": "吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小宝宝笑着，在妈妈的脸上吻了一下。", "target_word": "吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思，只敢吻一下她的手。", "target_word": "吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩鼓起勇气，在女孩的脸上轻轻吻了一下。", "target_word": "吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我送她到门口，她吻了一下我就走了。", "target_word": "吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老爷爷抱起孙女，吻了一下她的头发。", "target_word": "吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跳到我怀里，我吻了它一下，因为我太喜欢它了。", "target_word": "吻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吻了", "label": "体标"}, {"form": "吻过", "label": "体标"}, {"form": "吻一吻", "label": "重叠"}, {"form": "亲吻", "label": "复合"}, {"form": "热吻", "label": "复合"}], "register": "中性", "sense_fingerprint": "吻：用嘴轻轻碰一下，表示喜欢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1770a-bc57-44b1-a061-4827a60dbaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92577, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吻", "is_correct": true, "explanation": "吻：用嘴轻轻碰一下，表示喜欢，正确答案。"}, {"text": "问", "is_correct": false, "explanation": "wèn（第四声）与 wěn（第三声）声调不同，意思是询问。"}, {"text": "温", "is_correct": false, "explanation": "wēn（第一声）与 wěn（第三声）声调不同，意思是温暖。"}, {"text": "闻", "is_correct": false, "explanation": "wén（第二声）与 wěn（第三声）声调不同，意思是闻到、听到。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn（第三声）与 wěn 韵母不同（-an 与 -en），意思是碗，是餐具。"}], "explanations": {"吻": "吻：用嘴轻轻碰一下，表示喜欢，正确答案。", "问": "wèn（第四声）与 wěn（第三声）声调不同，意思是询问。", "温": "wēn（第一声）与 wěn（第三声）声调不同，意思是温暖。", "闻": "wén（第二声）与 wěn（第三声）声调不同，意思是闻到、听到。", "碗": "wǎn（第三声）与 wěn 韵母不同（-an 与 -en），意思是碗，是餐具。"}, "sentence_index": null, "correct_answer": "吻"}, "level_3": {"options": [{"text": "吻", "is_correct": true, "explanation": "吻：用嘴轻轻碰一下，表示喜欢，与“轻轻地”和对小狗的喜爱相合。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」是把液体咽下去，不能说“喝了一下小狗”。"}, {"text": "吞", "is_correct": false, "explanation": "语义：「吞」是咽下去，与“小狗”的亲近动作不符。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：「扔」多用于抛出物品，不说“扔了一下小狗”来表示喜爱。"}], "explanations": {"吻": "吻：用嘴轻轻碰一下，表示喜欢，与“轻轻地”和对小狗的喜爱相合。", "喝": "语义：「喝」是把液体咽下去，不能说“喝了一下小狗”。", "吞": "语义：「吞」是咽下去，与“小狗”的亲近动作不符。", "扔": "搭配：「扔」多用于抛出物品，不说“扔了一下小狗”来表示喜爱。"}, "sentence_index": 0, "correct_answer": "吻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两段管子接在一起，吻得很严，不漏水。", "explanation": "这里的「吻」是“吻合”的意思，指两个物体严丝合缝，不是用嘴唇接触。"}, {"text": "老师吻了我一个难题，我没有回答。", "explanation": "这里应该用〈问〉。「吻」是用嘴唇接触，表示喜爱；向人提出难题要用「问」。"}, {"text": "他吻了一下桌子上的灰，桌子就干净了。", "explanation": "这里应该用〈擦〉。「吻」是用嘴轻轻碰一下，表示喜欢；把桌子弄干净要用「擦」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吻", "is_correct": true, "explanation": "吻：用嘴唇轻触，表示喜欢，与男孩鼓起勇气后的温柔动作相合。"}, {"text": "踩", "is_correct": false, "explanation": "语义：「踩」是用脚压，与脸上的温柔动作不符。"}, {"text": "听", "is_correct": false, "explanation": "语义：「听」是用耳朵接收声音，不能说“在脸上听了一下”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」是把液体咽下去，不能说“在脸上喝了一下”。"}], "explanations": {"吻": "吻：用嘴唇轻触，表示喜欢，与男孩鼓起勇气后的温柔动作相合。", "踩": "语义：「踩」是用脚压，与脸上的温柔动作不符。", "听": "语义：「听」是用耳朵接收声音，不能说“在脸上听了一下”。", "喝": "语义：「喝」是把液体咽下去，不能说“在脸上喝了一下”。"}, "sentence_index": 6, "correct_answer": "吻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我吻了一口饼干，然后去写作业。", "explanation": "这里应该用〈咬〉。「吻」是用嘴唇接触，表示喜欢；咬一口食物要用「咬」。"}, {"text": "妈妈低下头，轻轻吻了吻汤的味道。", "explanation": "这里应该用〈闻〉。「吻」是用嘴唇接触，表示喜欢；闻汤的味道要用「闻」。"}, {"text": "爷爷吻了一下药，然后递给我。", "explanation": "这里应该用〈温〉。「吻」是用嘴唇接触，表示喜欢；把药加热要用「温」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸出门前吻了一个我的头。", "corrected_sentence": "爸爸出门前吻了一下我的头。", "error_description": "动量词错误。表示“吻”这个动作做了一次，要用动量词「一下」，不能用「一个」；「吻了一下」是对的，「吻了一个」是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他吻着一下她的脸，然后笑了。", "corrected_sentence": "他吻了一下她的脸，然后笑了。", "error_description": "体标错误。「着」表示动作正在进行，与表示完成的「一下」矛盾；完成的动作要用「了」，「吻了一下」是对的，「吻着一下」是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
