INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92579, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体不穿衣物或鞋，裸露着。", "primary_collocate": null, "pronunciation": "chì", "ipa": "ʈʂʰɨ˥˩", "syllable_count": 1, "sentences": [{"text": "孩子赤着脚在沙滩上跑。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很热，他赤着上身在家看书。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她赤着脚走进了房间。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸赤着脚在河边走来走去。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上很凉，别赤着脚走路。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩赤着身子跳进了水里。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赤着上身，在太阳下干活。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们赤着膀子搬石头。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢赤着脚走在草地上。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们赤着脚，在海边玩了一下午。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赤着", "label": "体标"}, {"form": "赤脚", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体不穿衣物或鞋，裸露着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92579, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赤", "is_correct": true, "explanation": "赤（chì）意思是身体不穿衣物或鞋，裸露着，这是听到的正确词。"}, {"text": "吃", "is_correct": false, "explanation": "chī（第一声）与 chì（第四声）声调不同，意思是吃东西。"}, {"text": "池", "is_correct": false, "explanation": "chí（第二声）与 chì（第四声）声调不同，意思是池塘。"}, {"text": "尺", "is_correct": false, "explanation": "chǐ（第三声）与 chì（第四声）声调不同，意思是尺子。"}, {"text": "次", "is_correct": false, "explanation": "cì（第四声）与 chì 声母不同（c 与 ch），意思是次数。"}], "explanations": {"赤": "赤（chì）意思是身体不穿衣物或鞋，裸露着，这是听到的正确词。", "吃": "chī（第一声）与 chì（第四声）声调不同，意思是吃东西。", "池": "chí（第二声）与 chì（第四声）声调不同，意思是池塘。", "尺": "chǐ（第三声）与 chì（第四声）声调不同，意思是尺子。", "次": "cì（第四声）与 chì 声母不同（c 与 ch），意思是次数。"}, "sentence_index": null, "correct_answer": "赤"}, "level_3": {"options": [{"text": "赤", "is_correct": true, "explanation": "“赤着脚”指脚裸露、不穿鞋，符合句意。"}, {"text": "红", "is_correct": false, "explanation": "搭配：“红”描写颜色，不能用“红着脚”表示脚没穿鞋的状态。"}, {"text": "白", "is_correct": false, "explanation": "搭配：“白”描写颜色，“白着脚”不表示裸露。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”表示温度感受，与“在沙滩上跑”的情境不符。"}], "explanations": {"赤": "“赤着脚”指脚裸露、不穿鞋，符合句意。", "红": "搭配：“红”描写颜色，不能用“红着脚”表示脚没穿鞋的状态。", "白": "搭配：“白”描写颜色，“白着脚”不表示裸露。", "冷": "语义：“冷”表示温度感受，与“在沙滩上跑”的情境不符。"}, "sentence_index": 0, "correct_answer": "赤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他赤着一双新运动鞋，走进了教室。", "explanation": "这里应该用〈穿着〉。“赤”指身体不穿衣物，鞋子是穿在脚上的，不能用“赤着”修饰。"}, {"text": "她赤着上身，穿着一件厚外套。", "explanation": "“赤着上身”指上身没穿衣服，后面又说“穿着一件厚外套”，前后矛盾。"}, {"text": "公司今年赤了三百万，老板很着急。", "explanation": "这里应该用〈亏〉。“赤”只用于“赤字”等词中，不能单独表示亏损。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92579, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赤", "is_correct": true, "explanation": "赤（chì）意思是身体不穿衣物或鞋，裸露着，这是听到的正确词。"}, {"text": "迟", "is_correct": false, "explanation": "chí（第二声）与 chì（第四声）声调不同，意思是迟到、晚。"}, {"text": "持", "is_correct": false, "explanation": "chí（第二声）与 chì（第四声）声调不同，意思是拿着、保持。"}, {"text": "刺", "is_correct": false, "explanation": "cì（第四声）与 chì 声母不同（c 与 ch），意思是刺。"}, {"text": "痴", "is_correct": false, "explanation": "chī（第一声）与 chì（第四声）声调不同，意思是痴呆、痴迷。"}], "explanations": {"赤": "赤（chì）意思是身体不穿衣物或鞋，裸露着，这是听到的正确词。", "迟": "chí（第二声）与 chì（第四声）声调不同，意思是迟到、晚。", "持": "chí（第二声）与 chì（第四声）声调不同，意思是拿着、保持。", "刺": "cì（第四声）与 chì 声母不同（c 与 ch），意思是刺。", "痴": "chī（第一声）与 chì（第四声）声调不同，意思是痴呆、痴迷。"}, "sentence_index": null, "correct_answer": "赤"}, "level_3": {"options": [{"text": "赤", "is_correct": true, "explanation": "“赤着上身”指上身裸露，符合句意。"}, {"text": "蓝", "is_correct": false, "explanation": "搭配：“蓝”描写颜色，不能说“蓝着上身”表示裸露。"}, {"text": "灰", "is_correct": false, "explanation": "搭配：“灰”描写颜色，不能用来表示上身裸露。"}, {"text": "凉", "is_correct": false, "explanation": "语义：“凉”指温度，与“在太阳下干活”的情境相矛盾。"}], "explanations": {"赤": "“赤着上身”指上身裸露，符合句意。", "蓝": "搭配：“蓝”描写颜色，不能说“蓝着上身”表示裸露。", "灰": "搭配：“灰”描写颜色，不能用来表示上身裸露。", "凉": "语义：“凉”指温度，与“在太阳下干活”的情境相矛盾。"}, "sentence_index": 6, "correct_answer": "赤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子赤着四条腿，站在门口。", "explanation": "“赤”只用于人的身体部位不穿衣物或鞋，椅子没有这种状态，不能说“赤着四条腿”。"}, {"text": "这棵大树赤着枝叶，过了一个冬天。", "explanation": "“赤”只用于人的身体部位不穿衣物或鞋，不能用于树木。"}, {"text": "那辆汽车赤着车身，在路上跑。", "explanation": "“赤”只用于人的身体部位不穿衣物或鞋，不能用于汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他赤着了脚在沙滩上走。", "corrected_sentence": "他赤着脚在沙滩上走。", "error_description": "“着”与“了”不能同时用在“赤”后，应去掉“了”，即“赤着脚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他赤过上身在河边钓鱼。", "corrected_sentence": "他赤着上身在河边钓鱼。", "error_description": "“赤”后接“着”表示裸露的状态，“过”表示经历，“赤过上身”不自然。错误在“过”，应改为“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
