INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92580, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体某部分裸露在外，没有遮盖。", "primary_collocate": null, "pronunciation": "chì", "ipa": "ʈʂʰɨ˥˩", "syllable_count": 1, "sentences": [{"text": "天太热了，哥哥赤着上身吃西瓜。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人赤着脚在田里走。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员赤着脚站在地上。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想赤着脚出门。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩赤着脚在雨里跑。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅赤着膀子打铁。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进门以后，他赤着脚走到床边。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很浅，孩子们赤着脚下去玩。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赤着上身，让医生检查。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天别赤着脚，会感冒。", "target_word": "赤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赤着", "label": "体标"}, {"form": "赤脚", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体某部分裸露在外，没有遮盖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
