INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈赤过双脚在厨房里忙。", "corrected_sentence": "妈妈赤着双脚在厨房里忙。", "error_description": "“赤”后接“着”表示裸露的状态，“过”表示经历，“赤过双脚”不自然。错误在“过”，应改为“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
