INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92583, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "辅导是帮着别人把功课学好。", "primary_collocate": null, "pronunciation": "fǔ dǎo", "ipa": "fu˨˩˦ taʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈每天晚上辅导弟弟做数学作业。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在家辅导我写英语作业。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师放学后留下来辅导成绩差的同学。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题我不会，请你辅导我一下，好吗？", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个周末都辅导邻居的孩子学数学。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸工作太忙，没有时间辅导女儿的功课。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的同桌英语很好，常常辅导我。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请了一位大学生来辅导儿子学汉语。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上个月王老师辅导过我几次物理。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐正在房间里辅导小明写作业。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辅导了", "label": "体标"}, {"form": "辅导过", "label": "体标"}, {"form": "辅导辅导", "label": "重叠"}, {"form": "輔導", "label": "繁体"}], "register": "中性", "sense_fingerprint": "帮别人做作业、学好功课", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df752ed1-047e-4fbd-b779-b0ded6150625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92583, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辅导", "is_correct": true, "explanation": "辅导指帮助学习功课，“妈妈每天晚上辅导弟弟做数学作业”句意通顺，是唯一能填入的词。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是物体表面，不能说“擦弟弟做数学作业”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或卫生，不能说“打扫弟弟做数学作业”。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要“送给某人某物”的结构，后接动词短语“做数学作业”不成立。"}], "explanations": {"辅导": "辅导指帮助学习功课，“妈妈每天晚上辅导弟弟做数学作业”句意通顺，是唯一能填入的词。", "擦": "搭配：“擦”的对象是物体表面，不能说“擦弟弟做数学作业”。", "打扫": "搭配：“打扫”的对象是场所或卫生，不能说“打扫弟弟做数学作业”。", "送": "配价：“送”需要“送给某人某物”的结构，后接动词短语“做数学作业”不成立。"}, "sentence_index": 0, "correct_answer": "辅导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生辅导病人按时吃药。", "explanation": "这里应该用〈叮嘱〉。辅导指帮助学习功课，提醒病人按时吃药应用〈叮嘱〉。"}, {"text": "妈妈每天辅导生病的爷爷。", "explanation": "这里应该用〈照顾〉。辅导指帮助学习，照料生病的老人应用〈照顾〉。"}, {"text": "园丁每天辅导院子里的花草。", "explanation": "这里应该用〈浇灌〉。辅导指帮助学习功课，给花草浇水应说〈浇灌〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辅导", "is_correct": true, "explanation": "辅导指帮助学习，同桌英语很好，帮我学英语，句意通顺，是唯一能填入的词。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是把一种语言转换成另一种，不能用来指对人的学习帮助。"}, {"text": "复印", "is_correct": false, "explanation": "搭配：“复印”的对象是文件或图像，不能用于人。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的对象是食物或饮品，不能说“品尝我”。"}], "explanations": {"辅导": "辅导指帮助学习，同桌英语很好，帮我学英语，句意通顺，是唯一能填入的词。", "翻译": "语义：“翻译”是把一种语言转换成另一种，不能用来指对人的学习帮助。", "复印": "搭配：“复印”的对象是文件或图像，不能用于人。", "品尝": "搭配：“品尝”的对象是食物或饮品，不能说“品尝我”。"}, "sentence_index": 6, "correct_answer": "辅导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶每天辅导我散步。", "explanation": "这里应该用〈陪伴〉。辅导指帮助学习，陪同散步应用〈陪伴〉。"}, {"text": "老板每天辅导员工打卡。", "explanation": "这里应该用〈监督〉。辅导指帮助学习，督促员工打卡应用〈监督〉。"}, {"text": "护士辅导病房的墙壁刷漆。", "explanation": "这里应该用〈粉刷〉。辅导指帮助学习功课，给墙壁刷漆应说〈粉刷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的同学辅导我了一个小时。", "corrected_sentence": "我的同学辅导了我一个小时。", "error_description": "错误：“了”位置不对。“了”应紧跟动词，应为“辅导了我一个小时”，而不是“辅导我了一个小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐以前辅导我过写英语作业。", "corrected_sentence": "姐姐以前辅导过我写英语作业。", "error_description": "错误：“过”位置不对。“过”表示曾经有过的经历，应紧跟动词“辅导”，应为“辅导过我”，而不是“辅导我过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
