INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92584, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "帮助并指导学习。", "primary_collocate": null, "pronunciation": "fǔ dǎo", "ipa": "fu˨˩˦ taʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "李老师辅导学生准备汉语考试。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请专家辅导老师们学习新的教学方法。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授每周辅导研究生写论文。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司安排老同事辅导新员工学习电脑技术。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，老师辅导大家复习了两个小时。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上辅导留学生学习中文。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者每天下午辅导山区的孩子读书。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师认真地辅导着每一个学生。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她退休以后还在辅导年轻人学习写作。", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你辅导我复习一下历史，好吗？", "target_word": "辅导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辅导了", "label": "体标"}, {"form": "辅导着", "label": "体标"}, {"form": "辅导辅导", "label": "重叠"}, {"form": "輔導", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指导复习、写论文、学技能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df752ed1-047e-4fbd-b779-b0ded6150625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辅导", "is_correct": true, "explanation": "辅导指帮助并指导学习，“李老师辅导学生准备汉语考试”句意通顺，是唯一能填入的词。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋，不能说“装修学生”。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”的对象是物品，不能说“清洗学生”。"}, {"text": "寄", "is_correct": false, "explanation": "配价：“寄”需要寄件人、收件人和物件的结构，后接“准备汉语考试”的动词短语不成立。"}], "explanations": {"辅导": "辅导指帮助并指导学习，“李老师辅导学生准备汉语考试”句意通顺，是唯一能填入的词。", "装修": "搭配：“装修”的对象是房屋，不能说“装修学生”。", "清洗": "搭配：“清洗”的对象是物品，不能说“清洗学生”。", "寄": "配价：“寄”需要寄件人、收件人和物件的结构，后接“准备汉语考试”的动词短语不成立。"}, "sentence_index": 0, "correct_answer": "辅导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他辅导门口的自行车。", "explanation": "这里应该用〈修理〉。辅导指帮助学习和指导，修车应说〈修理〉。"}, {"text": "医生辅导病人的感冒。", "explanation": "这里应该用〈治疗〉。辅导指帮助学习和指导，治疗疾病应用〈治疗〉。"}, {"text": "儿子每天辅导奶奶散步。", "explanation": "这里应该用〈陪伴〉。辅导指帮助学习和指导，陪同奶奶散步应用〈陪伴〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辅导", "is_correct": true, "explanation": "辅导指帮助并指导学习，“志愿者每天下午辅导山区的孩子读书”句意通顺，是唯一能填入的词。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋，不能说“装修山区的孩子”。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，不能说“购买山区的孩子”。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是转换语言，不能用来指帮助孩子读书。"}], "explanations": {"辅导": "辅导指帮助并指导学习，“志愿者每天下午辅导山区的孩子读书”句意通顺，是唯一能填入的词。", "装修": "搭配：“装修”的对象是房屋，不能说“装修山区的孩子”。", "购买": "搭配：“购买”的对象是商品，不能说“购买山区的孩子”。", "翻译": "语义：“翻译”是转换语言，不能用来指帮助孩子读书。"}, "sentence_index": 6, "correct_answer": "辅导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸辅导妈妈去医院。", "explanation": "这里应该用〈陪同〉。辅导指帮助学习和指导，陪同去医院应用〈陪同〉。"}, {"text": "主人热情地辅导客人。", "explanation": "这里应该用〈招待〉。辅导指帮助学习和指导，热情接待客人应用〈招待〉。"}, {"text": "大家热烈地辅导他获奖。", "explanation": "这里应该用〈祝贺〉。辅导指帮助学习和指导，庆祝获奖应用〈祝贺〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐在辅导我着复习历史。", "corrected_sentence": "姐姐在辅导着我复习历史。", "error_description": "错误：“着”的位置不对。“着”应紧跟动词“辅导”，应为“辅导着我复习历史”，而不是“辅导我着复习历史”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对孩子很耐心，辅导的很好。", "corrected_sentence": "她对孩子很耐心，辅导得很好。", "error_description": "错误：补语标记用错。“得”用在动词后引出补语，这里应为“辅导得很好”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
