INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92588, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "道路、桥梁等开始通行车辆。", "primary_collocate": null, "pronunciation": "tōng chē", "ipa": "tʰʊŋ˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "这座大桥去年十月通车。", "target_word": "通车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "隧道通车后，两个城市近多了。", "target_word": "通车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新大桥通车那天，很多人来拍照。", "target_word": "通车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高速公路通车以后，路上的车多了。", "target_word": "通车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁三号线下个月通车。", "target_word": "通车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条高速公路已经通车半年了。", "target_word": "通车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大桥明年通车，去海边就方便了。", "target_word": "通车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，那条铁路五十年前就通车了。", "target_word": "通车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条山路太窄，现在还不能通车。", "target_word": "通车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新桥通车以前，大家要坐船过河。", "target_word": "通车", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "通车了", "label": "体标"}, {"form": "通车典礼", "label": "复合"}, {"form": "通车仪式", "label": "复合"}], "register": "中性", "sense_fingerprint": "道路、桥梁、隧道等开始通行车辆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62eac6f8-55d8-4516-a7c5-4d8181c28db1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92588, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通车", "is_correct": true, "explanation": "正确答案。道路、桥梁等开始通行车辆。"}, {"text": "童车", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，童车指婴儿车。"}, {"text": "空车", "is_correct": false, "explanation": "kōng 与 tōng 声母不同（k 与 t），空车指没有载人或载货的车。"}, {"text": "同车", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，同车指同乘一辆车。"}], "explanations": {"通车": "正确答案。道路、桥梁等开始通行车辆。", "童车": "tóng（第二声）与 tōng（第一声）声调不同，童车指婴儿车。", "空车": "kōng 与 tōng 声母不同（k 与 t），空车指没有载人或载货的车。", "同车": "tóng（第二声）与 tōng（第一声）声调不同，同车指同乘一辆车。"}, "sentence_index": null, "correct_answer": "通车"}, "level_3": {"options": [{"text": "通车", "is_correct": true, "explanation": "大桥去年十月开始通行车辆，“去年十月通车”说得通。"}, {"text": "开幕", "is_correct": false, "explanation": "搭配：“开幕”用于展览、会议等活动，不说桥梁开幕。"}, {"text": "放映", "is_correct": false, "explanation": "搭配：“放映”用于电影，桥梁不说放映。"}, {"text": "放假", "is_correct": false, "explanation": "语义：桥梁不放假，“去年十月”与放假无关。"}], "explanations": {"通车": "大桥去年十月开始通行车辆，“去年十月通车”说得通。", "开幕": "搭配：“开幕”用于展览、会议等活动，不说桥梁开幕。", "放映": "搭配：“放映”用于电影，桥梁不说放映。", "放假": "语义：桥梁不放假，“去年十月”与放假无关。"}, "sentence_index": 0, "correct_answer": "通车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河通车以后，大船多了。", "explanation": "这里应该用〈通航〉。通车指道路、桥梁可以行车，河道能通船要说〈通航〉。"}, {"text": "这座公园通车以后，游客多了。", "explanation": "这里应该用〈开放〉。通车只用于道路、桥梁，公园对外开放要说〈开放〉。"}, {"text": "这座水库明年通车，附近农田就能灌溉了。", "explanation": "这里应该用〈放水〉。通车只用于道路、桥梁，水库供水灌溉要说〈放水〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通车", "is_correct": true, "explanation": "大桥明年可以开始通行车辆，“明年通车”说得通。"}, {"text": "开课", "is_correct": false, "explanation": "搭配：“开课”是学校的事，不说大桥开课。"}, {"text": "开业", "is_correct": false, "explanation": "语义：“开业”指商店、企业开始营业，大桥不说开业。"}, {"text": "放学", "is_correct": false, "explanation": "搭配：“放学”指学生离校，桥梁不说放学。"}], "explanations": {"通车": "大桥明年可以开始通行车辆，“明年通车”说得通。", "开课": "搭配：“开课”是学校的事，不说大桥开课。", "开业": "语义：“开业”指商店、企业开始营业，大桥不说开业。", "放学": "搭配：“放学”指学生离校，桥梁不说放学。"}, "sentence_index": 6, "correct_answer": "通车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新医院通车以后，大家都很方便。", "explanation": "这里应该用〈投入使用〉。通车只用于道路、桥梁，医院要说〈投入使用〉。"}, {"text": "电话通车以后，我们就能聊天了。", "explanation": "这里应该用〈接通〉。通车指道路可以行车，电话线路开通要说〈接通〉。"}, {"text": "新超市通车以后，人很多。", "explanation": "这里应该用〈开业〉。通车用于道路、桥梁，超市开始营业要说〈开业〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条高速路去年夏天终于被通车了。", "corrected_sentence": "这条高速路去年夏天终于通车了。", "error_description": "错误：“被通车”。正确：“通车了”。“通车”是不及物动词，不能用“被”字句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条隧道前年就把通车了。", "corrected_sentence": "这条隧道前年就通车了。", "error_description": "错误：“通车”是不及物动词，不能用“把”字句。正确：“通车了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
