INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92590, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好使是东西、器官或头脑运转灵便，用起来方便。", "primary_collocate": null, "pronunciation": "hǎo shǐ", "ipa": "xɑʊ˧˥ ʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个新软件挺好使的，我天天用。", "target_word": "好使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的腿脚不太好使了。", "target_word": "好使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪大了，耳朵不好使。", "target_word": "好使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把锁不好使，总是打不开。", "target_word": "好使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个扳手比那个好使。", "target_word": "好使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台打印机好使，一分钟能印十页。", "target_word": "好使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子脑子好使，一学就会。", "target_word": "好使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个遥控器不好使，按了没反应。", "target_word": "好使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天买的拖把真好使，一擦地就干净。", "target_word": "好使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这台电脑还好使吗？", "target_word": "好使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "器物、器官或头脑运转灵便好用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7018439-109a-4c8c-8d0d-ce7e3899b663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92590, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好使", "is_correct": true, "explanation": "“好使”指东西好用、使用起来方便灵便，是本词。"}, {"text": "好事", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是“好事”，指好的事情。"}, {"text": "好诗", "is_correct": false, "explanation": "shǐ（第三声）与 shī（第一声）声调不同，意思是“好诗”，指写得好的诗。"}, {"text": "好死", "is_correct": false, "explanation": "声母混淆：sǐ 与 shǐ 只差 s/sh，声调同为第三声；“好死”是真实短语，意为死得安然。"}], "explanations": {"好使": "“好使”指东西好用、使用起来方便灵便，是本词。", "好事": "shǐ（第三声）与 shì（第四声）声调不同，意思是“好事”，指好的事情。", "好诗": "shǐ（第三声）与 shī（第一声）声调不同，意思是“好诗”，指写得好的诗。", "好死": "声母混淆：sǐ 与 shǐ 只差 s/sh，声调同为第三声；“好死”是真实短语，意为死得安然。"}, "sentence_index": null, "correct_answer": "好使"}, "level_3": {"options": [{"text": "好使", "is_correct": true, "explanation": "“好使”指好用、方便，与“我天天用”相符。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或物的体型，不用于形容软件。"}, {"text": "年迈", "is_correct": false, "explanation": "语域：“年迈”是书面语，且只形容老人，不能用于软件。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容环境安静，不能用来评价软件好不好用。"}], "explanations": {"好使": "“好使”指好用、方便，与“我天天用”相符。", "高大": "搭配：“高大”形容人或物的体型，不用于形容软件。", "年迈": "语域：“年迈”是书面语，且只形容老人，不能用于软件。", "寂静": "语义：“寂静”形容环境安静，不能用来评价软件好不好用。"}, "sentence_index": 0, "correct_answer": "好使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子很好使，住着很舒服。", "explanation": "这里应该用〈宽敞〉。好使形容东西用起来方便，不形容房间的大小。"}, {"text": "他的声音很好使，大家都爱听。", "explanation": "这里应该用〈好听〉。好使不用来形容声音的美妙。"}, {"text": "这件衣服很好使，穿着很舒服。", "explanation": "这里应该用〈合身〉。好使形容东西用起来方便，不用来说衣服的尺寸是否合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好使", "is_correct": true, "explanation": "“好使”形容脑子反应快，与“一学就会”相符。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：“好看”形容外貌，不能用来说脑子。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”说的是重量，与“一学就会”的快速学习相矛盾。"}, {"text": "圆润", "is_correct": false, "explanation": "搭配：“圆润”形容声音或形状，不能用于脑子。"}], "explanations": {"好使": "“好使”形容脑子反应快，与“一学就会”相符。", "好看": "搭配：“好看”形容外貌，不能用来说脑子。", "沉重": "语义：“沉重”说的是重量，与“一学就会”的快速学习相矛盾。", "圆润": "搭配：“圆润”形容声音或形状，不能用于脑子。"}, "sentence_index": 6, "correct_answer": "好使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的议程还好使吗？", "explanation": "这里应该用〈合理〉。好使说的是东西用起来方便灵便，不用来评价会议的安排。"}, {"text": "这个城市的天气还好使吗？", "explanation": "这里应该用〈怎么样〉。好使说的是东西用起来方便灵便，不用来问天气。"}, {"text": "这份报告的内容还好使吗？", "explanation": "这里应该用〈正确〉。好使只说东西用起来方便，不用来评价报告的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电视挺好使得，我每天看。", "corrected_sentence": "这台电视挺好使的，我每天看。", "error_description": "“挺……的”格式中句末应该用“的”。“得”用在动词或形容词后引出补语，这里写成“得”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个闹钟不了好使，总是响不起来。", "corrected_sentence": "这个闹钟不好使，总是响不起来。", "error_description": "“了”误放在否定词“不”与形容词“好使”之间，否定形式应为“不好使”，“了”不能插入其中。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
