INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出生不久、还不会走路说话的小孩子。", "primary_collocate": null, "pronunciation": "yīng ér", "ipa": "iŋ˥ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "婴儿还不会走路。", "target_word": "婴儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个婴儿还不会说话。", "target_word": "婴儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "婴儿只会哭，不会告诉你哪里难受。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个婴儿爬着去拿玩具。", "target_word": "婴儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿不会自己吃饭，要大人喂。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有个婴儿，正在学着爬。", "target_word": "婴儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿听不懂话，但喜欢听妈妈的声音。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位爸爸一只手抱着婴儿，一只手拿包。", "target_word": "婴儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿不能自己站起来，需要大人扶。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑着对婴儿说话，婴儿也笑了。", "target_word": "婴儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个婴儿", "label": "量词"}, {"form": "婴儿车", "label": "复合"}, {"form": "婴儿床", "label": "复合"}], "register": "中性", "sense_fingerprint": "还不会走路、不会说话、需要大人照顾的小孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1928561-c547-4f0d-a7bb-b100578bce76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "婴儿", "is_correct": true, "explanation": "正确。婴儿指还不会走路的小孩，与“还不会走路”相符。"}, {"text": "大学生", "is_correct": false, "explanation": "语义：大学生早已会走路，不可能“还不会走路”。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“走路”的主语应是人或动物，电脑不能说“走路”。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：运动员不可能还不会走路。"}], "explanations": {"婴儿": "正确。婴儿指还不会走路的小孩，与“还不会走路”相符。", "大学生": "语义：大学生早已会走路，不可能“还不会走路”。", "电脑": "搭配：“走路”的主语应是人或动物，电脑不能说“走路”。", "运动员": "语义：运动员不可能还不会走路。"}, "sentence_index": 0, "correct_answer": "婴儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个婴儿已经能自己走路去上学了。", "explanation": "这里应该用〈小学生〉。婴儿还不会走路，不能自己走路去上学。"}, {"text": "妈妈给我买了一台婴儿。", "explanation": "这里应该用〈个〉。量词“台”用于机器，指人要用“个”。"}, {"text": "我的婴儿已经能自己穿衣服了。", "explanation": "这里应该用〈孩子〉。婴儿还不会自己穿衣，能自己穿衣的要说孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "婴儿", "is_correct": true, "explanation": "正确。婴儿听不懂话，但喜欢听妈妈的声音，主语是会听会感觉的小孩。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感觉，不会“喜欢听”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“听不懂话”和“喜欢”的主语必须是有生命的，汽车不能这样说。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会听，也不会喜欢任何声音。"}], "explanations": {"婴儿": "正确。婴儿听不懂话，但喜欢听妈妈的声音，主语是会听会感觉的小孩。", "石头": "语义：石头没有感觉，不会“喜欢听”。", "汽车": "搭配：“听不懂话”和“喜欢”的主语必须是有生命的，汽车不能这样说。", "窗户": "语义：窗户不会听，也不会喜欢任何声音。"}, "sentence_index": 6, "correct_answer": "婴儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她买了一辆婴儿，放在门口。", "explanation": "这里应该用〈个〉。量词“辆”用于车辆，指人要用“个”。"}, {"text": "这个婴儿已经会说很多话了。", "explanation": "这里应该用〈幼儿〉。婴儿还不会说话，已经会说很多话的要说幼儿。"}, {"text": "放学以后，婴儿要自己写作业。", "explanation": "这里应该用〈中学生〉。婴儿还不会写字，写作业的要说中学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那两婴儿还不会说话。", "corrected_sentence": "那两个婴儿还不会说话。", "error_description": "“两”和名词之间漏了量词。应说“两个婴儿”，不能说“两婴儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只婴儿总是要人抱着。", "corrected_sentence": "这个婴儿总是要人抱着。", "error_description": "“婴儿”指人，量词应用“个”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
