INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92598, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有能够达到或实现（目标、要求、标准）。", "primary_collocate": null, "pronunciation": "dá bú dào", "ipa": "ta˧˥ pu˧˥ taʊ˥˩", "syllable_count": 3, "sentences": [{"text": "今年的目标，我们恐怕达不到。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车坏了，我们今天达不到计划的进度。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时间太少，我们达不到原来的目标。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱不够，我们还达不到买房子的目标。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个产品质量太差，达不到要求。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路太难走，我们今天达不到计划的速度。", "target_word": "达不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间太短，工作达不到预期的结果。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有好的方法，我们的目的达不到。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的速度太慢，达不到比赛的标准。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个目标很难，现在还达不到。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "达得到", "label": "可能补语肯定式"}, {"form": "達不到", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词；没能到达某地或实现某个目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2be088-64c2-41e3-84d8-6c7e9081f3dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92598, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "达不到", "is_correct": true, "explanation": "达不到（dá bú dào）：没能到达某地或实现某个目标，是本词。"}, {"text": "拿不到", "is_correct": false, "explanation": "拿（ná）与达（dá）声母不同（n 与 d），意思是拿不到东西，不是没能到达。"}, {"text": "打不到", "is_correct": false, "explanation": "打（dǎ）与达（dá）声调不同（第三声与第二声），意思是打不着，不是没能到达。"}, {"text": "搭不到", "is_correct": false, "explanation": "搭（dā）与达（dá）声调不同（第一声与第二声），意思是搭不到车，不是没能到达。"}], "explanations": {"达不到": "达不到（dá bú dào）：没能到达某地或实现某个目标，是本词。", "拿不到": "拿（ná）与达（dá）声母不同（n 与 d），意思是拿不到东西，不是没能到达。", "打不到": "打（dǎ）与达（dá）声调不同（第三声与第二声），意思是打不着，不是没能到达。", "搭不到": "搭（dā）与达（dá）声调不同（第一声与第二声），意思是搭不到车，不是没能到达。"}, "sentence_index": null, "correct_answer": "达不到"}, "level_3": {"options": [{"text": "达不到", "is_correct": true, "explanation": "“恐怕”之后需要表示没能实现目标，达不到符合。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步与目标能否实现无关，句子语义不通。"}, {"text": "听懂", "is_correct": false, "explanation": "搭配：“听懂”的对象是话语，不能与“目标”搭配。"}, {"text": "喝醉", "is_correct": false, "explanation": "语义：喝醉是身体状态，与目标能否实现无关，句子不通。"}], "explanations": {"达不到": "“恐怕”之后需要表示没能实现目标，达不到符合。", "散步": "语义：散步与目标能否实现无关，句子语义不通。", "听懂": "搭配：“听懂”的对象是话语，不能与“目标”搭配。", "喝醉": "语义：喝醉是身体状态，与目标能否实现无关，句子不通。"}, "sentence_index": 0, "correct_answer": "达不到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的梦想终于达不到了。", "explanation": "这里应该用〈实现〉。“达不到”指没能到达或实现，梦想终于成功要用实现，不能说“终于达不到”。"}, {"text": "我们终于达不到山顶。", "explanation": "这里应该用〈到达〉。“终于”表示成功到达，“达不到”表示没能到达，与语境相反。"}, {"text": "这项政策终于达不到。", "explanation": "这里应该用〈落实〉。“终于”表示成功落实，“达不到”表示没能实现，与语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "达不到", "is_correct": true, "explanation": "“工作”之后需要接表示没能实现的结果，达不到符合。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记说的是记不住，与工作能否实现预期结果无关，句子不通。"}, {"text": "看着", "is_correct": false, "explanation": "搭配：“看着”后一般接人或具体事物，不能与“预期的结果”搭配。"}, {"text": "扔掉", "is_correct": false, "explanation": "搭配：结果不能被扔掉，“扔掉”与“预期的结果”不搭配。"}], "explanations": {"达不到": "“工作”之后需要接表示没能实现的结果，达不到符合。", "忘记": "语义：忘记说的是记不住，与工作能否实现预期结果无关，句子不通。", "看着": "搭配：“看着”后一般接人或具体事物，不能与“预期的结果”搭配。", "扔掉": "搭配：结果不能被扔掉，“扔掉”与“预期的结果”不搭配。"}, "sentence_index": 6, "correct_answer": "达不到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们终于达不到这个任务。", "explanation": "这里应该用〈完成〉。“达不到”说的是没能达到目标或标准，说把任务做完要用完成。"}, {"text": "飞机终于达不到目的地了。", "explanation": "这里应该用〈抵达〉。“终于”表示成功到达，“达不到”表示没能到达，与语境相反。"}, {"text": "他们终于达不到难关。", "explanation": "这里应该用〈度过〉。“达不到”指没能到达或实现，不能用来说克服了难关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车太慢，我们今晚达不到过计划的速度。", "corrected_sentence": "车太慢，我们今晚达不到计划的速度。", "error_description": "体标错误：可能补语否定式“达不到”后不能加体标“过”，应删去“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们今年很达不到这个目标。", "corrected_sentence": "我们今年怎么也达不到这个目标。", "error_description": "副词错误：“很”不能修饰“达不到”，应用“怎么也”表示无论如何都没能实现。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
