INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92603, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进球就是把球踢进或投进球门里，或者投进篮筐里。", "primary_collocate": null, "pronunciation": "jìn qiú", "ipa": "tɕin˥˩ tɕʰiou˧˥", "syllable_count": 2, "sentences": [{"text": "我一脚把球踢出去，可惜没进球。", "target_word": "进球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟投篮很准，每次都能进球。", "target_word": "进球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园踢足球，谁先进球谁赢。", "target_word": "进球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跳起来投篮，球在篮筐上转了一圈，进球了。", "target_word": "进球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把球踢进门里才算进球。", "target_word": "进球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门员很厉害，对方一直没有进球。", "target_word": "进球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我在球场上进球了，妈妈也来看了。", "target_word": "进球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友第一次进球，开心得大叫起来。", "target_word": "进球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了很久，现在投篮常常进球。", "target_word": "进球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，进球之后要先和队友一起庆祝。", "target_word": "进球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进了球", "label": "完成体"}, {"form": "进过球", "label": "经历体"}, {"form": "进球数", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把球踢进球门或投进篮筐里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c39e31-92d1-407d-a2da-901a9781bb50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92603, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进球", "is_correct": true, "explanation": "正确。进球指把球踢进或投进球门、篮筐。"}, {"text": "金球", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，金球指金色的球，与进球意思不同。"}, {"text": "禁区", "is_correct": false, "explanation": "qiú（第二声）与 qū（第一声）韵母不同，禁区指禁止进入的区域，足球中指罚球区。"}, {"text": "金秋", "is_correct": false, "explanation": "jìn 与 jīn、qiú 与 qiū 声调都不同，金秋指秋天。"}], "explanations": {"进球": "正确。进球指把球踢进或投进球门、篮筐。", "金球": "jìn（第四声）与 jīn（第一声）声调不同，金球指金色的球，与进球意思不同。", "禁区": "qiú（第二声）与 qū（第一声）韵母不同，禁区指禁止进入的区域，足球中指罚球区。", "金秋": "jìn 与 jīn、qiú 与 qiū 声调都不同，金秋指秋天。"}, "sentence_index": null, "correct_answer": "进球"}, "level_3": {"options": [{"text": "进球", "is_correct": true, "explanation": "正确。“可惜没进球”指踢出的球没有射入球门。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：前一句说的是踢球，“下棋”与踢球的情境不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：前一句说的是踢球，“唱歌”与踢球的情境不符。"}, {"text": "进账", "is_correct": false, "explanation": "语域：“进账”是经营、财务用语，用在踢球的语境中不合语域。"}], "explanations": {"进球": "正确。“可惜没进球”指踢出的球没有射入球门。", "下棋": "语义：前一句说的是踢球，“下棋”与踢球的情境不符。", "唱歌": "语义：前一句说的是踢球，“唱歌”与踢球的情境不符。", "进账": "语域：“进账”是经营、财务用语，用在踢球的语境中不合语域。"}, "sentence_index": 0, "correct_answer": "进球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在排球比赛中进球了。", "explanation": "这里应该用〈得分〉。进球只指球射入球门或篮筐，排球没有球门，应说得分。"}, {"text": "他从农村进球，找了份工作。", "explanation": "这里应该用〈进城〉。进球只用于球类比赛，不能用于人进入城市。"}, {"text": "这家店每周都去批发市场进球。", "explanation": "这里应该用〈进货〉。进球只指球类运动中得分，不能用于商品的购进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92603, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "进球", "is_correct": true, "explanation": "正确。进球指把球踢进或投进球门、篮筐。"}, {"text": "进修", "is_correct": false, "explanation": "qiú（第二声）与 xiū（第一声）声母与声调都不同，进修指进一步学习。"}, {"text": "金球", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，金球指金色的球，与进球意思不同。"}, {"text": "进气", "is_correct": false, "explanation": "qiú（第二声）与 qì（第四声）韵母不同，进气指空气等进入体内。"}, {"text": "新球", "is_correct": false, "explanation": "jìn 与 xīn 声母与声调不同，新球指新的球。"}], "explanations": {"进球": "正确。进球指把球踢进或投进球门、篮筐。", "进修": "qiú（第二声）与 xiū（第一声）声母与声调都不同，进修指进一步学习。", "金球": "jìn（第四声）与 jīn（第一声）声调不同，金球指金色的球，与进球意思不同。", "进气": "qiú（第二声）与 qì（第四声）韵母不同，进气指空气等进入体内。", "新球": "jìn 与 xīn 声母与声调不同，新球指新的球。"}, "sentence_index": null, "correct_answer": "进球"}, "level_3": {"options": [{"text": "进球", "is_correct": true, "explanation": "正确。“在球场上进球了”指在球场上把球射入球门得分。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：球场上不会做饭，与“球场上”的比赛情境冲突。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：球场上不能洗澡，与“球场上”的情境冲突。"}, {"text": "投资", "is_correct": false, "explanation": "配价：“投资”需要投资对象作宾语，“球场上”不能作其对象，搭配不成立。"}], "explanations": {"进球": "正确。“在球场上进球了”指在球场上把球射入球门得分。", "做饭": "语义：球场上不会做饭，与“球场上”的比赛情境冲突。", "洗澡": "语义：球场上不能洗澡，与“球场上”的情境冲突。", "投资": "配价：“投资”需要投资对象作宾语，“球场上”不能作其对象，搭配不成立。"}, "sentence_index": 6, "correct_answer": "进球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月公司进球了二十万。", "explanation": "这里应该用〈进账〉。进球只指球类比赛得分，不能用于公司收入。"}, {"text": "他去国外进球了一年。", "explanation": "这里应该用〈进修〉。进球只指球入球门得分，不能用于人到国外学习。"}, {"text": "这台机器从德国进球。", "explanation": "这里应该用〈进口〉。进球只指球类比赛中的得分，不能用于商品从国外购入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一次也没进了球。", "corrected_sentence": "他一次也没进球。", "error_description": "错误形式“没进了球”，正确形式“没进球”。“没”否定已发生的动作时，动词后不能再加完成标记“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们队在第二节进球了一个。", "corrected_sentence": "我们队在第二节进球了。", "error_description": "错误形式“进球了一个”，正确形式“进球了”。“进球”本身表示把球射入球门得分，后面不能再直接接“一个”表示数量，数量应说成“进了一个球”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
