INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92606, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公开发表的重要声明或主张。", "primary_collocate": null, "pronunciation": "xuān yán", "ipa": "ɕɥɛn˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "大会发表了一份重要的宣言。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份宣言向全世界说明了我们的主张。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府发表宣言，表示支持和平。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份宣言让很多人看到了新的希望。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宣言里写着：人人生来平等。", "target_word": "宣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在广场上宣读了他们的宣言。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇宣言只有几百字，却影响了世界。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教授认为，这份宣言是历史上的大事。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们公开发表宣言，要求保护环境。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宣言发表以后，各国都表示欢迎。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "独立宣言", "label": "复合"}], "register": "书面", "sense_fingerprint": "公开发表的重要声明或主张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a18bcdf7-86f3-4acd-8a8e-ebb3966c20cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣言", "is_correct": true, "explanation": "正确。“宣言”是公开发表的重要声明，可以被“发表”，与句意相符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“发表”用于声明、文章、作品，不能说“发表空气”。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“发表”不能用于“脚步”，句意不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“发表脾气”不成立，与“重要的”语境相悖，句意荒谬。"}], "explanations": {"宣言": "正确。“宣言”是公开发表的重要声明，可以被“发表”，与句意相符。", "空气": "搭配：“发表”用于声明、文章、作品，不能说“发表空气”。", "脚步": "搭配：“发表”不能用于“脚步”，句意不通。", "脾气": "语义：“发表脾气”不成立，与“重要的”语境相悖，句意荒谬。"}, "sentence_index": 0, "correct_answer": "宣言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们制定了一份宣言，安排了下周的工作。", "explanation": "这里应该用〈计划〉。宣言是公开发表的重要主张，不用于内部的工作安排。"}, {"text": "他拿到了一份宣言，上面写着期末成绩。", "explanation": "这里应该用〈成绩单〉。宣言是公开的主张，不能用来记录个人成绩。"}, {"text": "这首宣言让很多人看到了新的希望。", "explanation": "这里应该用〈歌〉。〈首〉用于歌曲、诗词，宣言是书面文件，“首”不能用来修饰宣言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣言", "is_correct": true, "explanation": "正确。“宣言”是公开发表的重要声明，“篇”可以用于文章类文件，与“几百字”相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“篇”用于文章，不用于歌曲，句中“几百字”也不适合歌曲。"}, {"text": "桥梁", "is_correct": false, "explanation": "搭配：“篇”不能用于桥梁，且桥梁不能“只有几百字”。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：疾病不是可以用“几百字”来描述的文本，与“篇”不搭，句意不通。"}], "explanations": {"宣言": "正确。“宣言”是公开发表的重要声明，“篇”可以用于文章类文件，与“几百字”相符。", "歌曲": "搭配：“篇”用于文章，不用于歌曲，句中“几百字”也不适合歌曲。", "桥梁": "搭配：“篇”不能用于桥梁，且桥梁不能“只有几百字”。", "疾病": "语义：疾病不是可以用“几百字”来描述的文本，与“篇”不搭，句意不通。"}, "sentence_index": 6, "correct_answer": "宣言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给大家跳了一段宣言，大家都很感动。", "explanation": "这里应该用〈舞〉。宣言是书面的主张，不能用“跳”。"}, {"text": "妈妈给孩子唱宣言。", "explanation": "这里应该用〈歌〉。宣言是公开发表的主张，不能“唱”。"}, {"text": "这台宣言很好用，洗衣服很快。", "explanation": "这里应该用〈洗衣机〉。宣言是公开发表的书面主张，不是能用来洗衣服的机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工会公开发表了一宣言。", "corrected_sentence": "工会公开发表了一份宣言。", "error_description": "错误形式：“一宣言”。正确形式：“一份宣言”。宣言是书面文件，数量词“一”后要带量词“份”，不能直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份宣言发表着以后，各国都很重视。", "corrected_sentence": "这份宣言发表以后，各国都很重视。", "error_description": "错误形式：“发表着以后”。正确形式：“发表以后”。“发表”是一次性的动作，不能加“着”表示持续，“以后”前不加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
