INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92608, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用得不当；误用。", "primary_collocate": null, "pronunciation": "cuò yòng", "ipa": "tsʰwo˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个词在这里错用了。", "target_word": "错用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把成语错用了。", "target_word": "错用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章时，别错用标点符号。", "target_word": "错用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人常常错用这个字。", "target_word": "错用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我错用了“的”和“地”。", "target_word": "错用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他错用了一个词，大家都笑了。", "target_word": "错用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个成语我以前错用过。", "target_word": "错用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "错用词语会让别人听不懂。", "target_word": "错用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作文里有两个词错用了。", "target_word": "错用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话时错用了称呼，他有点不好意思。", "target_word": "错用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "错用了", "label": "体标"}, {"form": "错用过", "label": "体标"}, {"form": "錯用", "label": "繁体"}], "register": "中性", "sense_fingerprint": "词语等用得不当，误用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee2df57-fb87-4f86-b7e0-dc23161c9f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92608, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "错用", "is_correct": true, "explanation": "正确：“错用”表示词语用得不当，符合“词在这里”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃这个词”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：词语不能被咬，与句中的对象不相容。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、身体等，不能说“洗这个词”。"}], "explanations": {"错用": "正确：“错用”表示词语用得不当，符合“词在这里”的语境。", "吃": "搭配：“吃”的对象是食物，不能说“吃这个词”。", "咬": "语义：词语不能被咬，与句中的对象不相容。", "洗": "搭配：“洗”的对象是衣物、身体等，不能说“洗这个词”。"}, "sentence_index": 0, "correct_answer": "错用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他错用了她的心情。", "explanation": "这里应该用〈理解〉。“错用”的对象是词语或方法，心情不能被错用；体会别人的心情要说“理解”。"}, {"text": "孩子错用了一个苹果。", "explanation": "这里应该用〈吃〉。“错用”的对象是词语或方法，苹果是食物，不能被错用；吃东西要说“吃”。"}, {"text": "他错用了天气变化。", "explanation": "这里应该用〈关注〉。“错用”的对象是词语或方法，天气变化不能被错用；注意天气变化要说“关注”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错用", "is_correct": true, "explanation": "正确：“错用”表示用得不当，与“以前……过”的经历相符。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球等物体，不能说“踢这个成语”。"}, {"text": "闻", "is_correct": false, "explanation": "搭配：“闻”的对象是气味，成语不能被“闻”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：成语是语言，不能被扔掉，与句中的对象不相容。"}], "explanations": {"错用": "正确：“错用”表示用得不当，与“以前……过”的经历相符。", "踢": "搭配：“踢”的对象是球等物体，不能说“踢这个成语”。", "闻": "搭配：“闻”的对象是气味，成语不能被“闻”。", "扔": "语义：成语是语言，不能被扔掉，与句中的对象不相容。"}, "sentence_index": 6, "correct_answer": "错用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他错用了心扉。", "explanation": "这里应该用〈打开〉。“错用”的对象是词语或方法，心扉不能被错用；敞开心扉要说“打开”。"}, {"text": "他错用了你的道歉。", "explanation": "这里应该用〈接受〉。“错用”的对象是词语或方法，道歉不能被错用；接受别人的道歉要说“接受”。"}, {"text": "他错用了那颗星星。", "explanation": "这里应该用〈观察〉。“错用”的对象是词语或方法，星星不能被错用；观察星星要说“观察”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这个词错用，文章很乱。", "corrected_sentence": "他把这个词错用了，文章很乱。", "error_description": "“把”字句缺少成分：“把”字句中动词后需带“了”等成分，应说“他把这个词错用了”，不能说“他把这个词错用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个成语我以前错用了过，后来改正了。", "corrected_sentence": "这个成语我以前错用过，后来改正了。", "error_description": "“了”与“过”重复：“错用过”已表示经历，不能再加“了”，应说“错用过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
