INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92611, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "选项是题目下面给你挑的几个答案。", "primary_collocate": null, "pronunciation": "xuǎn xiàng", "ipa": "ɕɥɛn²¹⁴ ɕjɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "选择题的选项是A、B、C、D。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，每道题只有一个正确选项。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看了两遍，还是不知道选哪个选项。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题的第三个选项是错的。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会做，就随便选了一个选项。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "答案就在选项B里。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "题目不难，但是选项很容易搞错。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你选的选项写在纸上。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看完题目，先排除了两个选项。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个选项看起来都很像。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "选项卡", "label": "复合"}, {"form": "選項", "label": "繁体"}], "register": "口语", "sense_fingerprint": "题目下面供人挑选的答案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0951d8-de99-4fb1-907c-73c4f740a35d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分数", "is_correct": false, "explanation": "语义：分数是数值，不是A、B、C、D这样的字母标号。"}, {"text": "选项", "is_correct": true, "explanation": "正确：“选项”指题目中的字母标号选项，符合“选择题的……是A、B、C、D”的语境。"}, {"text": "题干", "is_correct": false, "explanation": "语义：题干是题目的文字，不是字母标号。"}, {"text": "步骤", "is_correct": false, "explanation": "搭配：“步骤”不说“是A、B、C、D”，与字母标号的说法搭配不当。"}], "explanations": {"分数": "语义：分数是数值，不是A、B、C、D这样的字母标号。", "选项": "正确：“选项”指题目中的字母标号选项，符合“选择题的……是A、B、C、D”的语境。", "题干": "语义：题干是题目的文字，不是字母标号。", "步骤": "搭配：“步骤”不说“是A、B、C、D”，与字母标号的说法搭配不当。"}, "sentence_index": 0, "correct_answer": "选项"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个选项我们必须尽快解决。", "explanation": "这里应该用〈问题〉。选项是备选答案，不能被“解决”；要解决的是问题。"}, {"text": "两个选项参加了竞选。", "explanation": "这里应该用〈候选人〉。选项不是人，不能“参加竞选”。"}, {"text": "我看了一根选项。", "explanation": "这里应该用〈个〉。选项是抽象的备选项，“根”用于细长的东西，不能计量选项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以“搞错”的对象，与句中的对比不合。"}, {"text": "选项", "is_correct": true, "explanation": "正确：“选项”是容易搞错的对象，与“题目不难”形成对比，语义通顺。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会被“搞错”，句子语义不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”与题目无关，不能和“题目不难”形成对比。"}], "explanations": {"天气": "语义：天气不是可以“搞错”的对象，与句中的对比不合。", "选项": "正确：“选项”是容易搞错的对象，与“题目不难”形成对比，语义通顺。", "房子": "语义：房子不会被“搞错”，句子语义不通。", "性格": "语义：“性格”与题目无关，不能和“题目不难”形成对比。"}, "sentence_index": 6, "correct_answer": "选项"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于完成了这个选项。", "explanation": "这里应该用〈项目〉。选项是备选答案，不能“完成”；要完成的是项目或任务。"}, {"text": "电视选项很精彩。", "explanation": "这里应该用〈节目〉。选项是备选答案，不能用来指电视上的表演。"}, {"text": "他把两张选项看了一遍。", "explanation": "这里应该用〈个〉。选项是抽象的备选项，“张”用于纸、桌子等平面的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题只有一只正确选项。", "corrected_sentence": "这道题只有一个正确选项。", "error_description": "“选项”的量词应为“个”，“只”用于动物，不能用于选项。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把两选项都看了一遍。", "corrected_sentence": "他把两个选项都看了一遍。", "error_description": "数量词“两”后面要加量词“个”，应说“两个选项”；直接说“两选项”漏掉了量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
