INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92612, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92612, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "试题、问卷或程序中供选择的各个项目或答案。", "primary_collocate": null, "pronunciation": "xuǎn xiàng", "ipa": "ɕɥɛn²¹⁴ ɕjɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这道题有四个选项，我选了B。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问卷里每个问题都有三个选项。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在下面的选项中选一个。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个选项的意思我不太明白。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件的设置里有很多选项。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，我很难在两个选项里做决定。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你点开这个选项，就能改字体大小。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份问卷的最后一个选项是“其他”。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把正确的选项涂在答题卡上。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不同意的话，请选“否”这个选项。", "target_word": "选项", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "选项卡", "label": "复合"}, {"form": "選項", "label": "繁体"}], "register": "中性", "sense_fingerprint": "试题问卷或程序里可选的项目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0951d8-de99-4fb1-907c-73c4f740a35d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分数", "is_correct": false, "explanation": "语义：分数是成绩，不能从中“选B”，与后半句不合。"}, {"text": "选项", "is_correct": true, "explanation": "正确：“选项”是题目里供选择的答案，符合“选了B”的语境。"}, {"text": "门", "is_correct": false, "explanation": "语义：“门”与题目无关，“选了B”无法成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是题目里可以选的项目，句意不通。"}], "explanations": {"分数": "语义：分数是成绩，不能从中“选B”，与后半句不合。", "选项": "正确：“选项”是题目里供选择的答案，符合“选了B”的语境。", "门": "语义：“门”与题目无关，“选了B”无法成立。", "颜色": "语义：“颜色”不是题目里可以选的项目，句意不通。"}, "sentence_index": 0, "correct_answer": "选项"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很难在两个方案之间做选项。", "explanation": "这里应该用〈选择〉。选项指题目或问卷里备选的答案，不能说“做选项”。"}, {"text": "这场比赛的选项很厉害。", "explanation": "这里应该用〈选手〉。选项是备选答案，比赛的参与者应说“选手”。"}, {"text": "晚会的选项很精彩。", "explanation": "这里应该用〈节目〉。选项是备选答案，不能用来指晚会上的表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "答案", "is_correct": false, "explanation": "搭配：“点开”搭配文件、窗口、链接等，不说“点开答案”。"}, {"text": "选项", "is_correct": true, "explanation": "正确：“选项”是可以点开的设置项，点开后能改字体大小，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被点开，也改不了字体大小。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以点开的对象，与改字体大小无关。"}], "explanations": {"答案": "搭配：“点开”搭配文件、窗口、链接等，不说“点开答案”。", "选项": "正确：“选项”是可以点开的设置项，点开后能改字体大小，符合语境。", "天气": "语义：天气不能被点开，也改不了字体大小。", "颜色": "语义：颜色不是可以点开的对象，与改字体大小无关。"}, "sentence_index": 6, "correct_answer": "选项"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司的新选项下个月开始。", "explanation": "这里应该用〈项目〉。选项是供挑选的答案，公司的新工作计划应说“项目”。"}, {"text": "这个选项很难解决。", "explanation": "这里应该用〈问题〉。选项是备选答案，不能被“解决”；需要解决的是问题。"}, {"text": "这根选项你们都可以选。", "explanation": "这里应该用〈个〉。选项是抽象的备选项，“根”用于细长的东西，不能计量选项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题有三根选项，正确答案不在里面。", "corrected_sentence": "这道题有三个选项，正确答案不在里面。", "error_description": "“选项”前的量词应为“个”，“根”用于细长的东西，应写作“三个选项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在设置里找到了很大选项。", "corrected_sentence": "我在设置里找到了很多选项。", "error_description": "“很大”形容体积或程度，不能修饰可数的“选项”；应说“很多选项”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
