INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "计算机等设备上用手敲击输入的按键装置。", "primary_collocate": null, "pronunciation": "jiàn pán", "ipa": "tɕjɛn˥˩ pʰan˧˥", "syllable_count": 2, "sentences": [{"text": "这台计算机的键盘很好用。", "target_word": "键盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平板电脑可以连接外接键盘。", "target_word": "键盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的老手机有一个键盘，按起来很费力。", "target_word": "键盘", "complexity_tier": "T3", "furigana": "wǒ de lǎo shǒujī yǒu yí ge jiànpán, àn qǐ lái hěn fèilì.", "sentence_source": "generated"}, {"text": "他坐在电脑前，用键盘写程序。", "target_word": "键盘", "complexity_tier": "T3", "furigana": "tā zuò zài diànnǎo qián, yòng jiànpán xiě chéngxù.", "sentence_source": "generated"}, {"text": "键盘上的每个键都有字母或符号。", "target_word": "键盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上的键盘太小，我打错了字。", "target_word": "键盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用键盘输入你的名字。", "target_word": "键盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个键盘可以连接多种设备。", "target_word": "键盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的键盘有灯，晚上也能看清。", "target_word": "键盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "键盘是计算机的重要设备。", "target_word": "键盘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个键盘", "label": "量词"}, {"form": "无线键盘", "label": "复合"}, {"form": "机械键盘", "label": "复合"}, {"form": "鍵盤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "计算机等设备上用手敲击输入的按键装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee2df57-fb87-4f86-b7e0-dc23161c9f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "键盘", "is_correct": true, "explanation": "正确。键盘是计算机的输入设备，“这台计算机的键盘很好用”通顺。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是计算机的部件，句子说的是计算机的某个部件好不好用。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘与计算机无关，不能作为计算机的部件。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“很好用”用于工具、设备，不能用来形容“名字”。"}], "explanations": {"键盘": "正确。键盘是计算机的输入设备，“这台计算机的键盘很好用”通顺。", "冰箱": "语义：冰箱不是计算机的部件，句子说的是计算机的某个部件好不好用。", "窗帘": "语义：窗帘与计算机无关，不能作为计算机的部件。", "名字": "搭配：“很好用”用于工具、设备，不能用来形容“名字”。"}, "sentence_index": 0, "correct_answer": "键盘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的键盘没纸了，只好去买纸。", "explanation": "这里应该用〈打印机〉。没纸是打印机的问题，键盘不用纸。"}, {"text": "我的键盘卡住了，电视换不了台。", "explanation": "这里应该用〈遥控器〉。换台要靠遥控器，键盘是用来输入文字的，不能用来换电视频道。"}, {"text": "我用键盘拍了一张照片。", "explanation": "这里应该用〈相机〉。拍照片要用相机，键盘是用来输入文字的，不能拍照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "键盘", "is_correct": true, "explanation": "正确。键盘是用来输入文字的设备，“请用键盘输入你的名字”通顺。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚不能用来输入文字，句子无法成立。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷与输入文字无关，“请用牙刷输入”说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "配价：“输入”的工具必须是能输入文字的设备，“用雨伞”不能作为输入工具。"}], "explanations": {"键盘": "正确。键盘是用来输入文字的设备，“请用键盘输入你的名字”通顺。", "扫帚": "语义：扫帚不能用来输入文字，句子无法成立。", "牙刷": "语义：牙刷与输入文字无关，“请用牙刷输入”说不通。", "雨伞": "配价：“输入”的工具必须是能输入文字的设备，“用雨伞”不能作为输入工具。"}, "sentence_index": 6, "correct_answer": "键盘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台键盘的分辨率很高。", "explanation": "这里应该用〈显示器〉。分辨率是屏幕的参数，键盘没有分辨率。"}, {"text": "这个键盘可以开视频会议。", "explanation": "这里应该用〈摄像头〉。开视频会议要靠摄像头拍摄画面，键盘做不到。"}, {"text": "键盘能直接把纸上的文字扫进电脑。", "explanation": "这里应该用〈扫描仪〉。把纸上的文字直接扫进电脑要靠扫描，键盘只能手动输入，做不到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了一条新键盘。", "corrected_sentence": "我昨天买了一个新键盘。", "error_description": "量词错误：键盘用“个”，“条”用于细长的东西，不能用来修饰键盘。错误句中的“一条新键盘”应改为“一个新键盘”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她键盘收起来了。", "corrected_sentence": "她把键盘收起来了。", "error_description": "把字句缺少“把”：处置“键盘”要用“把”，应说“她把键盘收起来了”，不说“她键盘收起来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对开是两辆车从两头出发，往中间开。", "primary_collocate": null, "pronunciation": "duì kāi", "ipa": "tweɪ˥˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "两列火车从两头对开，中午在这里相遇。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上六点，两辆公交车同时从两个站对开。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线上的地铁从两头对开，很方便。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两艘船从两岸对开，很快就在河中间见面了。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京和上海各发一列高铁对开。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两班车从山的两边对开，在山顶相遇。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天早上，两班车从两个城市对开。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的车从两头对开，三小时后就能见面。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上，两列火车会从南北两头对开。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两趟列车每天都在同一时间对开。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对开了", "label": "体标"}, {"form": "对开过", "label": "体标"}, {"form": "對開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两辆车从两头出发，朝对方开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd4150c-a1b6-4a5e-a02d-612dc66104b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对开", "is_correct": true, "explanation": "对开指两车从两头相向开出，与“相遇”相符。"}, {"text": "停靠", "is_correct": false, "explanation": "语义：停靠是停下，不会从两头相向行进而相遇。"}, {"text": "分开", "is_correct": false, "explanation": "语义：分开是朝相反方向离去，与“相遇”矛盾。"}, {"text": "关闭", "is_correct": false, "explanation": "配价：“关闭”要带宾语（如关闭车门），不能单独用在“从两头”后面。"}], "explanations": {"对开": "对开指两车从两头相向开出，与“相遇”相符。", "停靠": "语义：停靠是停下，不会从两头相向行进而相遇。", "分开": "语义：分开是朝相反方向离去，与“相遇”矛盾。", "关闭": "配价：“关闭”要带宾语（如关闭车门），不能单独用在“从两头”后面。"}, "sentence_index": 0, "correct_answer": "对开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两班车同时从同一个车站对开，开往不同的方向。", "explanation": "这里应该用〈发车〉。对开要从两头相向开出，从同一车站开出应说“发车”。"}, {"text": "两只狗从院子的两头对开，跑到了中间。", "explanation": "这里应该用〈奔向〉。对开指两辆车从两头相向开出，狗跑向对方不能用对开。"}, {"text": "两辆车同向对开，一前一后地向北行驶。", "explanation": "这里应该用〈同行〉。对开指两车从两头相向开出，两车同向前进不能用对开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对开", "is_correct": true, "explanation": "对开指两班车从两个城市相向开出，与“每天早上”的定期运行相符。"}, {"text": "报废", "is_correct": false, "explanation": "语义：报废是车辆不能再用，与“每天早上”的定期运行矛盾。"}, {"text": "集合", "is_correct": false, "explanation": "语义：集合是聚到一处，与“从两个城市”各自出发矛盾。"}, {"text": "保养", "is_correct": false, "explanation": "配价：“保养”要带宾语（如保养车辆），不能单独用在“从两个城市”后。"}], "explanations": {"对开": "对开指两班车从两个城市相向开出，与“每天早上”的定期运行相符。", "报废": "语义：报废是车辆不能再用，与“每天早上”的定期运行矛盾。", "集合": "语义：集合是聚到一处，与“从两个城市”各自出发矛盾。", "保养": "配价：“保养”要带宾语（如保养车辆），不能单独用在“从两个城市”后。"}, "sentence_index": 6, "correct_answer": "对开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新司机对开了老司机的班次。", "explanation": "这里应该用〈替班〉。对开指两车从两头相向开出，接替别人的班次应说“替班”。"}, {"text": "三个学生从学校同时对开去郊游。", "explanation": "这里应该用〈出发〉。对开要从两头相向开出，三个学生从同一地点出发应说“出发”。"}, {"text": "这辆车从车库对开，驶上了马路。", "explanation": "这里应该用〈驶出〉。对开要两车从两头朝对方开，单独一辆车从车库开出应说“驶出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一列火车每天从北京和上海对开。", "corrected_sentence": "两列火车每天从北京和上海对开。", "error_description": "主语错误：“对开”要求两辆车从两头相向开出，主语不能是“一列火车”，应说“两列火车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两列车被从两头对开，三小时后在中间会合。", "corrected_sentence": "这两列车从两头对开，三小时后在中间会合。", "error_description": "“被”字句错误：“对开”是不及物动词，不能用“被”引出施事或受事，应去掉“被”，说“这两列车从两头对开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92618, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92618, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92618, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "用在数量词后，表示略微超过该数目（多指年龄、距离）。", "primary_collocate": null, "pronunciation": "kāi wài", "ipa": "kʰai⁵⁵ wai⁵¹", "syllable_count": 2, "sentences": [{"text": "他看上去四十开外，头发已经白了。", "target_word": "开外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老师五十开外，说话很慢。", "target_word": "开外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这儿到学校，有十里开外。", "target_word": "开外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了一公里开外，我才看到商店。", "target_word": "开外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位三十开外的男人是我们的经理。", "target_word": "开外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经六十开外了，还每天跑步。", "target_word": "开外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站在三百米开外，走路要五分钟。", "target_word": "开外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人七十开外，走路却很快。", "target_word": "开外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们站在百米开外，还是能听见他的声音。", "target_word": "开外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人里有一位三十开外的女士，穿着红衣服。", "target_word": "开外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "開外", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数量词后，表示略超过该数（年龄、距离）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0951d8-de99-4fb1-907c-73c4f740a35d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92618, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开外", "is_correct": true, "explanation": "「开外」表示略超过四十，符合“看上去”对年纪的估计。"}, {"text": "以内", "is_correct": false, "explanation": "语义：「以内」表示不超过四十岁，与“略超过”的意思相反。"}, {"text": "之中", "is_correct": false, "explanation": "语义：「之中」表示在某范围内部，不能放在年龄数字后表示概数。"}, {"text": "之前", "is_correct": false, "explanation": "搭配：「之前」用于时间或位置，不用来表示年龄的概数。"}], "explanations": {"开外": "「开外」表示略超过四十，符合“看上去”对年纪的估计。", "以内": "语义：「以内」表示不超过四十岁，与“略超过”的意思相反。", "之中": "语义：「之中」表示在某范围内部，不能放在年龄数字后表示概数。", "之前": "搭配：「之前」用于时间或位置，不用来表示年龄的概数。"}, "sentence_index": 0, "correct_answer": "开外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次数学测验满分是一百分，小明考了一百分开外。", "explanation": "这里不这么用。「开外」表示略超过某个数，而满分是上限，不能超过，应说“考了满分”。"}, {"text": "我们班一共有三十名学生，今天来了三十名开外。", "explanation": "这里不这么用。班级人数是确定的数字，「开外」只用于表示略超过的概数，不能用于确定的人数。"}, {"text": "这条路的限速是每小时六十公里开外。", "explanation": "这里不这么用。限速是上限，「开外」表示超过该数，超过限速属于违规，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开外", "is_correct": true, "explanation": "「开外」表示略超过三百米，与“走路要五分钟”的距离相合。"}, {"text": "之间", "is_correct": false, "explanation": "搭配：「之间」要求两个端点，「三百米之间」没有另一端，不能用于单个地点的距离。"}, {"text": "之中", "is_correct": false, "explanation": "语义：「之中」表示位于某一范围的内部，与「走路要五分钟」所描述的较远距离不符。"}, {"text": "以后", "is_correct": false, "explanation": "搭配：「以后」指时间在后，不能用来表示距离的概数。"}], "explanations": {"开外": "「开外」表示略超过三百米，与“走路要五分钟”的距离相合。", "之间": "搭配：「之间」要求两个端点，「三百米之间」没有另一端，不能用于单个地点的距离。", "之中": "语义：「之中」表示位于某一范围的内部，与「走路要五分钟」所描述的较远距离不符。", "以后": "搭配：「以后」指时间在后，不能用来表示距离的概数。"}, "sentence_index": 6, "correct_answer": "开外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "按照规定，这份报告不能超过三千字，他写了三千字开外。", "explanation": "这里不这么用。「开外」表示略超过某个数，用于概数；这里“不能超过”是上限，已经定死，不能说超过，应说“写了三千字”。"}, {"text": "我们是在二〇二六年开外搬进新家的。", "explanation": "这里不这么用。年份是确定的时间点，不能用「开外」表示略超过。"}, {"text": "他就住在我家隔壁，走路要三百米开外才到。", "explanation": "这里不这么用。「隔壁」指紧挨着，而「开外」表示在某个距离之外、较远，两者方向相反，不能用来形容紧邻的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈开外，但是身体很好。", "corrected_sentence": "我妈妈五十开外，但是身体很好。", "error_description": "错误在于缺少数量词。「开外」必须紧跟在数量词之后，应说「五十开外」，不能单独说「开外」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体育馆在五百开外，走路要十分钟。", "corrected_sentence": "体育馆在五百米开外，走路要十分钟。", "error_description": "错误在于数量词缺少量词。「五百」后面应加「米」，说“五百米开外”，不能只说“五百开外”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
