INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92619, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "长知识是学到新的东西。", "primary_collocate": null, "pronunciation": "zhǎng zhī shi", "ipa": "ʈʂɑŋ˨˩˦ ʈʂɨ˥ ʂɨ", "syllable_count": 3, "sentences": [{"text": "看这个节目真长知识。", "target_word": "长知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天听了老师的讲座，真长知识。", "target_word": "长知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去博物馆能长知识，孩子们都爱去。", "target_word": "长知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国旅行不但好玩，还能长知识。", "target_word": "长知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱看纪录片，说又长知识又好看。", "target_word": "长知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有意思，读完真长知识。", "target_word": "长知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟爷爷去农村住几天，也能长知识。", "target_word": "长知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个科学实验很有趣，大家都说长知识。", "target_word": "长知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多看新闻，多长知识，聊天时就有话说。", "target_word": "长知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参观科技馆可以长知识，还可以玩游戏。", "target_word": "长知识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "長知識", "label": "繁体"}, {"form": "长知识了", "label": "体标"}], "register": "口语", "sense_fingerprint": "看到听到后学到新东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df752ed1-047e-4fbd-b779-b0ded6150625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92619, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长知识", "is_correct": true, "explanation": "长知识：看节目能学到新东西，与句意相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能说修理节目，句意不通。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：“搬家”指迁居，与看节目无关，句意不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物件，节目不能被打扫。"}], "explanations": {"长知识": "长知识：看节目能学到新东西，与句意相符。", "修理": "搭配：“修理”的对象是器物，不能说修理节目，句意不通。", "搬家": "语义：“搬家”指迁居，与看节目无关，句意不通。", "打扫": "搭配：“打扫”的对象是场所或物件，节目不能被打扫。"}, "sentence_index": 0, "correct_answer": "长知识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盆花长知识了。", "explanation": "这里应该用〈长大〉。“长知识”指人学到新东西，花草只能说“长大”，不能用“长知识”。"}, {"text": "这棵小树这一年长知识了。", "explanation": "这里应该用〈长高〉。“长知识”只用于人学到新东西，树木变高要说“长高”。"}, {"text": "这只小猪这两个月长知识了，又胖了。", "explanation": "这里应该用〈长胖〉。“长知识”指学到新东西，小猪体重增加要说“长胖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长知识", "is_correct": true, "explanation": "长知识：住在农村能学到新东西，与“也能”的语境相符。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指输出文件，与住在农村无关，句意不通。"}, {"text": "发工资", "is_correct": false, "explanation": "搭配：“发工资”的主体是单位，住几天不能发工资，句意不通。"}, {"text": "拍卖", "is_correct": false, "explanation": "语义：“拍卖”是卖东西的活动，句中没有可拍卖的对象，句意不通。"}], "explanations": {"长知识": "长知识：住在农村能学到新东西，与“也能”的语境相符。", "打印": "语义：“打印”指输出文件，与住在农村无关，句意不通。", "发工资": "搭配：“发工资”的主体是单位，住几天不能发工资，句意不通。", "拍卖": "语义：“拍卖”是卖东西的活动，句中没有可拍卖的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "长知识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小狗这几个月长知识了，重了好几斤。", "explanation": "这里应该用〈长肉〉。“长知识”指人学到新东西，小狗体重增加要说“长肉”。"}, {"text": "这座山去年长知识了。", "explanation": "这里应该用〈长高〉。“长知识”指人学到新东西，山体升高要说“长高”。"}, {"text": "这块面团发酵以后长知识了。", "explanation": "这里应该用〈发大〉。“长知识”只用于人学到新东西，面团膨胀要说“发大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天看新闻，很快把长知识。", "corrected_sentence": "我每天看新闻，很快长知识。", "error_description": "错误在于在动宾式动词“长知识”前多加了介词“把”。“把”字句需要“把+宾语+动词+补语”的结构，“长知识”前不能直接加“把”，应删去“把”，说“很快长知识”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在博物馆长着很多知识。", "corrected_sentence": "他在博物馆长了很多知识。", "error_description": "错误：体标误用。“长知识”表示学到了新东西，是已经完成的变化，要用“了”，不能用表示持续的“着”。应说“长了很多知识”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "熟悉", "is_correct": true, "explanation": "「熟悉」与「陌生」构成反义关系，指对某地或某人的情况很了解。"}, {"text": "明亮", "is_correct": false, "explanation": "与「陌生」没有反义关系，「明亮」只说光线或环境亮。"}, {"text": "宽敞", "is_correct": false, "explanation": "与「陌生」没有反义关系，「宽敞」说空间大。"}, {"text": "善良", "is_correct": false, "explanation": "与「陌生」没有反义关系，「善良」说人的品性。"}], "correct_answer": "熟悉", "explanations": {"熟悉": "「熟悉」与「陌生」构成反义关系，指对某地或某人的情况很了解。", "明亮": "与「陌生」没有反义关系，「明亮」只说光线或环境亮。", "宽敞": "与「陌生」没有反义关系，「宽敞」说空间大。", "善良": "与「陌生」没有反义关系，「善良」说人的品性。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "熟悉", "is_correct": true, "explanation": "「熟悉」与「陌生」构成反义关系，指对事物或人很了解。"}, {"text": "丰富", "is_correct": false, "explanation": "与「陌生」没有反义关系，「丰富」说种类或数量多。"}, {"text": "干脆", "is_correct": false, "explanation": "与「陌生」没有反义关系，「干脆」说做事爽快利落。"}, {"text": "大方", "is_correct": false, "explanation": "与「陌生」没有反义关系，「大方」说态度自然、不拘束。"}], "correct_answer": "熟悉", "explanations": {"熟悉": "「熟悉」与「陌生」构成反义关系，指对事物或人很了解。", "丰富": "与「陌生」没有反义关系，「丰富」说种类或数量多。", "干脆": "与「陌生」没有反义关系，「干脆」说做事爽快利落。", "大方": "与「陌生」没有反义关系，「大方」说态度自然、不拘束。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "陌生是你从来没见过，也不认识。", "primary_collocate": null, "pronunciation": "mò shēng", "ipa": "mwɔ˥˩ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这个城市对我很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次来，这里的路都很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人我从来没见过，对我来说很陌生。", "target_word": "陌生", "complexity_tier": "T3", "furigana": "Zhè gè rén wǒ cóng lái méi jiàn guo, duì wǒ lái shuō hěn mò shēng.", "sentence_source": "generated"}, {"text": "你对这条路很陌生，晚上别一个人走。", "target_word": "陌生", "complexity_tier": "T3", "furigana": "Nǐ duì zhè tiáo lù hěn mò shēng, wǎnshang bié yí gè rén zǒu.", "sentence_source": "generated"}, {"text": "我今天到了一个陌生的地方。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字我从来没听过，很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一个人坐在陌生的教室里。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上有一个陌生号码。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚搬来时，我对邻居都很陌生。", "target_word": "陌生", "complexity_tier": "T3", "furigana": "Gāng bān lái shí, wǒ duì línjū dōu hěn mò shēng.", "sentence_source": "generated"}, {"text": "新环境对孩子来说很陌生，他有点儿怕。", "target_word": "陌生", "complexity_tier": "T3", "furigana": "Xīn huánjìng duì háizi lái shuō hěn mò shēng, tā yǒudiǎnr pà.", "sentence_source": "generated"}], "morphological_forms": [{"form": "陌生人", "label": "复合"}, {"form": "陌生感", "label": "复合"}], "register": "中性", "sense_fingerprint": "从来没见过、不认识的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5f01a3f-0c54-4133-9b25-173d415a41c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陌生", "is_correct": true, "explanation": "「陌生」表示对这个城市没有熟悉感，与句中「对我」的说法相符。"}, {"text": "干净", "is_correct": false, "explanation": "语义：「干净」说的是卫生状况，不能用来说城市对「我」的感受。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：「明亮」多用于光线、房间，不说「对我很明亮」。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：「严肃」说人的态度，不能用来形容城市对「我」的态度。"}], "explanations": {"陌生": "「陌生」表示对这个城市没有熟悉感，与句中「对我」的说法相符。", "干净": "语义：「干净」说的是卫生状况，不能用来说城市对「我」的感受。", "明亮": "搭配：「明亮」多用于光线、房间，不说「对我很明亮」。", "严肃": "语义：「严肃」说人的态度，不能用来形容城市对「我」的态度。"}, "sentence_index": 0, "correct_answer": "陌生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的游泳技术很陌生，一下水就沉下去了。", "explanation": "这里应该用〈生疏〉。「生疏」可以说技术、动作不熟练；「陌生」只说对人或事没见过、不认识，不能形容技术水平。"}, {"text": "这个现象我们很陌生，在这里已经见过很多次了。", "explanation": "这里应该用〈熟悉〉。「陌生」指没见过、不认识，与「见过很多次」矛盾；见得多、很了解要用〈熟悉〉。"}, {"text": "我每天都走这条路，这里的路对我很陌生。", "explanation": "这里应该用〈熟悉〉。「陌生」指没去过、不认识，与「每天都走这条路」矛盾；对路况很了解要用〈熟悉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陌生", "is_correct": true, "explanation": "「陌生」表示没来过、不熟悉，与「一个人坐在……的教室里」相符。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：「好吃」说食物的味道，不能形容教室。"}, {"text": "勤劳", "is_correct": false, "explanation": "语义：「勤劳」形容人肯干活，不能形容教室。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：「年轻」说人的年龄，不能形容教室。"}], "explanations": {"陌生": "「陌生」表示没来过、不熟悉，与「一个人坐在……的教室里」相符。", "好吃": "语义：「好吃」说食物的味道，不能形容教室。", "勤劳": "语义：「勤劳」形容人肯干活，不能形容教室。", "年轻": "语义：「年轻」说人的年龄，不能形容教室。"}, "sentence_index": 6, "correct_answer": "陌生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一见到我就很陌生，像亲人一样拥抱我。", "explanation": "这里应该用〈亲切〉。「陌生」指不认识，与「像亲人一样拥抱我」矛盾；对人热情亲近要用〈亲切〉。"}, {"text": "一进家门，屋里很陌生，像回到了家一样。", "explanation": "这里应该用〈温暖〉。「陌生」与「像回到了家一样」矛盾；描述家里的暖意要用〈温暖〉。"}, {"text": "我们两个配合得很陌生，一个眼神就明白了对方。", "explanation": "这里应该用〈默契〉。「陌生」只说不认识，与「一个眼神就明白」矛盾；配合心意相通要用〈默契〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我这个城市很陌生。", "corrected_sentence": "我对这个城市很陌生。", "error_description": "错误：「我这个城市很陌生」漏掉了介词「对」，感受的对象没有引出来。正确：「我对这个城市很陌生」。「陌生」常用「对……很陌生」的格式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇对我来说陌生。", "corrected_sentence": "这个小镇对我来说很陌生。", "error_description": "错误：形容词「陌生」作谓语时前面漏掉了程度副词「很」，说「陌生」显得句子不完整。正确：「这个小镇对我来说很陌生」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "熟悉", "is_correct": true, "explanation": "「熟悉」与「陌生」构成反义关系，指对事物很了解。"}, {"text": "明亮", "is_correct": false, "explanation": "与「陌生」没有反义关系，「明亮」只说光线或环境亮。"}, {"text": "宽敞", "is_correct": false, "explanation": "与「陌生」没有反义关系，「宽敞」说空间大。"}, {"text": "善良", "is_correct": false, "explanation": "与「陌生」没有反义关系，「善良」说人的品性。"}], "correct_answer": "熟悉", "explanations": {"熟悉": "「熟悉」与「陌生」构成反义关系，指对事物很了解。", "明亮": "与「陌生」没有反义关系，「明亮」只说光线或环境亮。", "宽敞": "与「陌生」没有反义关系，「宽敞」说空间大。", "善良": "与「陌生」没有反义关系，「善良」说人的品性。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "熟悉", "is_correct": true, "explanation": "「熟悉」与「陌生」构成反义关系，指对事物很了解。"}, {"text": "丰富", "is_correct": false, "explanation": "与「陌生」没有反义关系，「丰富」说种类或数量多。"}, {"text": "干脆", "is_correct": false, "explanation": "与「陌生」没有反义关系，「干脆」说做事爽快利落。"}, {"text": "大方", "is_correct": false, "explanation": "与「陌生」没有反义关系，「大方」说态度自然、不拘束。"}], "correct_answer": "熟悉", "explanations": {"熟悉": "「熟悉」与「陌生」构成反义关系，指对事物很了解。", "丰富": "与「陌生」没有反义关系，「丰富」说种类或数量多。", "干脆": "与「陌生」没有反义关系，「干脆」说做事爽快利落。", "大方": "与「陌生」没有反义关系，「大方」说态度自然、不拘束。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生疏，不熟悉；没有见过或不了解。", "primary_collocate": null, "pronunciation": "mò shēng", "ipa": "mwɔ˥˩ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "我离开家乡十年，那里变得很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久没开车，开车的感觉有点陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对电脑很陌生，不会上网。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词对学生来说很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年没见，他的声音变得陌生了。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新菜我很陌生，没吃过。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说的这个办法，大家都觉得陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回到旧房子，一切都让我觉得陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对城里的生活还很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对老年人来说，手机软件很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陌生人", "label": "复合"}, {"form": "陌生感", "label": "复合"}], "register": "中性", "sense_fingerprint": "生疏、不熟悉、不了解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5f01a3f-0c54-4133-9b25-173d415a41c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陌生", "is_correct": true, "explanation": "「陌生」表示离开多年后对那里不熟悉，与句中「离开家乡十年」相符。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：「幼稚」说人的心智不成熟，不能用来形容「那里」。"}, {"text": "调皮", "is_correct": false, "explanation": "语义：「调皮」形容人或孩子的性情，不用于地方。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：「狡猾」说人的心机，地方变得狡猾不成立。"}], "explanations": {"陌生": "「陌生」表示离开多年后对那里不熟悉，与句中「离开家乡十年」相符。", "幼稚": "语义：「幼稚」说人的心智不成熟，不能用来形容「那里」。", "调皮": "语义：「调皮」形容人或孩子的性情，不用于地方。", "狡猾": "语义：「狡猾」说人的心机，地方变得狡猾不成立。"}, "sentence_index": 0, "correct_answer": "陌生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这门技术很陌生，已经用了十年。", "explanation": "这里应该用〈熟练〉。「陌生」只说不认识，与「用了十年」矛盾；技术运用得好要用〈熟练〉。"}, {"text": "我们俩一起长大，每天都在一起玩，我对他的一切都很陌生。", "explanation": "这里应该用〈熟悉〉。「陌生」指不熟悉，与「一起长大、每天都在一起玩」矛盾；彼此很了解要用〈熟悉〉。"}, {"text": "这位教授对古代文学很陌生，他研究了三十年，已经发表了很多论文。", "explanation": "这里应该用〈精通〉。「陌生」指不熟悉，与「研究了三十年」矛盾；对学问深入掌握要用〈精通〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陌生", "is_correct": true, "explanation": "「陌生」表示对这个办法没听说过或不了解，与句中「大家都觉得」相符。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：「冷清」说地方或场面没有人气，不能用来形容办法。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：「热闹」说场面有人气，不能用来形容办法。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：「响亮」多形容声音，不能用「觉得」修饰办法。"}], "explanations": {"陌生": "「陌生」表示对这个办法没听说过或不了解，与句中「大家都觉得」相符。", "冷清": "语义：「冷清」说地方或场面没有人气，不能用来形容办法。", "热闹": "语义：「热闹」说场面有人气，不能用来形容办法。", "响亮": "搭配：「响亮」多形容声音，不能用「觉得」修饰办法。"}, "sentence_index": 6, "correct_answer": "陌生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们对这条街很陌生，几乎每天都在这里散步。", "explanation": "这里应该用〈熟悉〉。「陌生」指不了解，与「每天都在这里散步」矛盾；对地方很了解要用〈熟悉〉。"}, {"text": "我对自己家很陌生，闭着眼睛也能找到厨房。", "explanation": "这里应该用〈熟悉〉。「陌生」指不熟悉，与「闭着眼睛也能找到厨房」矛盾；对环境很了解要用〈熟悉〉。"}, {"text": "我们两人配合得很陌生，一个眼神就明白了对方。", "explanation": "这里应该用〈默契〉。「陌生」只说不认识，与「一个眼神就明白」矛盾；配合心意相通要用〈默契〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这条路很陌生。", "corrected_sentence": "他对这条路很陌生。", "error_description": "错误：「陌生」表示对某事物不熟悉，要用介词「对」引出对象，不能用「把」。正确：「他对这条路很陌生」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些方法老年人来说很陌生。", "corrected_sentence": "这些方法对老年人来说很陌生。", "error_description": "错误：「老年人来说」前面漏掉了介词「对」。「对……来说」引出说话的角度，不能省略「对」。正确：「这些方法对老年人来说很陌生」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "岛屿是海里四面都是水的小块陆地。", "primary_collocate": null, "pronunciation": "dǎo yǔ", "ipa": "tau˨˩˦ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "飞机飞过海面，下面有一座岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "furigana": "fēi jī fēi guò hǎi miàn, xià miàn yǒu yí zuò dǎo yǔ.", "sentence_source": "generated"}, {"text": "这片海里有很多岛屿，要坐船才能去。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岛屿四面都是水，没有桥，只能坐船。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边看到远处有个绿色的岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家由几千个岛屿组成。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我想去热带的岛屿玩儿。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来了，岛屿上的人都回家了。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的蓝色是海，绿色小点是岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个岛屿很小，只住着十几个人。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船到了那座岛屿，沙滩上有很多贝壳。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "岛屿·海里四面都是水的小块陆地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f149c945-cf41-413d-b166-ecfc5601d7e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "岛屿", "is_correct": true, "explanation": "“岛屿”是海里四面环水的小块陆地，与“飞过海面”的语境相合。"}, {"text": "海", "is_correct": false, "explanation": "搭配：“一座”不能修饰“海”，海要说“一片海”。"}, {"text": "海浪", "is_correct": false, "explanation": "量词：“座”不能修饰“海浪”，海浪应说“一排海浪”。"}, {"text": "云", "is_correct": false, "explanation": "量词：“座”不能修饰“云”，云要说“一朵云”。"}], "explanations": {"岛屿": "“岛屿”是海里四面环水的小块陆地，与“飞过海面”的语境相合。", "海": "搭配：“一座”不能修饰“海”，海要说“一片海”。", "海浪": "量词：“座”不能修饰“海浪”，海浪应说“一排海浪”。", "云": "量词：“座”不能修饰“云”，云要说“一朵云”。"}, "sentence_index": 0, "correct_answer": "岛屿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们从岛屿的一头步行，就能走到陆地。", "explanation": "这里应该用〈半岛〉。岛屿四面环水，与陆地不相连，不能步行走到陆地；〈半岛〉一端连着陆地。"}, {"text": "他们坐船去了一条绿色的岛屿。", "explanation": "量词用错。〈条〉用于细长的东西，岛屿应用〈座〉。"}, {"text": "远处的海面上浮着一只绿色的岛屿。", "explanation": "量词用错。〈只〉用于动物或单个的小物件，岛屿应用〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "岛屿", "is_correct": true, "explanation": "“岛屿”是海中四面环水的陆地，与“台风来了”、人要回家的语境相合。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“城市上”不说，应说“城市里”。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“学校上”不说，应说“学校里”。"}, {"text": "森林", "is_correct": false, "explanation": "搭配：“森林上”不说，应说“森林里”。"}], "explanations": {"岛屿": "“岛屿”是海中四面环水的陆地，与“台风来了”、人要回家的语境相合。", "城市": "搭配：“城市上”不说，应说“城市里”。", "学校": "搭配：“学校上”不说，应说“学校里”。", "森林": "搭配：“森林上”不说，应说“森林里”。"}, "sentence_index": 6, "correct_answer": "岛屿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐船到了一棵岛屿，沙滩上有很多贝壳。", "explanation": "量词用错。〈棵〉用于树，岛屿应用〈座〉。"}, {"text": "台风过后，海面上多了一本岛屿。", "explanation": "量词用错。〈本〉用于书，岛屿应用〈座〉。"}, {"text": "沙滩上有很多贝壳，我们坐船到了一辆岛屿。", "explanation": "量词用错。〈辆〉用于车，岛屿应用〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐船去了一本岛屿。", "corrected_sentence": "我们坐船去了一座岛屿。", "error_description": "量词错误：“岛屿”应搭配量词“座”，“本”用于书籍。应说“一座岛屿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些岛屿们都很美。", "corrected_sentence": "这些岛屿都很美。", "error_description": "错误在“岛屿”后面多加了“们”。“们”只用于人或拟人的名词，岛屿是无生命的事物，不能加“们”。应说“这些岛屿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
