INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海洋、湖泊或河流中四面环水的小块陆地。", "primary_collocate": null, "pronunciation": "dǎo yǔ", "ipa": "tau˨˩˦ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "湖中间有一个岛屿，鸟都住在那里。", "target_word": "岛屿", "complexity_tier": "T3", "furigana": "hú zhōng jiān yǒu yí gè dǎo yǔ, niǎo dōu zhù zài nà lǐ.", "sentence_source": "generated"}, {"text": "长江里有一个岛屿，船从两边过去。", "target_word": "岛屿", "complexity_tier": "T3", "furigana": "Cháng jiāng lǐ yǒu yí gè dǎo yǔ, chuán cóng liǎng biān guò qù.", "sentence_source": "generated"}, {"text": "海洋中有很多岛屿，有的大，有的小。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水围住了这块地，它成了岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里的岛屿四面环水，只能坐船去。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在山上，能看到湖里的几个岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "furigana": "zhàn zài shān shàng, néng kàn dào hú lǐ de jǐ gè dǎo yǔ.", "sentence_source": "generated"}, {"text": "这个岛屿在河中间，上面有很多树。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地理课上，老师讲了海洋和湖泊里的岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖中的岛屿春天特别漂亮，花开了。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水涨了，河中的岛屿变小了。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "岛屿·海洋湖泊河流中四面环水的小块陆地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f149c945-cf41-413d-b166-ecfc5601d7e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "岛屿", "is_correct": true, "explanation": "“岛屿”指湖中四面环水的小块陆地，与“湖中间”和“鸟住在那里”相合。"}, {"text": "海", "is_correct": false, "explanation": "语义：湖中间不可能是海，句子说的是湖里的陆地。"}, {"text": "岸", "is_correct": false, "explanation": "语义：“岸”在湖边，不在湖中间，与“湖中间有一个”的位置不符。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：“湖中间”已指明在湖内，再说“湖中间有一个湖泊”语义重复，不自然。"}], "explanations": {"岛屿": "“岛屿”指湖中四面环水的小块陆地，与“湖中间”和“鸟住在那里”相合。", "海": "语义：湖中间不可能是海，句子说的是湖里的陆地。", "岸": "语义：“岸”在湖边，不在湖中间，与“湖中间有一个”的位置不符。", "湖泊": "语义：“湖中间”已指明在湖内，再说“湖中间有一个湖泊”语义重复，不自然。"}, "sentence_index": 0, "correct_answer": "岛屿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖中间有一张岛屿，上面住着很多鸟。", "explanation": "量词用错。〈张〉用于纸、桌子等平面的东西，岛屿应用〈座〉。"}, {"text": "湖边的渔民每天划船去一条岛屿打鱼。", "explanation": "量词用错。〈条〉用于细长的东西，岛屿应用〈座〉。"}, {"text": "他站在湖边，看见一只岛屿，上面长着很多树。", "explanation": "量词用错。〈只〉用于动物或单个的小物件，岛屿应用〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "岛屿", "is_correct": true, "explanation": "“岛屿”是河中四面环水的小块陆地，与“在河中间”和“上面有很多树”相合。"}, {"text": "河岸", "is_correct": false, "explanation": "搭配：“河岸”不说“在河中间”，只能说在河边。"}, {"text": "码头", "is_correct": false, "explanation": "语义：码头在岸边，不在河中间，与句中的位置不符。"}, {"text": "船", "is_correct": false, "explanation": "语义：船上不会长很多树，与“上面有很多树”的描述冲突。"}], "explanations": {"岛屿": "“岛屿”是河中四面环水的小块陆地，与“在河中间”和“上面有很多树”相合。", "河岸": "搭配：“河岸”不说“在河中间”，只能说在河边。", "码头": "语义：码头在岸边，不在河中间，与句中的位置不符。", "船": "语义：船上不会长很多树，与“上面有很多树”的描述冲突。"}, "sentence_index": 6, "correct_answer": "岛屿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河中间有一棵岛屿，上面长满了草。", "explanation": "量词用错。〈棵〉用于树，岛屿应用〈座〉。"}, {"text": "河里有一本岛屿，岛上有很多鸟。", "explanation": "量词用错。〈本〉用于书，岛屿应用〈座〉。"}, {"text": "河水涨了，河中一辆岛屿变小了。", "explanation": "量词用错。〈辆〉用于车，岛屿应用〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "游客坐船来到湖中的一条岛屿，这里很安静。", "corrected_sentence": "游客坐船来到湖中的一座岛屿，这里很安静。", "error_description": "量词错误：“岛屿”应搭配量词“座”，“条”用于细长的东西。应说“一座岛屿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坐船到了河中的岛屿的，岛上有很多鸟。", "corrected_sentence": "我们坐船到了河中的岛屿，岛上有很多鸟。", "error_description": "错误在“岛屿”后多加了“的”。“岛屿”是中心语，后面不能再接“的”；“的”只接在“河中”后面，应说“河中的岛屿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92626, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92626, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92626, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "长时间地谈话。", "primary_collocate": null, "pronunciation": "cháng tán", "ipa": "ʈʂʰɑŋ³⁵ tʰan³⁵", "syllable_count": 2, "sentences": [{"text": "昨晚我们长谈了很久。", "target_word": "长谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和老师长谈了一个下午。", "target_word": "长谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友来了，我们长谈到半夜。", "target_word": "长谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和你长谈一次。", "target_word": "长谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐在院子里长谈。", "target_word": "长谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和我长谈过一次。", "target_word": "长谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位老朋友见面后长谈起来。", "target_word": "长谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在咖啡馆长谈了两个小时。", "target_word": "长谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和妈妈长谈了一晚上。", "target_word": "长谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们常常在电话里长谈。", "target_word": "长谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "长谈了", "label": "体标"}, {"form": "长谈过", "label": "体标"}], "register": "中性", "sense_fingerprint": "长谈：长时间地谈话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长谈", "is_correct": true, "explanation": "长谈：正确。“很久”说明时间长，与“长谈”（长时间地谈话）相符。"}, {"text": "瞥", "is_correct": false, "explanation": "语义：“瞥”指匆匆看一眼，是一瞬间的动作，不能持续“很久”。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”需要受事（扔东西），“我们扔了很久”缺少宾语，不成立。"}, {"text": "眨", "is_correct": false, "explanation": "搭配：“眨”一般带“眼”，且是瞬间动作，不能与“很久”组成一段时间的谈话。"}], "explanations": {"长谈": "长谈：正确。“很久”说明时间长，与“长谈”（长时间地谈话）相符。", "瞥": "语义：“瞥”指匆匆看一眼，是一瞬间的动作，不能持续“很久”。", "扔": "配价：“扔”需要受事（扔东西），“我们扔了很久”缺少宾语，不成立。", "眨": "搭配：“眨”一般带“眼”，且是瞬间动作，不能与“很久”组成一段时间的谈话。"}, "sentence_index": 0, "correct_answer": "长谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "见面后我们长谈了几句。", "explanation": "这里应该用〈寒暄〉。寒暄指简短的问候，几句话即可；长谈强调谈话时间长，不能用于“几句”这样的短时间。"}, {"text": "等车时我们长谈了一会儿。", "explanation": "这里应该用〈闲谈〉。闲谈指随便聊天，不强调时间长；长谈强调时间长，“一会儿”太短，不能搭配。"}, {"text": "老师一个人在台上长谈了一小时。", "explanation": "这里应该用〈讲〉。长谈指两人或多人之间的长时间交谈，老师一个人在台上讲话不叫长谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长谈", "is_correct": true, "explanation": "长谈起来：正确。“见面后……起来”表示开始某个动作，“长谈起来”即开始长时间交谈，与语境相符。"}, {"text": "扑", "is_correct": false, "explanation": "语义：“扑”是猛地向前冲的瞬间动作，“见面后扑起来”不通，与老朋友交谈的场景不符。"}, {"text": "撕", "is_correct": false, "explanation": "配价：“撕”需要受事（撕东西），“撕起来”缺少宾语，不能用于此句。"}, {"text": "鞠躬", "is_correct": false, "explanation": "搭配：“鞠躬”是一次性的礼节动作，不能说“鞠躬起来”表示开始。"}], "explanations": {"长谈": "长谈起来：正确。“见面后……起来”表示开始某个动作，“长谈起来”即开始长时间交谈，与语境相符。", "扑": "语义：“扑”是猛地向前冲的瞬间动作，“见面后扑起来”不通，与老朋友交谈的场景不符。", "撕": "配价：“撕”需要受事（撕东西），“撕起来”缺少宾语，不能用于此句。", "鞠躬": "搭配：“鞠躬”是一次性的礼节动作，不能说“鞠躬起来”表示开始。"}, "sentence_index": 6, "correct_answer": "长谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我长谈了一封信。", "explanation": "这里应该用〈写〉。长谈指口头的长时间交谈，不能用于书面的信件。"}, {"text": "他对着空房间长谈了一个小时。", "explanation": "这里应该用〈自言自语〉。长谈指双方或多方的交谈，对着空房间独自说话不叫长谈。"}, {"text": "她长谈了一下午桌子。", "explanation": "这里应该用〈擦〉。长谈不能带“桌子”这类物品作宾语，它指长时间的口头交谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩在公园很长谈了一个上午。", "corrected_sentence": "我们俩在公园长谈了一个上午。", "error_description": "错误：在动词“长谈”前加了程度副词“很”，“很长谈”不成立。“很”一般修饰形容词，不修饰“长谈”这类动作动词；正确说法是“长谈了一个上午”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他俩在湖边长谈得一下午。", "corrected_sentence": "他俩在湖边长谈了一下午。", "error_description": "错误：“长谈”后应接动态助词“了”，表示持续的动作已经发生。“得”是结构助词，用于带补语的结构，不能直接接“一下午”。正确说法是“长谈了一下午”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
