INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92631, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关系式是写出几个数怎么连在一起的式子。", "primary_collocate": null, "pronunciation": "guān xì shì", "ipa": "kwan˥ ɕi˥˩ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "老师在黑板上写了一个关系式。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这两个数的关系式写出来。", "target_word": "关系式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个关系式很简单，我看懂了。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先找出数和数的关系，再写关系式。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想了很久，才写对这个关系式。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用关系式算出每天要走多远。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关系式里有三个数。", "target_word": "关系式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这道题要先列出关系式。", "target_word": "关系式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "作业本上的关系式，他都抄错了。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能说说这个关系式是什么意思吗？", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "函数关系式", "label": "复合"}], "register": "书面", "sense_fingerprint": "写出几个数之间怎样连接的式子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62eac6f8-55d8-4516-a7c5-4d8181c28db1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92631, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关系式", "is_correct": true, "explanation": "「关系式」是写出几个数怎样连接的式子，老师在黑板上写的正是它。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“写”不能与“天气”搭配，“写了一个天气”说不通。"}, {"text": "草莓", "is_correct": false, "explanation": "语义：“草莓”是水果，不能写在黑板上当作式子，句子说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是电器，与黑板上写的内容无关，句子说不通。"}], "explanations": {"关系式": "「关系式」是写出几个数怎样连接的式子，老师在黑板上写的正是它。", "天气": "搭配：“写”不能与“天气”搭配，“写了一个天气”说不通。", "草莓": "语义：“草莓”是水果，不能写在黑板上当作式子，句子说不通。", "冰箱": "语义：“冰箱”是电器，与黑板上写的内容无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "关系式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在纸上画了一个关系式。", "explanation": "这里应该用〈图形〉。“画”的对象是图形，关系式是写出来的数学式子，不能用“画”。"}, {"text": "他把关系式穿在身上。", "explanation": "这里应该用〈衣服〉。“穿”的对象是衣服，关系式是数学表达式，不能穿。"}, {"text": "写完作文后，他喝了这个关系式。", "explanation": "这里应该用〈汤〉。“喝”的对象是汤、水等液体，关系式是数学表达式，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92631, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关系式", "is_correct": true, "explanation": "「关系式」是式子，里面可以写出几个数之间的关系，与“有三个数”相合。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：“地毯”是铺在地上的织物，不能装“数”，句子说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，与“数”无关，句子说不通。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：“夏天里”不能作为放置“数”的处所，搭配不通。"}], "explanations": {"关系式": "「关系式」是式子，里面可以写出几个数之间的关系，与“有三个数”相合。", "地毯": "语义：“地毯”是铺在地上的织物，不能装“数”，句子说不通。", "窗户": "语义：“窗户”是建筑部件，与“数”无关，句子说不通。", "夏天": "搭配：“夏天里”不能作为放置“数”的处所，搭配不通。"}, "sentence_index": 6, "correct_answer": "关系式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我买了一袋关系式，很甜。", "explanation": "这里应该用〈糖果〉。“一袋……很甜”说的是能吃的糖果，关系式是数学式子，不能吃，也不甜。"}, {"text": "你能唱一唱这首歌的关系式吗？", "explanation": "这里应该用〈歌词〉。“唱”的对象是歌词或歌曲，关系式是数学式子，不能唱。"}, {"text": "你能说说这道菜的关系式吗？", "explanation": "这里应该用〈做法〉。“说说”的是菜的做法，关系式是数学表达式，与菜无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题要先写出一只关系式。", "corrected_sentence": "这道题要先写出一个关系式。", "error_description": "「关系式」是数学式子，量词应用“个”。“只”用于动物等，不能用来数式子，应改为“一个关系式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很快就把这棵关系式写对了。", "corrected_sentence": "他很快就把这个关系式写对了。", "error_description": "「关系式」不是植物，量词“棵”用于树木等植物，不能用来数式子，应改为“这个关系式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
