INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92632, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示几个量之间关系的数学表达式。", "primary_collocate": null, "pronunciation": "guān xì shì", "ipa": "kwan˥ ɕi˥˩ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "路程、速度和时间有一个关系式。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个关系式表示价钱和数量的关系。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们用关系式表示面积和边长。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "物理书里有很多关系式。", "target_word": "关系式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "根据这个关系式，我们可以算出温度。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "圆的面积和半径可以用关系式写出来。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把长、宽和面积的关系式记在本子上。", "target_word": "关系式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个关系式说明，速度越快，时间越短。", "target_word": "关系式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，我要记住这几个关系式。", "target_word": "关系式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你用一个关系式表示水和时间的关系。", "target_word": "关系式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "函数关系式", "label": "复合"}], "register": "书面", "sense_fingerprint": "表示几个量之间关系的数学表达式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62eac6f8-55d8-4516-a7c5-4d8181c28db1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关系式", "is_correct": true, "explanation": "「关系式」表示几个量之间的关系，与“路程、速度和时间”相符，句子通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与路程、速度、时间无关，句子说不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“路程、速度和时间”不带“味道”，“有一个味道”搭配不当。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”与这三个量毫无关系，句子不通。"}], "explanations": {"关系式": "「关系式」表示几个量之间的关系，与“路程、速度和时间”相符，句子通顺。", "颜色": "语义：“颜色”与路程、速度、时间无关，句子说不通。", "味道": "搭配：“路程、速度和时间”不带“味道”，“有一个味道”搭配不当。", "窗户": "语义：“窗户”与这三个量毫无关系，句子不通。"}, "sentence_index": 0, "correct_answer": "关系式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快就把这个关系式吃完了。", "explanation": "这里应该用〈食物〉。“吃”的对象是食物，关系式是数学表达式，不能吃。"}, {"text": "妈妈在厨房里切了关系式。", "explanation": "这里应该用〈蔬菜〉。“切”的对象是蔬菜、肉等食材，关系式是数学表达式，不能切。"}, {"text": "他背出了一首古诗的关系式。", "explanation": "这里应该用〈诗句〉。关系式是数学表达式，与古诗无关，“一首古诗的关系式”的说法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关系式", "is_correct": true, "explanation": "「关系式」是表示几个量之间关系的数学式子，可以记在本子上，句子通顺。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是数量之间的关系，把“长、宽和面积的歌曲”记下来说不通。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：“云朵”与“长、宽和面积”无关，句子说不通。"}, {"text": "花瓣", "is_correct": false, "explanation": "搭配：“记”后接“花瓣”不成词组，“长、宽和面积的花瓣”也不能记录。"}], "explanations": {"关系式": "「关系式」是表示几个量之间关系的数学式子，可以记在本子上，句子通顺。", "歌曲": "语义：“歌曲”不是数量之间的关系，把“长、宽和面积的歌曲”记下来说不通。", "云朵": "语义：“云朵”与“长、宽和面积”无关，句子说不通。", "花瓣": "搭配：“记”后接“花瓣”不成词组，“长、宽和面积的花瓣”也不能记录。"}, "sentence_index": 6, "correct_answer": "关系式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你把水和时间的关系式染成红色。", "explanation": "这里应该用〈布料〉。“染”的对象是布料、头发等，关系式是数学表达式，不能染。"}, {"text": "请你演奏这个关系式。", "explanation": "这里应该用〈乐曲〉。“演奏”的对象是乐曲，关系式是数学表达式，不能演奏。"}, {"text": "请你唱一首儿歌里的关系式。", "explanation": "这里应该用〈歌词〉。“唱”的对象是儿歌或歌词，关系式是数学式子，不能唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那幅关系式抄在了作业本上。", "corrected_sentence": "他把那个关系式抄在了作业本上。", "error_description": "「关系式」是数学式子，“幅”用于字画、照片，不能用来数它，应改为“那个关系式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在黑板上写了一件关系式。", "corrected_sentence": "老师在黑板上写了一个关系式。", "error_description": "「关系式」是数学式子，量词应该用“个”。“件”用于衣服、事情等，不能用来数关系式，应改为“一个关系式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
