INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用虚假的言语或行为使人上当。", "primary_collocate": null, "pronunciation": "piàn rén", "ipa": "pʰjɛn˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "有人打电话骗人，说你的银行卡出了问题。", "target_word": "骗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用假名字骗人，拿走了大家的钱。", "target_word": "骗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店卖假货骗人，很多人上了当。", "target_word": "骗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有些人专门骗人，要小心。", "target_word": "骗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子专门骗人，老人特别要小心。", "target_word": "骗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他装成警察骗人，让大家把钱给他。", "target_word": "骗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种网站是骗人的，不要给他们钱。", "target_word": "骗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠骗人赚钱，后来警察抓住了他。", "target_word": "骗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用好听的话骗人，让我买了很贵的东西。", "target_word": "骗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪有免费送钱的事？这是骗人的。", "target_word": "骗人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骗了人", "label": "体标"}, {"form": "骗过人", "label": "体标"}], "register": "口语", "sense_fingerprint": "用假话或假行为让人上当受损", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5f01a3f-0c54-4133-9b25-173d415a41c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骗人", "is_correct": true, "explanation": "「骗人」表示用假话使人上当，与句中「银行卡出了问题」的内容相符。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：「祝贺」表示喜事的庆贺，与后句「银行卡出了问题」不符。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：「拜访」指登门看望，不能用打电话的方式，与句中「打电话」矛盾。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：「表扬」表示肯定和赞许，与后句「银行卡出了问题」不符。"}], "explanations": {"骗人": "「骗人」表示用假话使人上当，与句中「银行卡出了问题」的内容相符。", "祝贺": "语义：「祝贺」表示喜事的庆贺，与后句「银行卡出了问题」不符。", "拜访": "语义：「拜访」指登门看望，不能用打电话的方式，与句中「打电话」矛盾。", "表扬": "语义：「表扬」表示肯定和赞许，与后句「银行卡出了问题」不符。"}, "sentence_index": 0, "correct_answer": "骗人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "网上有些人专门骗人，大家都很感激。", "explanation": "这里应该用〈帮人〉。「骗人」指用假话使人上当，与「大家都很感激」矛盾；给人提供帮助要说〈帮人〉。"}, {"text": "这家店的服务很骗人，顾客都很满意。", "explanation": "这里应该用〈热情〉。「骗人」指欺骗，与「顾客都很满意」矛盾；待人周到、主动要用〈热情〉。"}, {"text": "他对家人很骗人，每天都照顾得很周到。", "explanation": "这里应该用〈体贴〉。「骗人」指欺骗，与「照顾得很周到」矛盾；关心别人、为人着想要用〈体贴〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骗人", "is_correct": true, "explanation": "「骗人」表示用假话欺骗别人，与句中「不要给他们钱」的提醒相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「睡觉」是休息的动作，不能用来说网站「是睡觉的」，与句意不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：「吃饭」是日常动作，不能用来说明网站的性质，与句意不通。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：「跑步」是身体活动，不能用来说明网站的性质，与句意不通。"}], "explanations": {"骗人": "「骗人」表示用假话欺骗别人，与句中「不要给他们钱」的提醒相符。", "睡觉": "语义：「睡觉」是休息的动作，不能用来说网站「是睡觉的」，与句意不通。", "吃饭": "语义：「吃饭」是日常动作，不能用来说明网站的性质，与句意不通。", "跑步": "语义：「跑步」是身体活动，不能用来说明网站的性质，与句意不通。"}, "sentence_index": 6, "correct_answer": "骗人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话很骗人，句句都是真心话。", "explanation": "这里应该用〈真诚〉。「骗人」指说假话欺骗别人，与「句句都是真心话」矛盾；说话出于真心要用〈真诚〉。"}, {"text": "这家店的价格很骗人，每样东西都很合理。", "explanation": "这里应该用〈公道〉。「骗人」指欺骗，与「每样东西都很合理」矛盾；价格合理、不欺诈要用〈公道〉。"}, {"text": "他的话很骗人，大家都觉得很踏实。", "explanation": "这里应该用〈实在〉。「骗人」指说假话，与「大家都觉得很踏实」矛盾；说话可靠、不虚假要用〈实在〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个骗子专门很骗人，我们要小心。", "corrected_sentence": "这个骗子专门骗人，我们要小心。", "error_description": "错误：「很」是程度副词，不能直接修饰动作性的「骗人」，「专门很骗人」不通；去掉「很」即正确：「这个骗子专门骗人，我们要小心」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人以前骗人过，大家都不信他。", "corrected_sentence": "那个人以前骗过人，大家都不信他。", "error_description": "错误：体标「过」应紧跟动词「骗」，要说「骗过人」，不能说「骗人过」。正确：「那个人以前骗过人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92635, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注意", "is_correct": true, "explanation": "正确：“注意”与“忽视”的“没注意到”相对，是反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”指把东西归类摆好，与“忽视”的任何义项都不构成反义。"}, {"text": "推迟", "is_correct": false, "explanation": "无关：“推迟”指把时间往后延，与“忽视”不构成反义。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”指交流看法，与“忽视”不构成反义。"}], "correct_answer": "注意", "explanations": {"注意": "正确：“注意”与“忽视”的“没注意到”相对，是反义关系。", "整理": "无关：“整理”指把东西归类摆好，与“忽视”的任何义项都不构成反义。", "推迟": "无关：“推迟”指把时间往后延，与“忽视”不构成反义。", "讨论": "无关：“讨论”指交流看法，与“忽视”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92635, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注意", "is_correct": true, "explanation": "正确：“注意”与“忽视”的“没注意到”相对，是反义关系。"}, {"text": "放松", "is_correct": false, "explanation": "无关：“放松”指使紧张的状态缓和，与“忽视”不构成反义。"}, {"text": "选择", "is_correct": false, "explanation": "无关：“选择”指从几样中挑出一样，与“忽视”不构成反义。"}, {"text": "翻译", "is_correct": false, "explanation": "无关：“翻译”指转换语言，与“忽视”不构成反义。"}], "correct_answer": "注意", "explanations": {"注意": "正确：“注意”与“忽视”的“没注意到”相对，是反义关系。", "放松": "无关：“放松”指使紧张的状态缓和，与“忽视”不构成反义。", "选择": "无关：“选择”指从几样中挑出一样，与“忽视”不构成反义。", "翻译": "无关：“翻译”指转换语言，与“忽视”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92635, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "忽视是没有看到、没注意到某事。", "primary_collocate": null, "pronunciation": "hū shì", "ipa": "xu˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他太忙了，忽视了身体发出的信号。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时不能忽视路边的小孩。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忽视了一个小问题，所以做错了。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只看大字，忽视了下面的小字。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，司机忽视了路上的红灯。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在聊天，忽视了门口的敲门声。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太多人只看上面，忽视了脚下的路。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他玩游戏太投入，忽视了窗外下起的大雨。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们容易忽视身边很小的变化。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看地图时，我忽视了旁边的小路。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忽视了", "label": "体标"}, {"form": "忽视过", "label": "体标"}], "register": "中性", "sense_fingerprint": "没注意到，漏看了某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd4150c-a1b6-4a5e-a02d-612dc66104b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92635, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "察觉", "is_correct": false, "explanation": "语义：“察觉”是注意到、感觉到，与“太忙”造成的遗漏相反，句子说不通。"}, {"text": "忽视", "is_correct": true, "explanation": "正确：“忽视”表示没注意到、没放在心上，与“太忙”构成因果，句意通顺。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”只接器物、设备，不能说修理身体发出的信号。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场地等，不能用于身体发出的信号。"}], "explanations": {"察觉": "语义：“察觉”是注意到、感觉到，与“太忙”造成的遗漏相反，句子说不通。", "忽视": "正确：“忽视”表示没注意到、没放在心上，与“太忙”构成因果，句意通顺。", "修理": "搭配：“修理”只接器物、设备，不能说修理身体发出的信号。", "打扫": "搭配：“打扫”的对象是房间、场地等，不能用于身体发出的信号。"}, "sentence_index": 0, "correct_answer": "忽视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一进门就看到了桌上的花瓶，却忽视了它，立刻伸手把它扶住。", "explanation": "这里应该用〈看到〉。“忽视”表示没有看到，而句中说“一进门就看到了”，前后矛盾。"}, {"text": "老师叫了我的名字，我却忽视了他，马上站起来回答问题。", "explanation": "这里应该用〈听见〉。“忽视”表示没有注意到，而句中写我马上站起来回答，说明已经听到了，前后矛盾。"}, {"text": "我每天上班都会经过那棵老树，忽视了它，每次都停下来拍照。", "explanation": "这里应该用〈留意〉。“忽视”表示没有看到，而句中说每次都停下来拍照，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92635, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "察看", "is_correct": false, "explanation": "语义：“察看”是仔细查看，与“只看上面”的前提相矛盾，句子不通。"}, {"text": "忽视", "is_correct": true, "explanation": "正确：“忽视”指没有留意脚下的路，与“只看上面”前后呼应。"}, {"text": "钻研", "is_correct": false, "explanation": "搭配：“钻研”接问题、学问，不能说钻研脚下的路。"}, {"text": "理睬", "is_correct": false, "explanation": "搭配：“理睬”的对象是人，不能用于道路。"}], "explanations": {"察看": "语义：“察看”是仔细查看，与“只看上面”的前提相矛盾，句子不通。", "忽视": "正确：“忽视”指没有留意脚下的路，与“只看上面”前后呼应。", "钻研": "搭配：“钻研”接问题、学问，不能说钻研脚下的路。", "理睬": "搭配：“理睬”的对象是人，不能用于道路。"}, "sentence_index": 6, "correct_answer": "忽视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生忽视了病人的伤口，却仔细地包扎了起来。", "explanation": "这里应该用〈重视〉。“忽视”是没注意到，与后面“仔细地包扎”正好相反，前后矛盾。"}, {"text": "他忽视了那张照片，每天都要把它拿出来仔细看。", "explanation": "这里应该用〈关注〉。“忽视”是没注意到，与“每天拿出来仔细看”相反。"}, {"text": "我忽视了这条新闻，立刻告诉了所有朋友。", "explanation": "这里应该用〈留意〉。“忽视”是没注意到，与“立刻告诉所有朋友”相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机忽视到了路口的指示牌，开错了方向。", "corrected_sentence": "司机忽视了路口的指示牌，开错了方向。", "error_description": "“忽视”后不能接结果补语“到”（“到”属于“注意到”的用法）。正确说法是“忽视了”，表示没有注意、没有重视，错误在于“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这件事忽视，后来很后悔。", "corrected_sentence": "他把这件事忽视了，后来很后悔。", "error_description": "“把”字句中，动词“忽视”后面要带“了”等成分，不能只说“把这件事忽视”。正确说法是“他把这件事忽视了”，错误在于漏掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92636, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重视", "is_correct": true, "explanation": "正确：“重视”与“忽视”相对，指认为重要、放在心上，是反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指把物品从一处运到另一处，与“忽视”不构成反义。"}, {"text": "装饰", "is_correct": false, "explanation": "无关：“装饰”指使美观的修饰，与“忽视”不构成反义。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”指交流看法，与“忽视”不构成反义。"}], "correct_answer": "重视", "explanations": {"重视": "正确：“重视”与“忽视”相对，指认为重要、放在心上，是反义关系。", "搬运": "无关：“搬运”指把物品从一处运到另一处，与“忽视”不构成反义。", "装饰": "无关：“装饰”指使美观的修饰，与“忽视”不构成反义。", "讨论": "无关：“讨论”指交流看法，与“忽视”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
