INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92636, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不重视；不放在心上。", "primary_collocate": null, "pronunciation": "hū shì", "ipa": "xu˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "学生不能忽视身体健康。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不应该忽视客人的意见。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母常常忽视孩子的心情。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人忽视睡觉的重要性。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要忽视小事，小事也会变成大问题。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直忽视朋友的帮助，后来很后悔。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作再忙，也不能忽视安全。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太忙，总是忽视家人。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学习方法千万不能忽视。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店只想赚钱，忽视了客人的感受。", "target_word": "忽视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忽视了", "label": "体标"}, {"form": "忽视过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不把某事当回事，不重视", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd4150c-a1b6-4a5e-a02d-612dc66104b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是风景、作品，不能说欣赏身体健康。"}, {"text": "忽视", "is_correct": true, "explanation": "正确：“忽视”表示不重视，与“不能”搭配，句意是提醒要重视健康。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”用于人或成就，不能接“身体健康”。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所、展览，不能用于身体健康。"}], "explanations": {"欣赏": "搭配：“欣赏”的对象是风景、作品，不能说欣赏身体健康。", "忽视": "正确：“忽视”表示不重视，与“不能”搭配，句意是提醒要重视健康。", "祝贺": "搭配：“祝贺”用于人或成就，不能接“身体健康”。", "参观": "搭配：“参观”的对象是场所、展览，不能用于身体健康。"}, "sentence_index": 0, "correct_answer": "忽视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我忽视了今晚的演出，提前三个小时就到了现场，认真准备。", "explanation": "这里应该用〈重视〉。“忽视”是不予重视，与“提前三个小时就到了现场，认真准备”的态度相反，前后矛盾。"}, {"text": "我忽视了身体，每天都按时做好三餐，从不落下。", "explanation": "这里应该用〈照顾〉。“忽视”是不予重视，与“每天都按时做好三餐，从不落下”的做法相反，前后矛盾。"}, {"text": "他忽视了老师的建议，每一条都认真记在本子上。", "explanation": "这里应该用〈重视〉。“忽视”是不予重视，与“每一条都认真记在本子上”的态度相反，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考验", "is_correct": false, "explanation": "搭配：“考验”的对象是人或能力，不能说考验安全。"}, {"text": "忽视", "is_correct": true, "explanation": "正确：“忽视”表示不重视，与“也不能”搭配，句意是提醒要重视安全。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”用于人或事物的到来，不能欢迎安全。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：“消灭”指彻底去掉，而安全是应当保持的，句子说不通。"}], "explanations": {"考验": "搭配：“考验”的对象是人或能力，不能说考验安全。", "忽视": "正确：“忽视”表示不重视，与“也不能”搭配，句意是提醒要重视安全。", "欢迎": "搭配：“欢迎”用于人或事物的到来，不能欢迎安全。", "消灭": "语义：“消灭”指彻底去掉，而安全是应当保持的，句子说不通。"}, "sentence_index": 6, "correct_answer": "忽视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忽视了这份合同，每一条都认真读了一遍。", "explanation": "这里应该用〈重视〉。“忽视”是不予重视，与“每一条都认真读了一遍”的态度相反，前后矛盾。"}, {"text": "这家店忽视了顾客的投诉，立刻道了歉并退了钱。", "explanation": "这里应该用〈回应〉。“忽视”是不予重视，与“立刻道歉并退款”的处理方式相反，前后矛盾。"}, {"text": "我忽视了孩子的进步，把他的每一次进步都写进了日记。", "explanation": "这里应该用〈记录〉。“忽视”是不予重视，与“把每次进步都写进日记”的做法相反，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她忽视了过孩子的感受，后来很后悔。", "corrected_sentence": "她忽视过孩子的感受，后来很后悔。", "error_description": "表示曾经有过这种经历时，“忽视”应带体标“过”，不能再加“了”。正确说法是“她忽视过孩子的感受”，错误在于“了过”连用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他忽视了着家人的感受，已经很多年了。", "corrected_sentence": "他忽视着家人的感受，已经很多年了。", "error_description": "表示持续的状态时，“忽视”应带体标“着”，不能再加“了”。正确说法是“他忽视着家人的感受”，错误在于“了着”连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92637, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开门", "is_correct": true, "explanation": "开门：把门打开，与“把门关上”构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”与“关门”没有反义关系，不在同一语义范围内。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”与“关门”没有反义关系，二者动作义不对立。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”与“关门”没有反义关系，不构成对立。"}], "correct_answer": "开门", "explanations": {"开门": "开门：把门打开，与“把门关上”构成反义。", "唱歌": "“唱歌”与“关门”没有反义关系，不在同一语义范围内。", "读书": "“读书”与“关门”没有反义关系，二者动作义不对立。", "散步": "“散步”与“关门”没有反义关系，不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
