INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92637, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "关门是把门关上。", "primary_collocate": null, "pronunciation": "guān mén", "ipa": "kwan˥ mən˧˥", "syllable_count": 2, "sentences": [{"text": "外面很冷，请你快点关门。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡着了，你关门时小声一点。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大了，我去关门。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出去的时候忘了关门。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要用力关门，宝宝在睡觉。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说：进屋以后要马上关门。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫要跑进来了，快关门！", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我走进房间，轻轻地关门，怕吵醒他。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一回到家就关门，然后开了灯。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请关门，空调的冷气会跑出去。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "关门了", "label": "体标"}, {"form": "關門", "label": "繁体"}], "register": "口语", "sense_fingerprint": "把门关上，动作义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df752ed1-047e-4fbd-b779-b0ded6150625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92637, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "关门", "is_correct": true, "explanation": "关门：把门关上，与听到的读音一致。"}, {"text": "官民", "is_correct": false, "explanation": "mín（第二声）与 mén（第二声）韵母不同，官民意思是官员和百姓。"}, {"text": "官名", "is_correct": false, "explanation": "míng 与 mén 韵母不同（-ing 与 -en），官名意思是官职的名称。"}, {"text": "官文", "is_correct": false, "explanation": "wén 与 mén 声母不同，官文意思是官方的文件。"}], "explanations": {"关门": "关门：把门关上，与听到的读音一致。", "官民": "mín（第二声）与 mén（第二声）韵母不同，官民意思是官员和百姓。", "官名": "míng 与 mén 韵母不同（-ing 与 -en），官名意思是官职的名称。", "官文": "wén 与 mén 声母不同，官文意思是官方的文件。"}, "sentence_index": null, "correct_answer": "关门"}, "level_3": {"options": [{"text": "关门", "is_correct": true, "explanation": "关门：请人把门关上，与“外面很冷”的语境相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“外面很冷”的请求无关，句意不通。"}, {"text": "写字", "is_correct": false, "explanation": "语义：“写字”与天冷、要求快点的语境不相关，句意不通。"}, {"text": "关灯", "is_correct": false, "explanation": "语义：“关灯”与“外面很冷”的请求无关，句意不通。"}], "explanations": {"关门": "关门：请人把门关上，与“外面很冷”的语境相符。", "唱歌": "语义：“唱歌”与“外面很冷”的请求无关，句意不通。", "写字": "语义：“写字”与天冷、要求快点的语境不相关，句意不通。", "关灯": "语义：“关灯”与“外面很冷”的请求无关，句意不通。"}, "sentence_index": 0, "correct_answer": "关门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把窗户关门了。", "explanation": "这里应该用〈关上〉。“关门”的对象只能是门，窗户要说“关上窗户”。"}, {"text": "他把灯关门了。", "explanation": "这里应该用〈关灯〉。“关门”的对象是门，灯要说“关灯”。"}, {"text": "他把抽屉关门了。", "explanation": "这里应该用〈关上〉。“关门”的对象只能是门，抽屉要说“关上抽屉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关门", "is_correct": true, "explanation": "关门：猫要跑进来，所以要把门关上，句意通顺。"}, {"text": "关灯", "is_correct": false, "explanation": "语义：关灯与“猫要跑进来”的情境无关，无法挡住猫，句意不通。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：“做饭”与猫跑进来的情境无关，句意不通。"}, {"text": "关机", "is_correct": false, "explanation": "搭配：“关机”的对象是电子设备，不能用来阻止猫跑进来。"}], "explanations": {"关门": "关门：猫要跑进来，所以要把门关上，句意通顺。", "关灯": "语义：关灯与“猫要跑进来”的情境无关，无法挡住猫，句意不通。", "做饭": "语义：“做饭”与猫跑进来的情境无关，句意不通。", "关机": "搭配：“关机”的对象是电子设备，不能用来阻止猫跑进来。"}, "sentence_index": 6, "correct_answer": "关门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈让我把电脑关门，别再玩了。", "explanation": "这里应该用〈关机〉。“关门”的对象是门，电脑要说“关机”。"}, {"text": "这本书看完了，我把它关门了。", "explanation": "这里应该用〈合上〉。书要说“合上”，“关门”只用于门。"}, {"text": "下雨了，他把伞关门了。", "explanation": "这里应该用〈收〉。伞要说“收起来”，“关门”不能用于伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一进屋就关门上了。", "corrected_sentence": "我一进屋就关门了。", "error_description": "错误在于“关门”后多接了补语“上”。“关门”后不接“上”，应说“关上门”或“关门了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他关门着，屋子里很安静。", "corrected_sentence": "他关门了，屋子里很安静。", "error_description": "错误在于“着”放错了位置。“着”应接在动词“关”之后，说“关着门”；若要表示动作已完成，则说“关门了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
