INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92638, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "商店、饭馆等停止营业或到点不再营业。", "primary_collocate": null, "pronunciation": "guān mén", "ipa": "kwan˥ mən˧˥", "syllable_count": 2, "sentences": [{"text": "这家饭馆晚上九点关门。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店周日关门，明天再去吧。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为生意不好，那家小店关门了。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆几点关门？", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市快关门了，我们快点买。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，很多店都关门休息。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板今天有事，所以早早关门了。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行下午五点关门，你要早点去。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨，街上的小店都关门了。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书店去年关门了，他很难过。", "target_word": "关门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "关门了", "label": "体标"}, {"form": "关门大吉", "label": "复合"}, {"form": "關門", "label": "繁体"}], "register": "口语", "sense_fingerprint": "商店、饭馆等停业或到点不再营业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df752ed1-047e-4fbd-b779-b0ded6150625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92638, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "关门", "is_correct": true, "explanation": "关门：店铺停业或门关上，与听到的读音一致。"}, {"text": "官民", "is_correct": false, "explanation": "mín（第二声）与 mén（第二声）韵母不同，官民意思是官员和百姓。"}, {"text": "官名", "is_correct": false, "explanation": "míng 与 mén 韵母不同（-ing 与 -en），官名意思是官职的名称。"}, {"text": "官文", "is_correct": false, "explanation": "wén 与 mén 声母不同，官文意思是官方的文件。"}], "explanations": {"关门": "关门：店铺停业或门关上，与听到的读音一致。", "官民": "mín（第二声）与 mén（第二声）韵母不同，官民意思是官员和百姓。", "官名": "míng 与 mén 韵母不同（-ing 与 -en），官名意思是官职的名称。", "官文": "wén 与 mén 声母不同，官文意思是官方的文件。"}, "sentence_index": null, "correct_answer": "关门"}, "level_3": {"options": [{"text": "关门", "is_correct": true, "explanation": "关门：饭馆晚上九点停止营业，句意通顺。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”与饭馆的营业时间无关，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”需要带修理的对象，饭馆晚上九点修理句意不完整。"}, {"text": "考试", "is_correct": false, "explanation": "语义：饭馆不能考试，“考试”与营业时间的语境不符，句意不通。"}], "explanations": {"关门": "关门：饭馆晚上九点停止营业，句意通顺。", "下雨": "语义：“下雨”与饭馆的营业时间无关，句意不通。", "修理": "配价：“修理”需要带修理的对象，饭馆晚上九点修理句意不完整。", "考试": "语义：饭馆不能考试，“考试”与营业时间的语境不符，句意不通。"}, "sentence_index": 0, "correct_answer": "关门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜单关门了。", "explanation": "这里应该用〈撤下〉。“关门”的对象是门或店铺，菜单不能关门。"}, {"text": "他的电话关门了，我打不通。", "explanation": "这里应该用〈关机〉。“关门”只用于门和店铺停业，电话要说“关机”。"}, {"text": "查完字以后，他把字典关门了。", "explanation": "这里应该用〈合上〉。“关门”只用于门或店铺停业，字典要说“合上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关门", "is_correct": true, "explanation": "关门：老板有事，所以早早停止营业，句意通顺。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与老板有事、早早停业的语境无关，句意不通。"}, {"text": "写字", "is_correct": false, "explanation": "语义：“写字”与老板有事、早早停业的语境无关，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与“有事”导致的早退语境不相关，句意不通。"}], "explanations": {"关门": "关门：老板有事，所以早早停止营业，句意通顺。", "跳舞": "语义：“跳舞”与老板有事、早早停业的语境无关，句意不通。", "写字": "语义：“写字”与老板有事、早早停业的语境无关，句意不通。", "游泳": "语义：“游泳”与“有事”导致的早退语境不相关，句意不通。"}, "sentence_index": 6, "correct_answer": "关门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的猫去年关门了，他很难过。", "explanation": "这里应该用〈走丢〉。“关门”只用于店铺停业，不能用于动物。"}, {"text": "他的手机去年关门了，他很难过。", "explanation": "这里应该用〈坏了〉。“关门”只指门关上或店铺停业，手机不能“关门”。"}, {"text": "村里的河去年关门了，大家都很难过。", "explanation": "这里应该用〈断流〉。“关门”只用于门或店铺停业，河水断了要说“断流”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店今天九点就关门上了。", "corrected_sentence": "这家店今天九点就关门了。", "error_description": "错误在于“关门”后多接了补语“上”。店铺停业时“关门”后不接“上”，应说“关门了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天大雨，店早早关门着。", "corrected_sentence": "今天大雨，店早早关门了。", "error_description": "错误在于“关门”后加了“着”。店铺停业是动作完成，应说“关门了”，不能说“关门着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
