INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "男女或雌雄的区别。", "primary_collocate": null, "pronunciation": "xìng bié", "ipa": "ɕiŋ˥˩ pje˧˥", "syllable_count": 2, "sentences": [{"text": "这种小鸟的性别很难分清。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同性别的小狗，长大后样子不一样。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不能因为性别不同给不同工资。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物的性别分雌和雄。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两只猫性别不同，一只雌一只雄。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作能力和性别没有关系。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的性别不同，但都爱画画。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查后，说小马的性别是雄性。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼的性别要长大后才看得出。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的性别不同，但学习机会应该一样。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "性别歧视", "label": "复合"}, {"form": "性别比例", "label": "复合"}], "register": "中性", "sense_fingerprint": "性别·男女或雌雄的区别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f149c945-cf41-413d-b166-ecfc5601d7e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性别", "is_correct": true, "explanation": "正确：「性别」指雌雄之别，正好说明小鸟的雌雄难以分清。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：小鸟没有国籍，「国籍」与这里的语境不合。"}, {"text": "学历", "is_correct": false, "explanation": "语义：小鸟不具备学历，「学历」这里说不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：「分清」后接的是可以辨认的区别，「工资」是报酬，不说分清工资。"}], "explanations": {"性别": "正确：「性别」指雌雄之别，正好说明小鸟的雌雄难以分清。", "国籍": "语义：小鸟没有国籍，「国籍」与这里的语境不合。", "学历": "语义：小鸟不具备学历，「学历」这里说不通。", "工资": "搭配：「分清」后接的是可以辨认的区别，「工资」是报酬，不说分清工资。"}, "sentence_index": 0, "correct_answer": "性别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "动物的性别分温顺和凶猛。", "explanation": "这里应该用〈性格〉。性别指雌雄，不能用来说温顺、凶猛这类性情。"}, {"text": "这只狗的性别是拉布拉多。", "explanation": "这里应该用〈品种〉。性别只指雌或雄，不能说成品种。"}, {"text": "这只鸟的性别很漂亮。", "explanation": "这里应该用〈外貌〉。性别是雌雄之别，不能用来形容“漂亮”这类外貌特征。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性别", "is_correct": true, "explanation": "正确：「性别」指男女或雌雄之别，与前面的「不同」搭配，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能作为人群之间的区别，这里说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」是食物或气味的特征，不能说「他们的味道不同」。"}, {"text": "形状", "is_correct": false, "explanation": "语义：「形状」指物体的外形，人与人之间不用形状区分，「他们的形状不同」说不通。"}], "explanations": {"性别": "正确：「性别」指男女或雌雄之别，与前面的「不同」搭配，句意通顺。", "天气": "语义：天气不能作为人群之间的区别，这里说不通。", "味道": "语义：「味道」是食物或气味的特征，不能说「他们的味道不同」。", "形状": "语义：「形状」指物体的外形，人与人之间不用形状区分，「他们的形状不同」说不通。"}, "sentence_index": 6, "correct_answer": "性别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗的性别是三岁。", "explanation": "这里应该用〈年龄〉。性别只指雌雄，不能表示岁数。"}, {"text": "这只狗的性别是十公斤。", "explanation": "这里应该用〈体重〉。性别不能用来表示重量。"}, {"text": "这只猫的性别是三十厘米。", "explanation": "这里应该用〈身高〉。性别不能用来表示长度或身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只鸡的性别雌的。", "corrected_sentence": "这只鸡的性别是雌的。", "error_description": "漏掉判断动词「是」。“性别雌的”结构不完整，应说“性别是雌的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条鱼要长大后才能看出它性别。", "corrected_sentence": "这条鱼要长大后才能看出它的性别。", "error_description": "漏掉定语标记「的」。“它性别”不成词组，应说“它的性别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
