INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92643, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "限度是最多能到哪里的那条线。", "primary_collocate": null, "pronunciation": "xiàn dù", "ipa": "ɕjɛn˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "每个人的耐心都有限度。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩笑要开，但不能超过限度。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥能承受的重量有一定限度。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝酒总是有限度，从不喝醉。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱花多少要有个限度，别乱买东西。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，玩游戏的时间要有限度。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的忍耐已经到了限度。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电梯有载重限度，请不要超载。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间开玩笑，也要知道限度。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脾气好，但好脾气也有限度。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "限度：事情最多能到的那条界线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a127e4-6f10-4f8a-b8d9-beff9815793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92643, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "限度", "is_correct": true, "explanation": "限度（xiàn dù）指事情最多能到的那条界线，正确答案。"}, {"text": "现代", "is_correct": false, "explanation": "dài 与 dù 韵母不同（ai 与 u），意思是当代，与限度不同。"}, {"text": "线路", "is_correct": false, "explanation": "lù 与 dù 声母不同（l 与 d），意思是线路，与限度不同。"}, {"text": "限速", "is_correct": false, "explanation": "sù 与 dù 声母不同（s 与 d），意思是速度限制，与限度不同。"}], "explanations": {"限度": "限度（xiàn dù）指事情最多能到的那条界线，正确答案。", "现代": "dài 与 dù 韵母不同（ai 与 u），意思是当代，与限度不同。", "线路": "lù 与 dù 声母不同（l 与 d），意思是线路，与限度不同。", "限速": "sù 与 dù 声母不同（s 与 d），意思是速度限制，与限度不同。"}, "sentence_index": null, "correct_answer": "限度"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：耐心本身没有颜色，“耐心都有颜色”说不通。"}, {"text": "限度", "is_correct": true, "explanation": "限度指事情最多能到的界线，耐心可以有这样的界线，符合句意。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”一般不与“耐心”搭配，不说耐心有重量。"}, {"text": "方向", "is_correct": false, "explanation": "语义：耐心没有方向，“耐心都有方向”不成立。"}], "explanations": {"颜色": "语义：耐心本身没有颜色，“耐心都有颜色”说不通。", "限度": "限度指事情最多能到的界线，耐心可以有这样的界线，符合句意。", "重量": "搭配：“重量”一般不与“耐心”搭配，不说耐心有重量。", "方向": "语义：耐心没有方向，“耐心都有方向”不成立。"}, "sentence_index": 0, "correct_answer": "限度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个国家之间的限度非常清楚。", "explanation": "这里应该用〈界限〉。限度指最多能到的那条界线，不指两地之间的分界线；分界线要用界限。"}, {"text": "这次活动的限度很大，大家都很期待。", "explanation": "这里应该用〈范围〉。限度强调界线和极限，不表示覆盖面；活动涉及的面广要用范围。"}, {"text": "这份报告的提交限度是下周五。", "explanation": "这里应该用〈期限〉。限度不指截止时间，报告必须在某天前交要用期限。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92643, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "限度", "is_correct": true, "explanation": "限度（xiàn dù）指事情最多能到的那条界线，正确答案。"}, {"text": "现代", "is_correct": false, "explanation": "xiàn dài：dài 与 dù 韵母不同，意思是当代，与限度不同。"}, {"text": "鲜度", "is_correct": false, "explanation": "xiān 与 xiàn 声调不同（阴平与去声），意思是新鲜的程度，与限度不同。"}, {"text": "限定", "is_correct": false, "explanation": "xiàn dìng：dìng 与 dù 韵母不同，意思是规定范围，是动词，与限度不同。"}], "explanations": {"限度": "限度（xiàn dù）指事情最多能到的那条界线，正确答案。", "现代": "xiàn dài：dài 与 dù 韵母不同，意思是当代，与限度不同。", "鲜度": "xiān 与 xiàn 声调不同（阴平与去声），意思是新鲜的程度，与限度不同。", "限定": "xiàn dìng：dìng 与 dù 韵母不同，意思是规定范围，是动词，与限度不同。"}, "sentence_index": null, "correct_answer": "限度"}, "level_3": {"options": [{"text": "气味", "is_correct": false, "explanation": "语义：忍耐不能达到气味的程度，“忍耐已经到了气味”说不通。"}, {"text": "字母", "is_correct": false, "explanation": "语义：字母与忍耐无关，“忍耐已经到了字母”不成立。"}, {"text": "限度", "is_correct": true, "explanation": "限度指忍耐最多能到的界线，“已经到了”后接限度符合句意。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“到了体积”不是常见搭配，忍耐一般不说到了体积。"}], "explanations": {"气味": "语义：忍耐不能达到气味的程度，“忍耐已经到了气味”说不通。", "字母": "语义：字母与忍耐无关，“忍耐已经到了字母”不成立。", "限度": "限度指忍耐最多能到的界线，“已经到了”后接限度符合句意。", "体积": "搭配：“到了体积”不是常见搭配，忍耐一般不说到了体积。"}, "sentence_index": 6, "correct_answer": "限度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家离学校的限度很远。", "explanation": "这里应该用〈距离〉。限度指最多能到的界线，不表示空间的远近；两地之间的远近要用距离。"}, {"text": "这辆车的限度很快。", "explanation": "这里应该用〈速度〉。限度不表示快慢；车跑得快要用速度。"}, {"text": "会议的限度定在下午三点。", "explanation": "这里应该用〈时间〉。限度不指时间点，会议定在某个时间要用时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做什么事都要有条限度，不能太过分。", "corrected_sentence": "做什么事都要有个限度，不能太过分。", "error_description": "错误：量词用错了。“限度”前面口语中常说“有个限度”，不能用量词“条”。正确：“做什么事都要有个限度，不能太过分。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔开支有一定个限度，不能随便花。", "corrected_sentence": "这笔开支有一定的限度，不能随便花。", "error_description": "“一定”作定语修饰“限度”时要用“的”，不能用量词“个”；应说“一定的限度”，不说“一定个限度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
