INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "范围的极限；最大的程度。", "primary_collocate": null, "pronunciation": "xiàn dù", "ipa": "ɕjɛn˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "我们要最大限度地减少浪费。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在能力的限度内，尽力帮了大家。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，吃药要在规定的限度内。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事已经超出了我能力的限度。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要在最大限度上保护好环境。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把时间用到了最大限度。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的身体有一定限度，不能一直熬夜。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经尽了最大限度的努力。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作再忙，也要在身体能承受的限度内。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让我们把成本降到最低限度。", "target_word": "限度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "限度：范围的极限，最大的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a127e4-6f10-4f8a-b8d9-beff9815793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92644, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "限度", "is_correct": true, "explanation": "限度（xiàn dù）指范围的极限、最大的程度，正确答案。"}, {"text": "现代", "is_correct": false, "explanation": "dài 与 dù 韵母不同（ai 与 u），意思是当代，与限度不同。"}, {"text": "线路", "is_correct": false, "explanation": "lù 与 dù 声母不同（l 与 d），意思是线路，与限度不同。"}, {"text": "限速", "is_correct": false, "explanation": "sù 与 dù 声母不同（s 与 d），意思是速度限制，与限度不同。"}], "explanations": {"限度": "限度（xiàn dù）指范围的极限、最大的程度，正确答案。", "现代": "dài 与 dù 韵母不同（ai 与 u），意思是当代，与限度不同。", "线路": "lù 与 dù 声母不同（l 与 d），意思是线路，与限度不同。", "限速": "sù 与 dù 声母不同（s 与 d），意思是速度限制，与限度不同。"}, "sentence_index": null, "correct_answer": "限度"}, "level_3": {"options": [{"text": "性格", "is_correct": false, "explanation": "语义：浪费不能用性格来修饰，“最大性格地减少浪费”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“最大颜色”不是固定搭配，“最大……地减少浪费”不成立。"}, {"text": "限度", "is_correct": true, "explanation": "限度指最大的程度，“最大限度地”后接减少浪费，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与减少浪费无关，句子不成立。"}], "explanations": {"性格": "语义：浪费不能用性格来修饰，“最大性格地减少浪费”说不通。", "颜色": "搭配：“最大颜色”不是固定搭配，“最大……地减少浪费”不成立。", "限度": "限度指最大的程度，“最大限度地”后接减少浪费，符合句意。", "年龄": "语义：年龄与减少浪费无关，句子不成立。"}, "sentence_index": 0, "correct_answer": "限度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的限度很鲜艳。", "explanation": "这里应该用〈颜色〉。限度指界线和最大程度，不能用来形容色彩；画的颜色要用颜色。"}, {"text": "考试的限度定在上午。", "explanation": "这里应该用〈时间〉。限度不表示时点，考试安排在某个时间要用时间。"}, {"text": "汽车的限度向北行驶。", "explanation": "这里应该用〈方向〉。限度不表示方位，车辆行驶的朝向要用方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92644, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "限度", "is_correct": true, "explanation": "限度（xiàn dù）指范围的极限、最大的程度，正确答案。"}, {"text": "现代", "is_correct": false, "explanation": "xiàn dài：dài 与 dù 韵母不同，意思是当代，与限度不同。"}, {"text": "鲜度", "is_correct": false, "explanation": "xiān 与 xiàn 声调不同（阴平与去声），意思是新鲜的程度，与限度不同。"}, {"text": "限定", "is_correct": false, "explanation": "xiàn dìng：dìng 与 dù 韵母不同，意思是规定范围，是动词，与限度不同。"}], "explanations": {"限度": "限度（xiàn dù）指范围的极限、最大的程度，正确答案。", "现代": "xiàn dài：dài 与 dù 韵母不同，意思是当代，与限度不同。", "鲜度": "xiān 与 xiàn 声调不同（阴平与去声），意思是新鲜的程度，与限度不同。", "限定": "xiàn dìng：dìng 与 dù 韵母不同，意思是规定范围，是动词，与限度不同。"}, "sentence_index": null, "correct_answer": "限度"}, "level_3": {"options": [{"text": "方向", "is_correct": false, "explanation": "语义：身体没有方向，“人的身体有一定方向”说不通。"}, {"text": "限度", "is_correct": true, "explanation": "限度指身体能承受的最大程度，“有一定限度”与“不能一直熬夜”语境相符。"}, {"text": "字母", "is_correct": false, "explanation": "语义：身体不能有字母，句子不成立。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：身体一般不说有价格，“有一定价格”与人体的语境不搭。"}], "explanations": {"方向": "语义：身体没有方向，“人的身体有一定方向”说不通。", "限度": "限度指身体能承受的最大程度，“有一定限度”与“不能一直熬夜”语境相符。", "字母": "语义：身体不能有字母，句子不成立。", "价格": "搭配：身体一般不说有价格，“有一定价格”与人体的语境不搭。"}, "sentence_index": 6, "correct_answer": "限度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议的限度定在大厅里。", "explanation": "这里应该用〈地点〉。限度指最多能到的界线，不指场所；会议的场所要用地点。"}, {"text": "这条河的限度很长。", "explanation": "这里应该用〈长度〉。限度指最大的程度，不表示事物有多长；河流有多长要用长度。"}, {"text": "这次活动的报名限度是下周三。", "explanation": "这里应该用〈期限〉。限度不指截止时间，报名截止日要用期限。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的做法已经超出了法律允许地限度。", "corrected_sentence": "他的做法已经超出了法律允许的限度。", "error_description": "错误：“法律允许”作定语修饰名词“限度”，要用“的”，不能用“地”。正确：“他的做法已经超出了法律允许的限度。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要最大限度的节约能源。", "corrected_sentence": "我们要最大限度地节约能源。", "error_description": "错误：“最大限度”作状语修饰动词“节约”时，后面要用“地”，不用“的”。正确：“我们要最大限度地节约能源。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
