INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一员是一群人里的其中一个人。", "primary_collocate": null, "pronunciation": "yì yuán", "ipa": "i˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我是这个班的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成了足球队的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎你成为我们公司的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王是志愿者队伍中的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很高兴成为家庭的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的保姆很快就成了我们家的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这支科学考察队的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都是社会的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想做这个大家庭里的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，你也是我们小组的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一群人中的其中一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92645, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一员", "is_correct": true, "explanation": "“一员”指属于某个集体的一个成员，是正确答案。"}, {"text": "议院", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，“议院”指议会。"}, {"text": "医院", "is_correct": false, "explanation": "yī 与 yì、yuàn 与 yuán 的声调都不同，“医院”是看病的地方。"}, {"text": "意愿", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，“意愿”指愿望。"}], "explanations": {"一员": "“一员”指属于某个集体的一个成员，是正确答案。", "议院": "yuàn（第四声）与 yuán（第二声）声调不同，“议院”指议会。", "医院": "yī 与 yì、yuàn 与 yuán 的声调都不同，“医院”是看病的地方。", "意愿": "yuàn（第四声）与 yuán（第二声）声调不同，“意愿”指愿望。"}, "sentence_index": null, "correct_answer": "一员"}, "level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：“教室”是场所，不能指人，与“这个班的”不搭配。"}, {"text": "一员", "is_correct": true, "explanation": "“一员”指属于这个班的一个成员，符合句中语境。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是物品，不能说“我是这个班的黑板”。"}, {"text": "同桌", "is_correct": false, "explanation": "搭配：“同桌”要说“某人的同桌”，不能直接用“这个班的”修饰。"}], "explanations": {"教室": "语义：“教室”是场所，不能指人，与“这个班的”不搭配。", "一员": "“一员”指属于这个班的一个成员，符合句中语境。", "黑板": "语义：“黑板”是物品，不能说“我是这个班的黑板”。", "同桌": "搭配：“同桌”要说“某人的同桌”，不能直接用“这个班的”修饰。"}, "sentence_index": 0, "correct_answer": "一员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班买了一员新黑板。", "explanation": "这里应该用〈块〉。“一员”只用于人，不能用来数黑板，黑板要说“一块”。"}, {"text": "他收到了一员礼物。", "explanation": "这里应该用“一份”。“一员”只用来指人，不能拿来数礼物。"}, {"text": "我家养了一员小狗。", "explanation": "这里应该用〈一只〉。“一员”指人在集体中的身份，只用来数人，不能用来数小狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植物", "is_correct": false, "explanation": "语义：“植物”不是人，不能作为考察队的成员。"}, {"text": "一员", "is_correct": true, "explanation": "“一员”指属于这支考察队的一个成员，符合句中语境。"}, {"text": "望远镜", "is_correct": false, "explanation": "语义：“望远镜”是仪器，不指人。"}, {"text": "邻居", "is_correct": false, "explanation": "搭配：“邻居”指住得近的人，与“考察队”之间没有居住关系，不能这样修饰。"}], "explanations": {"植物": "语义：“植物”不是人，不能作为考察队的成员。", "一员": "“一员”指属于这支考察队的一个成员，符合句中语境。", "望远镜": "语义：“望远镜”是仪器，不指人。", "邻居": "搭配：“邻居”指住得近的人，与“考察队”之间没有居住关系，不能这样修饰。"}, "sentence_index": 6, "correct_answer": "一员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他骑了一员自行车。", "explanation": "这里应该用〈辆〉。“一员”只用于人，不能用来数自行车，自行车要说“一辆”。"}, {"text": "我们今天吃了一员饺子。", "explanation": "这里应该用“一盘”。“一员”只用于人，不用来数食物。"}, {"text": "他买了一员新鞋。", "explanation": "这里应该用〈一双〉。“一员”只用来指人，不能用来数鞋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是我们学校的一员的。", "corrected_sentence": "她是我们学校的一员。", "error_description": "多加了“的”：“一员”后面不能再加“的”，应去掉句末多余的“的”，正确说法是“我们学校的一员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们都是学校的一员们。", "corrected_sentence": "孩子们都是学校的一员。", "error_description": "多加了“们”：“一员”是数量短语，后面不能再加“们”表示复数，应说“学校的一员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
