INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "集体或团体中的一个成员。", "primary_collocate": null, "pronunciation": "yì yuán", "ipa": "i˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他是篮球队里很重要的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎你加入我们，成为这个团队的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都是地球村的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚刚成了合唱团的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李是医疗队的一员，去了山区。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个同学都是班级的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很骄傲，因为他是国家队的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做公司的一员，我要努力工作。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人也是我们社区的一员。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经是我们大家庭的一员了。", "target_word": "一员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "集体或团体中的一个成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92646, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一员", "is_correct": true, "explanation": "“一员”指集体或团体中的一个成员，是正确答案。"}, {"text": "议院", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，“议院”指议会。"}, {"text": "医院", "is_correct": false, "explanation": "yī 与 yì、yuàn 与 yuán 的声调都不同，“医院”是看病的地方。"}, {"text": "意愿", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，“意愿”指愿望。"}], "explanations": {"一员": "“一员”指集体或团体中的一个成员，是正确答案。", "议院": "yuàn（第四声）与 yuán（第二声）声调不同，“议院”指议会。", "医院": "yī 与 yì、yuàn 与 yuán 的声调都不同，“医院”是看病的地方。", "意愿": "yuàn（第四声）与 yuán（第二声）声调不同，“意愿”指愿望。"}, "sentence_index": null, "correct_answer": "一员"}, "level_3": {"options": [{"text": "球门", "is_correct": false, "explanation": "语义：“球门”是球场上的设施，不指人，不能作为篮球队的成员。"}, {"text": "一员", "is_correct": true, "explanation": "“一员”指篮球队里的一个成员，符合“很重要的”这一语境。"}, {"text": "篮筐", "is_correct": false, "explanation": "语义：“篮筐”是器材，不能指人，与“很重要的”搭配不通。"}, {"text": "球队", "is_correct": false, "explanation": "搭配：“篮球队里”已说明是球队，再用“球队”重复，且不能作“很重要的”的对象。"}], "explanations": {"球门": "语义：“球门”是球场上的设施，不指人，不能作为篮球队的成员。", "一员": "“一员”指篮球队里的一个成员，符合“很重要的”这一语境。", "篮筐": "语义：“篮筐”是器材，不能指人，与“很重要的”搭配不通。", "球队": "搭配：“篮球队里”已说明是球队，再用“球队”重复，且不能作“很重要的”的对象。"}, "sentence_index": 0, "correct_answer": "一员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司新添了一员电脑。", "explanation": "这里应该用〈台〉。“一员”只用于人，不能用来数电脑，电脑要说“一台”。"}, {"text": "桌子上放着一员苹果。", "explanation": "这里应该用“一篮”。“一员”只用于人，不能拿来数水果。"}, {"text": "我们家新买了一员汽车。", "explanation": "这里应该用〈一辆〉。“一员”只用于人，不能用来数车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国旗", "is_correct": false, "explanation": "语义：“国旗”是旗帜，不指人，不能作国家队的成员。"}, {"text": "一员", "is_correct": true, "explanation": "“一员”指属于国家队的一个成员，符合“很骄傲”的语境。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：“体育馆”是场所，不能作为国家队的成员。"}, {"text": "金牌", "is_correct": false, "explanation": "语义：“金牌”是奖牌，不指人，不能作为国家队的成员。"}], "explanations": {"国旗": "语义：“国旗”是旗帜，不指人，不能作国家队的成员。", "一员": "“一员”指属于国家队的一个成员，符合“很骄傲”的语境。", "体育馆": "语义：“体育馆”是场所，不能作为国家队的成员。", "金牌": "语义：“金牌”是奖牌，不指人，不能作为国家队的成员。"}, "sentence_index": 6, "correct_answer": "一员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们小区新修了一员公园。", "explanation": "这里应该用〈座〉。“一员”只用于人，不能用来数公园，公园要说“一座”。"}, {"text": "他吃了一员蛋糕。", "explanation": "这里应该用“一块”。“一员”只用于人，不用来数食物。"}, {"text": "他写了一员长篇小说。", "explanation": "这里应该用〈一部〉。“一员”只用来指人，不能用来数作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经成了这个团队的一员的。", "corrected_sentence": "他已经成了这个团队的一员。", "error_description": "多加了“的”：“一员”后面不能再加“的”，应去掉句末多余的“的”，正确说法是“这个团队的一员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚加入了一个新的小组，成了其中的一员的。", "corrected_sentence": "他刚加入了一个新的小组，成了其中的一员。", "error_description": "多加了“的”：“一员”后面不能再加“的”，应去掉句末多余的“的”，正确说法是“成了其中的一员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "奖励与惩罚是一对反义词：奖励是对做得好的事给予的好处，惩罚是做错事后要承受的事。"}, {"text": "杯子", "is_correct": false, "explanation": "杯子是器具，与惩罚没有反义关系。"}, {"text": "风景", "is_correct": false, "explanation": "风景是自然或城市的景色，与惩罚没有反义关系。"}, {"text": "计划", "is_correct": false, "explanation": "计划是打算和安排，与惩罚没有反义关系。"}], "correct_answer": "奖励", "explanations": {"奖励": "奖励与惩罚是一对反义词：奖励是对做得好的事给予的好处，惩罚是做错事后要承受的事。", "杯子": "杯子是器具，与惩罚没有反义关系。", "风景": "风景是自然或城市的景色，与惩罚没有反义关系。", "计划": "计划是打算和安排，与惩罚没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "奖励与惩罚是一对反义词：奖励是对做得好的事给予的好处，惩罚是做错事后要承受的事。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是建筑的构件，与惩罚没有反义关系。"}, {"text": "节日", "is_correct": false, "explanation": "节日是特定的纪念日，与惩罚没有反义关系。"}, {"text": "方法", "is_correct": false, "explanation": "方法是做事的途径，与惩罚没有反义关系。"}], "correct_answer": "奖励", "explanations": {"奖励": "奖励与惩罚是一对反义词：奖励是对做得好的事给予的好处，惩罚是做错事后要承受的事。", "窗户": "窗户是建筑的构件，与惩罚没有反义关系。", "节日": "节日是特定的纪念日，与惩罚没有反义关系。", "方法": "方法是做事的途径，与惩罚没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "惩罚是做错事以后，被要求做不喜欢的事。", "primary_collocate": null, "pronunciation": "chéng fá", "ipa": "ʈʂʰɤŋ˧˥ fa˧˥", "syllable_count": 2, "sentences": [{"text": "做错事要接受惩罚。", "target_word": "惩罚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天的惩罚是洗碗。", "target_word": "惩罚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他迟到了，老师的惩罚是打扫教室。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟打破了杯子，受到了妈妈的惩罚。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏输的人要接受惩罚，比如唱歌。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最怕的惩罚是不能看电视。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对孩子来说，罚站是一种很难受的惩罚。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业没写完，他的惩罚是放学后留下来。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手机弄坏了，爸爸的惩罚是一个月不能玩游戏。", "target_word": "惩罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸让孩子自己决定惩罚的内容，他选了跑步。", "target_word": "惩罚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次惩罚", "label": "量词：次"}, {"form": "惩罚措施", "label": "复合"}, {"form": "懲罰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做错事后被要求做不喜欢的事（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6c760cb-57e2-4f62-a33d-bc36fa2b95af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "惩罚", "is_correct": true, "explanation": "惩罚：做错事后要承受的处分，与“接受”搭配。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金是发给表现好的人的钱，做错事不会得到奖金。"}, {"text": "荣誉", "is_correct": false, "explanation": "语义：荣誉是因成绩而得到的光荣，与“做错事”相矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“接受”不与“作业”搭配，作业应说完成或布置。"}], "explanations": {"惩罚": "惩罚：做错事后要承受的处分，与“接受”搭配。", "奖金": "语义：奖金是发给表现好的人的钱，做错事不会得到奖金。", "荣誉": "语义：荣誉是因成绩而得到的光荣，与“做错事”相矛盾。", "作业": "搭配：“接受”不与“作业”搭配，作业应说完成或布置。"}, "sentence_index": 0, "correct_answer": "惩罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的自行车需要惩罚。", "explanation": "这里应该用〈修理〉。修理用于坏了的物品，惩罚的对象是做错事的人，不能用于自行车。"}, {"text": "他因为超速，去交了惩罚。", "explanation": "这里应该用〈罚款〉。交的是钱款，惩罚指做错事后要承受的事，不能用“交”来表示。"}, {"text": "他很快就吃完了惩罚。", "explanation": "这里应该用〈午饭〉。吃完的是饭食，惩罚是做错事后要承受的事，不能被“吃完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惩罚", "is_correct": true, "explanation": "惩罚：罚站这种做错事后承受的处分，与“一种很难受的”搭配。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是令人高兴的东西，与“很难受”相矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "语义：享受是愉快的体验，与“很难受”的说法相矛盾。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏是供人娱乐的活动，“很难受的游戏”说不通。"}], "explanations": {"惩罚": "惩罚：罚站这种做错事后承受的处分，与“一种很难受的”搭配。", "礼物": "语义：礼物是令人高兴的东西，与“很难受”相矛盾。", "享受": "语义：享受是愉快的体验，与“很难受”的说法相矛盾。", "游戏": "语义：游戏是供人娱乐的活动，“很难受的游戏”说不通。"}, "sentence_index": 6, "correct_answer": "惩罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在晚会上唱了惩罚。", "explanation": "这里应该用〈歌〉。唱的是歌，惩罚是做错事后要承受的事，不能被“唱”。"}, {"text": "他每天早上喝一杯惩罚。", "explanation": "这里应该用〈牛奶〉。喝的是饮料，惩罚是做错事后要承受的事，不能被“喝”。"}, {"text": "他从这次失败中吸取了惩罚。", "explanation": "这里应该用〈教训〉。吸取的是教训，惩罚是做错事后要承受的事，不能被吸取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前受到过一条惩罚，这次要留下来打扫教室。", "corrected_sentence": "他以前受到过一次惩罚，这次要留下来打扫教室。", "error_description": "量词错误：“惩罚”应用量词“次”，说“一次惩罚”；“条”用于长条形事物，不能修饰“惩罚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他惩罚是一周不能看电视。", "corrected_sentence": "他的惩罚是一周不能看电视。", "error_description": "错误在于定语标记“的”被漏掉。应说“他的惩罚”，“他惩罚是”不符合汉语的名词修饰结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "奖励与惩罚是一对反义词：奖励是对做得好的人给予奖赏，惩罚是对犯错的人给予处分。"}, {"text": "批准", "is_correct": false, "explanation": "批准是同意或核准，与惩罚没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "参加是加入某项活动，与惩罚没有反义关系。"}, {"text": "修建", "is_correct": false, "explanation": "修建是建造房屋或道路，与惩罚没有反义关系。"}], "correct_answer": "奖励", "explanations": {"奖励": "奖励与惩罚是一对反义词：奖励是对做得好的人给予奖赏，惩罚是对犯错的人给予处分。", "批准": "批准是同意或核准，与惩罚没有反义关系。", "参加": "参加是加入某项活动，与惩罚没有反义关系。", "修建": "修建是建造房屋或道路，与惩罚没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "奖励与惩罚是一对反义词：奖励是对做得好的人给予奖赏，惩罚是对犯错的人给予处分。"}, {"text": "购买", "is_correct": false, "explanation": "购买是付钱买进，与惩罚没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是交换意见，与惩罚没有反义关系。"}, {"text": "出版", "is_correct": false, "explanation": "出版是把作品印刷发行，与惩罚没有反义关系。"}], "correct_answer": "奖励", "explanations": {"奖励": "奖励与惩罚是一对反义词：奖励是对做得好的人给予奖赏，惩罚是对犯错的人给予处分。", "购买": "购买是付钱买进，与惩罚没有反义关系。", "讨论": "讨论是交换意见，与惩罚没有反义关系。", "出版": "出版是把作品印刷发行，与惩罚没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对犯错或犯罪的人给予处分。", "primary_collocate": null, "pronunciation": "chéng fá", "ipa": "ʈʂʰɤŋ˧˥ fa˧˥", "syllable_count": 2, "sentences": [{"text": "老师惩罚了迟到的学生。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律会惩罚犯罪的人。", "target_word": "惩罚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司决定惩罚泄露秘密的员工。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈没有惩罚弟弟，只是批评了他。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王惩罚了偷东西的人，把他关进监狱。", "target_word": "惩罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判因为犯规惩罚了那名球员。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官依法惩罚了这个骗子。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做错了事，爸爸却从来不惩罚他。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不应该随便惩罚做错事的孩子。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府已经惩罚过那家排放污水的工厂。", "target_word": "惩罚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惩罚了", "label": "体标：了"}, {"form": "惩罚过", "label": "体标：过"}, {"form": "懲罰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对犯错或犯罪者给予处分（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6c760cb-57e2-4f62-a33d-bc36fa2b95af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "惩罚", "is_correct": true, "explanation": "惩罚：对迟到这种过错给予处分，与“迟到的学生”搭配。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬是肯定好的行为，与“迟到”这一过错相矛盾。"}, {"text": "赞赏", "is_correct": false, "explanation": "语义：赞赏是欣赏优点，不能用来说对迟到学生的处理。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：批改用于作业、试卷，不能说“批改学生”。"}], "explanations": {"惩罚": "惩罚：对迟到这种过错给予处分，与“迟到的学生”搭配。", "表扬": "语义：表扬是肯定好的行为，与“迟到”这一过错相矛盾。", "赞赏": "语义：赞赏是欣赏优点，不能用来说对迟到学生的处理。", "批改": "搭配：批改用于作业、试卷，不能说“批改学生”。"}, "sentence_index": 0, "correct_answer": "惩罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在报告里惩罚了当时的政策。", "explanation": "这里应该用〈批评〉。惩罚针对犯错的人，政策是事物，不能被惩罚；批评可以用于政策和观点。"}, {"text": "他惩罚了这个错误的说法。", "explanation": "这里应该用〈纠正〉。纠正的对象可以是错误的说法，惩罚的对象只能是犯错的人。"}, {"text": "我们要尽快惩罚这个问题。", "explanation": "这里应该用〈处理〉。处理问题是设法解决，惩罚只用于犯错的人，不能用于“问题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惩罚", "is_correct": true, "explanation": "惩罚：依法对骗子给予处分，与“依法”的语境一致。"}, {"text": "招待", "is_correct": false, "explanation": "语义：招待是款待客人，“依法招待骗子”说不通。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：感谢是表达谢意，法官不会对骗子表示谢意。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是讥讽，与法官依法办案的身份不符。"}], "explanations": {"惩罚": "惩罚：依法对骗子给予处分，与“依法”的语境一致。", "招待": "语义：招待是款待客人，“依法招待骗子”说不通。", "感谢": "语义：感谢是表达谢意，法官不会对骗子表示谢意。", "嘲笑": "语义：嘲笑是讥讽，与法官依法办案的身份不符。"}, "sentence_index": 6, "correct_answer": "惩罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他惩罚了房东的损失。", "explanation": "这里应该用〈赔偿〉。赔偿是对损失给予补偿，惩罚的对象只能是做错事的人，“损失”不能被惩罚。"}, {"text": "工人惩罚了那台坏掉的洗衣机。", "explanation": "这里应该用〈修理〉。修理是使坏了的物品恢复正常，惩罚的对象只能是做错事的人，不能用于洗衣机。"}, {"text": "医生惩罚了他的感冒。", "explanation": "这里应该用〈治疗〉。惩罚的对象只能是做错事的人，感冒是疾病，不能被惩罚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校对打架的学生惩罚的很严厉。", "corrected_sentence": "学校对打架的学生惩罚得很严厉。", "error_description": "结构助词错误：程度补语前应用“得”，“惩罚的很严厉”中的“的”应为“得”，正确说法是“惩罚得很严厉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察惩罚了过这个小偷。", "corrected_sentence": "警察惩罚过这个小偷。", "error_description": "错误在于“过”前多加了“了”。经历态“过”应紧跟动词，说“惩罚过这个小偷”，“惩罚了过这个小偷”不符合汉语的体标用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
