INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92649, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "陛下是对国王或皇帝的尊敬叫法。", "primary_collocate": null, "pronunciation": "bì xià", "ipa": "pi˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "在电影里，大臣见到国王都叫他陛下。", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝进来时，所有人都站起来说：“陛下好！”", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对国王不能叫名字，要叫陛下。", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问陛下，晚饭想吃什么？", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，“陛下”是对皇帝的尊敬叫法。", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王子对父亲国王说：“陛下，我想去看看外面的世界。”", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王今天很高兴，大家都祝陛下身体好。", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的士兵见到皇帝，马上喊：“陛下万岁！”", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在戏里演国王，别人都要叫他陛下。", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王回来了，仆人赶紧说：“欢迎回来，陛下。”", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "称呼国王或皇帝时用的尊敬叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92649, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陛下", "is_correct": true, "explanation": "“陛下”是对国王的尊敬叫法，大臣见到国王时这样称呼，符合句意。"}, {"text": "爸爸", "is_correct": false, "explanation": "语义：大臣称呼国王不会叫“爸爸”，二者身份关系不符。"}, {"text": "同桌", "is_correct": false, "explanation": "语义：“同桌”是同学之间的称呼，与大臣对国王的称呼不符。"}, {"text": "小朋友", "is_correct": false, "explanation": "语域：“小朋友”是随意的口语称呼，与“陛下”的尊称不符。"}], "explanations": {"陛下": "“陛下”是对国王的尊敬叫法，大臣见到国王时这样称呼，符合句意。", "爸爸": "语义：大臣称呼国王不会叫“爸爸”，二者身份关系不符。", "同桌": "语义：“同桌”是同学之间的称呼，与大臣对国王的称呼不符。", "小朋友": "语域：“小朋友”是随意的口语称呼，与“陛下”的尊称不符。"}, "sentence_index": 0, "correct_answer": "陛下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去商店买了两斤陛下。", "explanation": "这里应该用〈苹果〉。“陛下”是对国王或皇帝的尊称，不是能买的东西。"}, {"text": "数学老师走进教室，我们站起来说：“陛下好！”", "explanation": "这里应该用〈老师〉。“陛下”只尊称国王或皇帝，见到老师应说“老师好”。"}, {"text": "今天是奶奶的生日，我们向她鞠躬说：“陛下，生日快乐！”", "explanation": "这里应该用〈您〉。“陛下”只尊称国王或皇帝，祝奶奶生日应说“您”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92649, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陛下", "is_correct": true, "explanation": "“陛下”指国王这样的君主，大家祝君主身体好，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有身体，不能祝它身体好。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有身体，不能祝它身体好。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“身体好”通常用于人，不能用于房子。"}], "explanations": {"陛下": "“陛下”指国王这样的君主，大家祝君主身体好，符合句意。", "石头": "语义：石头没有身体，不能祝它身体好。", "桌子": "语义：桌子没有身体，不能祝它身体好。", "房子": "搭配：“身体好”通常用于人，不能用于房子。"}, "sentence_index": 6, "correct_answer": "陛下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里坐着好几位陛下。", "explanation": "这里应该用〈学生〉。“陛下”只用于君主，教室里的人应说“学生”。"}, {"text": "他走进教室，大声说：“我是陛下，都给我坐好！”", "explanation": "这里应该用〈本人〉。“陛下”是别人对君主的尊称，不能用来自称。"}, {"text": "这座宫殿的陛下有十级，我们要爬上去。", "explanation": "这里应该用〈台阶〉。“陛”古义指台阶，但“陛下”现在只作君主尊称，不能指台阶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "侍卫跑进来，对国王说：“陛下的，城门开了。”", "corrected_sentence": "侍卫跑进来，对国王说：“陛下，城门开了。”", "error_description": "“陛下”作称呼时后面不加“的”，应直接用逗号连接，即“陛下，……”。错误在“的”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家向国王行礼，齐声喊：“陛下们万岁！”", "corrected_sentence": "大家向国王行礼，齐声喊：“陛下万岁！”", "error_description": "“陛下”是对单一君主的尊称，不能加“们”表示复数，错误在“们”，应改为“陛下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
