INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92650, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对君主的尊称。", "primary_collocate": null, "pronunciation": "bì xià", "ipa": "pi˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "大臣跪在地上说：“陛下，敌人已经到了。”", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王走进大厅，大家都对他说：“陛下好。”", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军对皇帝说：“陛下，请您下命令吧。”", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陛下，您今天想先见哪位大臣？", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王后笑着问国王：“陛下，您累了吗？”", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣们站在门口，轻声叫着“陛下”。", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的皇帝坐在椅子上，听大臣叫他陛下。", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请陛下放心，我们一定会保护王宫。", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使者向国王鞠躬，说：“陛下，我从远方来。”", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老大臣对皇帝说：“陛下，这件事很重要。”", "target_word": "陛下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "对国王、皇帝等君主的尊称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陛下", "is_correct": true, "explanation": "“陛下”是对君主的尊称，大臣跪着对君主说话，符合句意。"}, {"text": "妈妈", "is_correct": false, "explanation": "语义：大臣跪着对君主说话，不会称呼君主为“妈妈”。"}, {"text": "同学", "is_correct": false, "explanation": "语义：“同学”是平辈称呼，与大臣跪奏君主的情境不符。"}, {"text": "孩子", "is_correct": false, "explanation": "语域：“孩子”是随意的口语称呼，与“陛下”所用的书面尊称不符。"}], "explanations": {"陛下": "“陛下”是对君主的尊称，大臣跪着对君主说话，符合句意。", "妈妈": "语义：大臣跪着对君主说话，不会称呼君主为“妈妈”。", "同学": "语义：“同学”是平辈称呼，与大臣跪奏君主的情境不符。", "孩子": "语域：“孩子”是随意的口语称呼，与“陛下”所用的书面尊称不符。"}, "sentence_index": 0, "correct_answer": "陛下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸生日那天，我们都对他说：“祝陛下生日快乐！”", "explanation": "这里应该用〈您〉。“陛下”只尊称君主，祝父亲生日应说“您”。"}, {"text": "妈妈对我说：“陛下，作业写完了吗？”", "explanation": "这里应该用〈宝贝〉。“陛下”只尊称君主，对孩子应说“宝贝”。"}, {"text": "老板走进办公室，大家都说：“陛下好！”", "explanation": "这里应该用〈您〉。“陛下”只尊称君主，称呼公司老板应说“您好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陛下", "is_correct": true, "explanation": "“陛下”是对君主的尊称，大臣这样叫皇帝才合适。"}, {"text": "老板", "is_correct": false, "explanation": "语义：“老板”是商业场合的称呼，不用于称呼皇帝。"}, {"text": "教授", "is_correct": false, "explanation": "语义：“教授”是学术职称，与皇帝的身份不符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：皇帝不是厨师，大臣不会这样称呼他。"}], "explanations": {"陛下": "“陛下”是对君主的尊称，大臣这样叫皇帝才合适。", "老板": "语义：“老板”是商业场合的称呼，不用于称呼皇帝。", "教授": "语义：“教授”是学术职称，与皇帝的身份不符。", "厨师": "语义：皇帝不是厨师，大臣不会这样称呼他。"}, "sentence_index": 6, "correct_answer": "陛下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座宫殿的陛下很高，要爬很多台阶。", "explanation": "这里应该用〈台阶〉。“陛”古义指宫殿的台阶，但“陛下”现在只作君主的尊称，不指台阶。"}, {"text": "操场上来了很多陛下。", "explanation": "这里应该用〈同学〉。“陛下”只用于君主，操场上的学生应说“同学”。"}, {"text": "他一进门就大声说：“我是陛下，大家都让开！”", "explanation": "这里应该用〈本人〉。“陛下”是别人对君主的尊称，不能用来自称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大臣对皇帝说：“陛下的，边境来信了。”", "corrected_sentence": "大臣对皇帝说：“陛下，边境来信了。”", "error_description": "“陛下”作称呼时后面不加“的”，应直接用逗号连接，即“陛下，……”。错误在“的”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "侍卫跪下说：“陛下们，请您保重身体。”", "corrected_sentence": "侍卫跪下说：“陛下，请您保重身体。”", "error_description": "“陛下”是对单一君主的尊称，不能加“们”表示复数，错误在“们”，应改为“陛下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
