INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "不若的意思是不如，说这样做比那样做更好。", "primary_collocate": null, "pronunciation": "bù ruò", "ipa": "pu˥˩ ʐuo˥˩", "syllable_count": 2, "sentences": [{"text": "与其生气，不若笑一笑。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车太挤，不若走路去学校。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其买新手机，不若把旧的修好。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想了一天，不若马上去做。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其看电视，不若出去跑跑步。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得这么大，不若明天再去。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直等下去，不若换个办法。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其说得多，不若做得好。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人去太无聊，不若叫上朋友。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其点外卖，不若自己煮碗面。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "与其……不若……", "label": "固定搭配"}], "register": "书面", "sense_fingerprint": "不若：不如，说这样做比那样做更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11634477-b3a7-490b-8534-8c42b7d88671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，与“与其生气”的比较关系不符。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与后面的“但/却”呼应，不能与“与其”配合。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进，与“与其……”表示的比较关系不符。"}, {"text": "不若", "is_correct": true, "explanation": "正确：“与其……不若……”表示比较，笑一笑比生气更好，符合句意。"}], "explanations": {"因此": "语义：“因此”表示因果，与“与其生气”的比较关系不符。", "虽然": "搭配：“虽然”要与后面的“但/却”呼应，不能与“与其”配合。", "而且": "语义：“而且”表示递进，与“与其……”表示的比较关系不符。", "不若": "正确：“与其……不若……”表示比较，笑一笑比生气更好，符合句意。"}, "sentence_index": 0, "correct_answer": "不若"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想去，不若没有时间。", "explanation": "这里应该用〈但是〉。但是表示转折，不若表示比较，不能用来表示转折。"}, {"text": "他努力练习，不若提高了成绩。", "explanation": "这里应该用〈从而〉。从而引出结果，不若表示比较，不能引出结果。"}, {"text": "他说了很多，不若没有做。", "explanation": "这里应该用〈却〉。却是副词，表示转折，不若是连词，表示比较，不能用在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，而这里是比较两种做法、选择更好的一种，不能用“尽管”。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”要与后面的“就”呼应，这里没有条件关系，不能用“只要”。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”表示递进补充，与“一直等下去”的句意不协调。"}, {"text": "不若", "is_correct": true, "explanation": "正确：“一直等下去，不若换个办法”表示比较，继续等不如换办法，符合句意。"}], "explanations": {"尽管": "语义：“尽管”表示让步，而这里是比较两种做法、选择更好的一种，不能用“尽管”。", "只要": "搭配：“只要”要与后面的“就”呼应，这里没有条件关系，不能用“只要”。", "况且": "语义：“况且”表示递进补充，与“一直等下去”的句意不协调。", "不若": "正确：“一直等下去，不若换个办法”表示比较，继续等不如换办法，符合句意。"}, "sentence_index": 6, "correct_answer": "不若"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天很冷，不若我穿了厚衣服。", "explanation": "这里应该用〈所以〉。所以表示因果，不若表示比较，不能引出结果。"}, {"text": "他很努力，不若很快就成功了。", "explanation": "这里应该用〈因此〉。因此表示因果，不若表示比较，不能引出结果。"}, {"text": "我们去了公园，不若拍了照。", "explanation": "这里应该用〈并且〉。并且表示并列，不若表示比较，不能用在这两个动作的并列关系中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "与其熬夜，不若的早点睡。", "corrected_sentence": "与其熬夜，不若早点睡。", "error_description": "助词错误：“不若”是连词，后面不能加“的”，应说“不若早点睡”，不能说“不若的早点睡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "与其等待，不若了主动联系他。", "corrected_sentence": "与其等待，不若主动联系他。", "error_description": "体貌错误：“不若”是连词，后面不能加“了”，应说“不若主动联系他”，不能说“不若了主动联系他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
