INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92653, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指定是先说好是哪一个。", "primary_collocate": null, "pronunciation": "zhǐ dìng", "ipa": "ʈʂɨ˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师指定小李回答这个问题。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在指定的地方等我。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，他指定了一个人当队长。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店允许顾客指定一位朋友代为取货。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校指定我代表班级参加比赛。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想要哪个？请你指定一个。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理指定小王来接客人。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把东西放在他指定的桌子上。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人指定要靠窗的座位。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们要在指定的教室考试。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指定了", "label": "完成体"}, {"form": "指定过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "事先说明选定某个人或某个地方、东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4c1239-4184-41d0-a500-af91482a0938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92653, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指定", "is_correct": true, "explanation": "“指定”表示选定小李承担任务，符合句意。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”的对象是文件、内容等，不能接“小李回答这个问题”。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求食物做宾语，无法以“小李回答这个问题”为宾语。"}, {"text": "擦", "is_correct": false, "explanation": "配价：“擦”的对象是物体表面，不能以“小李回答这个问题”为宾语。"}], "explanations": {"指定": "“指定”表示选定小李承担任务，符合句意。", "删除": "搭配：“删除”的对象是文件、内容等，不能接“小李回答这个问题”。", "吃": "配价：“吃”要求食物做宾语，无法以“小李回答这个问题”为宾语。", "擦": "配价：“擦”的对象是物体表面，不能以“小李回答这个问题”为宾语。"}, "sentence_index": 0, "correct_answer": "指定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我指定周末去爬山。", "explanation": "这里应该用〈决定〉。指定是从若干人或事物中选定，或由有关方面规定，不用于个人自己拿主意。"}, {"text": "警察指定他是小偷。", "explanation": "这里应该用〈认定〉。指定指事先选定或规定，不用来对事实作出判断。"}, {"text": "老师指定了我的错误。", "explanation": "这里应该用〈指出〉。指定是事先选定或规定，不能用来指出已经存在的错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92653, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指定", "is_correct": true, "explanation": "“指定”表示经理选定小王去接客人，符合句意。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”指给动物或幼小的生命进食，与“经理”、“接客人”不搭。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”的对象是物品或作品，不能用于安排一个人去接客人。"}, {"text": "寄存", "is_correct": false, "explanation": "搭配：“寄存”通常指存放物品，不能用于选定人去接客人。"}], "explanations": {"指定": "“指定”表示经理选定小王去接客人，符合句意。", "喂养": "语义：“喂养”指给动物或幼小的生命进食，与“经理”、“接客人”不搭。", "收藏": "语义：“收藏”的对象是物品或作品，不能用于安排一个人去接客人。", "寄存": "搭配：“寄存”通常指存放物品，不能用于选定人去接客人。"}, "sentence_index": 6, "correct_answer": "指定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天指定碗。", "explanation": "这里应该用〈洗〉。指定是选定或规定，不表示清洗，“我每天指定碗”不通。"}, {"text": "他指定了老师的批评。", "explanation": "这里应该用〈接受〉。指定的对象是人或事物的选定，不能与“批评”搭配表示接受。"}, {"text": "我指定明年学开车。", "explanation": "这里应该用〈打算〉。指定是选定某人或某物，不用于说自己的计划，应说“我打算明年学开车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师指定着小王负责这次活动。", "corrected_sentence": "老师指定小王负责这次活动。", "error_description": "“指定”是一次性完成的动作，不能加“着”表示持续，应去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把新的教室指定考场。", "corrected_sentence": "学校把新的教室指定为考场。", "error_description": "“把……指定为……”是固定结构，表示把某物确定为某种用途，这里漏掉了“为”，应说“指定为考场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
