INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92655, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92655, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "随之是跟着前面的事马上有了后面的事。", "primary_collocate": null, "pronunciation": "suí zhī", "ipa": "sweɪ̯˧˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "门一开，一阵冷风随之吹了进来。", "target_word": "随之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一灭，屋里随之安静了下来。", "target_word": "随之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说完话，大家的掌声随之响起。", "target_word": "随之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车开动了，站台上的哭声随之传来。", "target_word": "随之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闪电一亮，雷声随之响起。", "target_word": "随之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一声枪响，鸟儿随之飞上了天空。", "target_word": "随之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一松手，书随之掉在了地上。", "target_word": "随之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束了，欢呼声随之响了起来。", "target_word": "随之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板点了点头，大家随之松了口气。", "target_word": "随之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳落山，天色随之黑了下来。", "target_word": "随之", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "前一件事刚发生，后一件事马上发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9d6783f-ace1-4265-9d14-fc3a3d5379b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92655, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随之", "is_correct": true, "explanation": "随之：门一开，冷风紧接着吹进来，与“随之”表示紧随前事的意思一致。"}, {"text": "迟迟", "is_correct": false, "explanation": "语义：“迟迟”表示拖延很久，与“门一开”就立刻发生的结果不符。"}, {"text": "几乎", "is_correct": false, "explanation": "语义：“几乎”表示差一点没有发生，与“门一开”后风确实吹进来的结果矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”表示过去的经历，与门开后即时发生的事情不符。"}], "explanations": {"随之": "随之：门一开，冷风紧接着吹进来，与“随之”表示紧随前事的意思一致。", "迟迟": "语义：“迟迟”表示拖延很久，与“门一开”就立刻发生的结果不符。", "几乎": "语义：“几乎”表示差一点没有发生，与“门一开”后风确实吹进来的结果矛盾。", "曾经": "体貌：“曾经”表示过去的经历，与门开后即时发生的事情不符。"}, "sentence_index": 0, "correct_answer": "随之"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题很简单，他随之哭了起来。", "explanation": "这里应该用〈却〉。随之表示后一件事是前一件事马上引出的结果，“题目简单”不会引出“哭”，两件事没有这种联系，表示转折应用〈却〉。"}, {"text": "他虽然很累，随之继续工作了。", "explanation": "这里应该用〈仍然〉。随之表示后一件事是随前一件事的变化而发生的，“很累”与“继续工作”不是承接关系，表示尽管如此仍然做某事应用〈仍然〉。"}, {"text": "夜深了，随之我们吃了晚饭。", "explanation": "这里应该用〈然后〉。随之表示后一件事是随前一件事的变化而发生的，“夜深了”与“吃晚饭”之间没有这种联系，只是先后顺序，应用〈然后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随之", "is_correct": true, "explanation": "随之：书跟着松手而掉在地上，前后顺承，与“随之”的意思一致。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，与“一松手”就必然掉落的结果不符。"}, {"text": "从来", "is_correct": false, "explanation": "语法：“从来”多用于否定或表示一贯如此，不能修饰“一松手”后马上发生的一次性结果“掉在了地上”。"}, {"text": "渐渐", "is_correct": false, "explanation": "搭配：“渐渐”指逐步进行，与“一松手”这种瞬间动作不搭配。"}], "explanations": {"随之": "随之：书跟着松手而掉在地上，前后顺承，与“随之”的意思一致。", "偶尔": "语义：“偶尔”表示有时，与“一松手”就必然掉落的结果不符。", "从来": "语法：“从来”多用于否定或表示一贯如此，不能修饰“一松手”后马上发生的一次性结果“掉在了地上”。", "渐渐": "搭配：“渐渐”指逐步进行，与“一松手”这种瞬间动作不搭配。"}, "sentence_index": 6, "correct_answer": "随之"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩很好，他随之退学了。", "explanation": "这里应该用〈反而〉。随之表示后一件事是前一件事引出的结果，“成绩好”不会引出“退学”，两件事正好相反，应用〈反而〉。"}, {"text": "他在家看书，随之下起了大雨。", "explanation": "这里应该用〈忽然〉。随之表示后一件事是随前一件事的变化而发生的，看书与下雨之间没有这种联系，只是先后出现，应用〈忽然〉。"}, {"text": "他不喜欢吃辣，随之点了一碗辣椒。", "explanation": "这里应该用〈偏偏〉。随之表示后一件事是前一件事引出的结果，“不喜欢吃辣”不会引出“点辣椒”，两件事相反，应用〈偏偏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车子一停，乘客随之地下了车。", "corrected_sentence": "车子一停，乘客随之下了车。", "error_description": "错误：副词“随之”后面不能直接加助词“地”。正确：应为“乘客随之下了车”，“随之”后直接接动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一抬手，灯随之的亮了。", "corrected_sentence": "他一抬手，灯随之亮了。", "error_description": "错误：副词“随之”后面不能加“的”。正确：应为“灯随之亮了”，“随之”后直接接动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不过如此是说一件事没有想的那么好，也没有想的那么难。", "primary_collocate": null, "pronunciation": "bú guò rú cǐ", "ipa": "pu˧˥ kuɔ˥˩ ʐu˧˥ tsʰɹ̩˨˩˦", "syllable_count": 4, "sentences": [{"text": "我以为汉语考试很难，其实不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听别人说骑马很可怕，试了以后觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜看起来很难做，做完觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机我以前很怕，现在觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个大学很有名，进去看了看，不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说工作很累，我做了一个月，不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说搬家很麻烦，我搬完觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次住五星酒店，我觉得也不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怕这次比赛，对手的水平不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说学游泳很难，我学了几天，不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "事情没想的那么好或那么难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5f01a3f-0c54-4133-9b25-173d415a41c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不过如此", "is_correct": true, "explanation": "“不过如此”表示事情没有想象的那么难，与前句“我以为很难”形成转折，符合语境。"}, {"text": "很冷", "is_correct": false, "explanation": "语义：“冷”说的是温度，用来形容考试的难易说不通。"}, {"text": "很圆", "is_correct": false, "explanation": "搭配：“圆”不用来描述考试的难易，与“其实”后的评价不搭。"}, {"text": "很瘦", "is_correct": false, "explanation": "体貌：“瘦”描述人的身材，不能用来评价考试。"}], "explanations": {"不过如此": "“不过如此”表示事情没有想象的那么难，与前句“我以为很难”形成转折，符合语境。", "很冷": "语义：“冷”说的是温度，用来形容考试的难易说不通。", "很圆": "搭配：“圆”不用来描述考试的难易，与“其实”后的评价不搭。", "很瘦": "体貌：“瘦”描述人的身材，不能用来评价考试。"}, "sentence_index": 0, "correct_answer": "不过如此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手的嗓音真是不过如此，观众都听得入迷。", "explanation": "褒贬误用：这里把“不过如此”当成了夸奖，但它表示平常，与“听得入迷”的赞美相矛盾。"}, {"text": "这部电影太感人了，我觉得不过如此，看完哭了很久。", "explanation": "这里应该用〈感人〉。「不过如此」表示没有想的那么好，与「看完哭了很久」矛盾。"}, {"text": "这次考试比我想的难多了，我觉得不过如此。", "explanation": "这里应该用〈很难〉。「不过如此」表示没有想的那么难，与「比我想的难多了」正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不过如此", "is_correct": true, "explanation": "“不过如此”表示搬完后觉得并没有想象的那么麻烦，与前句“搬家很麻烦”形成转折，符合语境。"}, {"text": "很甜", "is_correct": false, "explanation": "语义：“甜”说的是味道，与搬家的感受无关。"}, {"text": "很胖", "is_correct": false, "explanation": "体貌：“胖”描述人的体型，不能用来形容搬家后的感觉。"}, {"text": "很亮", "is_correct": false, "explanation": "搭配：“亮”多描述光线或颜色，用来说搬完后的感受搭配不当。"}], "explanations": {"不过如此": "“不过如此”表示搬完后觉得并没有想象的那么麻烦，与前句“搬家很麻烦”形成转折，符合语境。", "很甜": "语义：“甜”说的是味道，与搬家的感受无关。", "很胖": "体貌：“胖”描述人的体型，不能用来形容搬家后的感觉。", "很亮": "搭配：“亮”多描述光线或颜色，用来说搬完后的感受搭配不当。"}, "sentence_index": 6, "correct_answer": "不过如此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师的讲解很精彩，学生们却都觉得不过如此，频频鼓掌。", "explanation": "褒贬误用：“不过如此”只表示平常，这里却与“很精彩”和“频频鼓掌”相矛盾，把它当成了赞美。"}, {"text": "这道题的难度不过如此，我绞尽脑汁也做不出来。", "explanation": "这里应该用〈棘手〉。“不过如此”表示没有想的那么难，与“绞尽脑汁也做不出来”正相反。"}, {"text": "这份作业不过如此，我们熬了一整夜。", "explanation": "这里应该用〈很难〉。「不过如此」表示没有想的那么难，与「熬了一整夜」的辛苦正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次体检的流程我以前很担心，走完一遍觉得很不过如此。", "corrected_sentence": "这次体检的流程我以前很担心，走完一遍觉得不过如此。", "error_description": "错误形式：“很不过如此”；正确形式：“不过如此”。“不过如此”已经表示平常，前面不能加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新搬的小区环境我原来很担心，住了几天觉得很不过如此。", "corrected_sentence": "新搬的小区环境我原来很担心，住了几天觉得不过如此。", "error_description": "错误形式：“很不过如此”；正确形式：“不过如此”。“不过如此”本身已表示没有想的那么好或那么难，前面不能加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
