INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92660, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "移动较重或较大的物体，使其离开原来位置；也指迁移。", "primary_collocate": null, "pronunciation": "bān", "ipa": "pan˥", "syllable_count": 1, "sentences": [{"text": "他一个人搬了一张大桌子。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子太重，我搬不动。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我把沙发搬到楼上。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在搬新买的冰箱。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们下个月要搬到新家去。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬着一个大箱子走进了教室。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生把椅子搬出去。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时搬过很多石头。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李搬到北京以后，工作很忙。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块大石头两个人都搬不起来。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搬了", "label": "体标（了）"}, {"form": "搬着", "label": "体标（着）"}, {"form": "搬过", "label": "体标（过）"}, {"form": "搬运", "label": "复合"}], "register": "中性", "sense_fingerprint": "移动较重较大的物体离开原位，也指迁居", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f149c945-cf41-413d-b166-ecfc5601d7e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_vali