INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92661, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人民法院是一个地方，里面的法官来判断谁对谁错。", "primary_collocate": null, "pronunciation": "rén mín fǎ yuàn", "ipa": "ʐən˧˥ min˧˥ fa˨˩˦ ɥɛn˥˩", "syllable_count": 4, "sentences": [{"text": "人民法院在市中心，离地铁站很近。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐车去人民法院，今天要开庭。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民法院门口站着两位保安。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座人民法院是去年新建的。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民法院的大楼又高又新。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早上八点就到了人民法院。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民法院旁边有一家小饭店。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我从人民法院门前走过。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民法院里的法官正在开庭。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去人民法院怎么走？", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "正式", "sense_fingerprint": "审案的法官工作的地方，即法院的大楼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c571f81-6489-4741-8a61-f863fc462a95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人民法院", "is_correct": true, "explanation": "正确：“人民法院”指法院的大楼，可以位于市中心，离地铁站很近。"}, {"text": "法律", "is_correct": false, "explanation": "语义：法律是规范，不是可以位于市中心的地点。"}, {"text": "案件", "is_correct": false, "explanation": "语义：案件是事情，不能说它在市中心。"}, {"text": "判决", "is_correct": false, "explanation": "搭配：“判决”是裁判结果，一般不用“在市中心”“离地铁站近”来描述。"}], "explanations": {"人民法院": "正确：“人民法院”指法院的大楼，可以位于市中心，离地铁站很近。", "法律": "语义：法律是规范，不是可以位于市中心的地点。", "案件": "语义：案件是事情，不能说它在市中心。", "判决": "搭配：“判决”是裁判结果，一般不用“在市中心”“离地铁站近”来描述。"}, "sentence_index": 0, "correct_answer": "人民法院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人民法院昨天发烧了，去医院看了病。", "explanation": "此句把“人民法院”当成了会生病的人，但它指建筑，不会发烧、看病。"}, {"text": "人民法院这周末要去爬山，已经买好了登山鞋。", "explanation": "此句把“人民法院”当成了能去爬山、买鞋的人，但它指建筑，不能做这类人的动作。"}, {"text": "人民法院每天晚上都会在房间里做作业。", "explanation": "此句把“人民法院”当成了会做作业的学生，但它指建筑，不能做这类学习活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人民法院", "is_correct": true, "explanation": "正确：“人民法院”是建筑，可以有饭店在它旁边。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，不能有饭店在它旁边。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情是抽象的心理，不是有空间位置的地点。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“旁边”后面一般接地点或实体，不能接“名字”。"}], "explanations": {"人民法院": "正确：“人民法院”是建筑，可以有饭店在它旁边。", "时间": "语义：时间是抽象概念，不能有饭店在它旁边。", "感情": "语义：感情是抽象的心理，不是有空间位置的地点。", "名字": "搭配：“旁边”后面一般接地点或实体，不能接“名字”。"}, "sentence_index": 6, "correct_answer": "人民法院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人民法院昨天请朋友吃了晚饭。", "explanation": "此句把“人民法院”当成了能请客的人，但它指建筑，不能做“请客”这类人的动作。"}, {"text": "人民法院每天早上都去公园跑步。", "explanation": "此句把“人民法院”当成了会去公园跑步的人，但它指建筑，不能做这类人的运动。"}, {"text": "人民法院每天晚上都会在窗前唱歌，唱得很好听。", "explanation": "此句把“人民法院”当成了会唱歌的人，但它指建筑，不能做唱歌这类人的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骑车人民法院办事。", "corrected_sentence": "他骑车去人民法院办事。", "error_description": "错误：漏掉了动词“去”。“骑车去＋地点”中需要“去”，正确说法：他骑车去人民法院办事。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他常人民法院门口等朋友。", "corrected_sentence": "他常在人民法院门口等朋友。", "error_description": "错误：漏掉了介词“在”。“在＋地点”表示动作发生的地方，正确说法：他常在人民法院门口等朋友。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
