INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92664, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "引导事业前进的方向和总的原则。", "primary_collocate": null, "pronunciation": "fāng zhēn", "ipa": "faŋ˥ ʈʂən˥", "syllable_count": 2, "sentences": [{"text": "国家制定了新的教育方针。", "target_word": "方针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项方针让工厂越办越好。", "target_word": "方针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院一直坚持为病人服务的方针。", "target_word": "方针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府的基本方针是发展经济。", "target_word": "方针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党的方针对国家的发展很重要。", "target_word": "方针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条方针指引着公司的事业前进。", "target_word": "方针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把环保作为长期的方针。", "target_word": "方针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会上，市长讲了城市发展的方针。", "target_word": "方针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的外交方针一直没有变。", "target_word": "方针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改变方针以后，企业的情况好多了。", "target_word": "方针", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "方针政策", "label": "复合"}], "register": "书面", "sense_fingerprint": "名词：引导事业前进的方向和总原则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '465f594a-3aae-426d-a776-e288a89e9985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "方针", "is_correct": true, "explanation": "fāng zhēn 即“方针”，指引事业前进的方向和总原则。"}, {"text": "方阵", "is_correct": false, "explanation": "fāng zhèn 只有第二音节声调不同（第四声），意思是“方形的队列”。"}, {"text": "防震", "is_correct": false, "explanation": "fáng zhèn 两个音节的声调都与 fāng zhēn 不同，意思是“防止震动”。"}, {"text": "仿真", "is_correct": false, "explanation": "fǎng zhēn 只有第一音节声调不同（第三声），意思是“模拟真实”。"}], "explanations": {"方针": "fāng zhēn 即“方针”，指引事业前进的方向和总原则。", "方阵": "fāng zhèn 只有第二音节声调不同（第四声），意思是“方形的队列”。", "防震": "fáng zhèn 两个音节的声调都与 fāng zhēn 不同，意思是“防止震动”。", "仿真": "fǎng zhēn 只有第一音节声调不同（第三声），意思是“模拟真实”。"}, "sentence_index": null, "correct_answer": "方针"}, "level_3": {"options": [{"text": "方针", "is_correct": true, "explanation": "“教育方针”是固定搭配，指教育事业的大方向和总原则，与“制定”搭配自然。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“教育窗户”说不通，窗户不属于可以制定的教育内容。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“制定”不带“饭菜”这类具体事物，“教育饭菜”不成词组。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能与“教育”组合成制定的对象，句子无法成立。"}], "explanations": {"方针": "“教育方针”是固定搭配，指教育事业的大方向和总原则，与“制定”搭配自然。", "窗户": "语义：“教育窗户”说不通，窗户不属于可以制定的教育内容。", "饭菜": "搭配：“制定”不带“饭菜”这类具体事物，“教育饭菜”不成词组。", "颜色": "语义：颜色不能与“教育”组合成制定的对象，句子无法成立。"}, "sentence_index": 0, "correct_answer": "方针"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做饭的第一方针是洗菜。", "explanation": "这里应该用〈步骤〉。方针是总的方向，做饭时先后做什么的具体顺序要用步骤。"}, {"text": "我们选了一条平坦的方针去山顶。", "explanation": "这里应该用〈路线〉。方针是抽象的原则，去山顶的具体路径要用路线。"}, {"text": "这道汤的方针很简单，三步就能做好。", "explanation": "这里应该用〈做法〉。方针是总的方向，汤的具体做法才用“做法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方针", "is_correct": true, "explanation": "“作为长期的方针”指把环保当作长期遵循的大方向，语义通顺。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：“作为长期的衣服”说不通，衣服不是可以作为行动原则的东西。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭不能“作为长期的”指导性内容，句子不成立。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：“哥们儿”是口语，指朋友，与书面语的“作为……”结构不合。"}], "explanations": {"方针": "“作为长期的方针”指把环保当作长期遵循的大方向，语义通顺。", "衣服": "语义：“作为长期的衣服”说不通，衣服不是可以作为行动原则的东西。", "早饭": "语义：早饭不能“作为长期的”指导性内容，句子不成立。", "哥们儿": "语域：“哥们儿”是口语，指朋友，与书面语的“作为……”结构不合。"}, "sentence_index": 6, "correct_answer": "方针"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛是个难得的方针，别错过。", "explanation": "这里应该用〈机会〉。方针指总的方向和原则，比赛中难得的好时机要用“机会”。"}, {"text": "他的方针很开朗，大家都喜欢和他聊天。", "explanation": "这里应该用〈性格〉。方针指总的方向和原则，说一个人开朗要用“性格”，不能用“方针”。"}, {"text": "他把方针送给了我，我很喜欢。", "explanation": "这里应该用〈礼物〉。方针是抽象的原则，不能拿来送人，送人的东西要用“礼物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项长期方针已经定下去了。", "corrected_sentence": "这项长期方针已经定下来了。", "error_description": "补语错误：“定下来”表示决定确定，“定下去”不能这样用，应为“定下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们改变了一棵方针，效果很好。", "corrected_sentence": "他们改变了一项方针，效果很好。", "error_description": "量词错误：“方针”应用“项”或“个”，“棵”只用于植物，不能用来数“方针”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92665, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92665, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92665, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "作死是明明很危险，还偏要去做，让自己倒霉。", "primary_collocate": null, "pronunciation": "zuò sǐ", "ipa": "tswo˥˩ sɨ˨˩", "syllable_count": 2, "sentences": [{"text": "明明下大雨，他还去河边玩，真是作死。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条路很危险，你别作死了。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不听劝，非要作死。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯还闯过去，这不是作死吗？", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再作死，小心被车撞。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明明不会游泳，他偏要下水，真作死。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别作死去碰那只大狗。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他天天熬夜喝酒，简直是作死。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有雪，他还爬，这就是作死。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要作死，快把刀放下。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "作死了", "label": "体标"}], "register": "口语", "sense_fingerprint": "明知危险却偏要做，结果让自己倒霉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92665, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作死", "is_correct": true, "explanation": "作死：明知危险还偏要做，与“真是”搭配，用来批评这种行为。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是悠闲的活动，不能用来批评在下大雨时去河边玩的行为。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：旅行是正常的出行，“真是旅行”不能表达对危险行为的批评。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与去河边玩的行为无关，「真是睡觉」讲不通，无法用来批评这种危险行为。"}], "explanations": {"作死": "作死：明知危险还偏要做，与“真是”搭配，用来批评这种行为。", "散步": "语义：散步是悠闲的活动，不能用来批评在下大雨时去河边玩的行为。", "旅行": "语义：旅行是正常的出行，“真是旅行”不能表达对危险行为的批评。", "睡觉": "语义：睡觉与去河边玩的行为无关，「真是睡觉」讲不通，无法用来批评这种危险行为。"}, "sentence_index": 0, "correct_answer": "作死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为了救落水的孩子，作死地跳进了河里。", "explanation": "这里应该用〈勇敢〉。作死含贬义，指明知危险还偏要做、自找倒霉；救人是出于善意的行为，应该用〈勇敢〉。"}, {"text": "探险队决定作死穿越那片沙漠。", "explanation": "这里应该用〈冒险〉。探险队有计划、有目的地行动，不是自找倒霉，应该用〈冒险〉。"}, {"text": "她为了考上大学，作死地复习到凌晨。", "explanation": "这里应该用〈拼命〉。作死指自寻死路，含贬义；“拼命复习”是努力的说法，不带贬义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作死", "is_correct": true, "explanation": "作死：明知危险还去碰，与“别”搭配，用来表示劝阻。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”与“去碰那只大狗”不能连用，句子表示的是危险行为的劝阻。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班与去碰大狗毫无关联，劝阻的语气讲不通。"}, {"text": "复习", "is_correct": false, "explanation": "语义：复习是学习活动，不是危险行为，不能用来劝阻去碰狗。"}], "explanations": {"作死": "作死：明知危险还去碰，与“别”搭配，用来表示劝阻。", "睡觉": "搭配：“睡觉”与“去碰那只大狗”不能连用，句子表示的是危险行为的劝阻。", "上班": "语义：上班与去碰大狗毫无关联，劝阻的语气讲不通。", "复习": "语义：复习是学习活动，不是危险行为，不能用来劝阻去碰狗。"}, "sentence_index": 6, "correct_answer": "作死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她很作死，主动帮老人提包。", "explanation": "这里应该用〈热心〉。作死含贬义，指自找倒霉；主动帮老人提包是善意的行为，不能用“作死”形容。"}, {"text": "他很作死，过马路前总会先看红灯。", "explanation": "这里应该用〈谨慎〉。作死指明知危险还偏要做，与过马路前先看红灯的态度正好相反。"}, {"text": "他很作死，每次考试前都会认真复习。", "explanation": "这里应该用〈认真〉。作死指自找倒霉，含贬义；“认真复习”是正面的学习态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他作死得往前冲，大家都劝不住。", "corrected_sentence": "他作死地往前冲，大家都劝不住。", "error_description": "“作死”后修饰动词“往前冲”的应该用“地”，写成“得”是错的。“得”用于动词后作补语，“作死地”是状语，应写作“作死地往前冲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被作死，怪不了别人。", "corrected_sentence": "他是自己作死，怪不了别人。", "error_description": "“作死”是自己找的麻烦，不能用“被”表示被动。应说“是自己作死”，不说“被作死”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
