INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92666, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（口语）自找麻烦或危险，自寻死路。", "primary_collocate": null, "pronunciation": "zuò sǐ", "ipa": "tswo˥˩ sɨ˨˩", "syllable_count": 2, "sentences": [{"text": "你惹他干什么，这不是自己作死吗？", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正生气，你还去说，真会作死。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是作死，所以老出问题。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别作死，这件事没人帮你。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是再这样作死，我不管你了。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没做作业还玩游戏，你就作死吧。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他作死去惹那群人，结果被打了。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不想作死，就听医生的话。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在作死，朋友都走了。", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚还去山里，你是想作死吗？", "target_word": "作死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "作死了", "label": "体标"}], "register": "口语", "sense_fingerprint": "自己招惹麻烦或危险，自寻死路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作死", "is_correct": true, "explanation": "作死：自己招惹麻烦，自找倒霉，与“自己”搭配，用来责备。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌是娱乐活动，与“你惹他干什么”的责备语境不相干。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是悠闲的活动，与“惹他”带来的麻烦毫无关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与对他人惹事的责备无关，「这不是自己吃饭吗」讲不通。"}], "explanations": {"作死": "作死：自己招惹麻烦，自找倒霉，与“自己”搭配，用来责备。", "唱歌": "语义：唱歌是娱乐活动，与“你惹他干什么”的责备语境不相干。", "散步": "语义：散步是悠闲的活动，与“惹他”带来的麻烦毫无关系。", "吃饭": "语义：吃饭与对他人惹事的责备无关，「这不是自己吃饭吗」讲不通。"}, "sentence_index": 0, "correct_answer": "作死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中作死，最终拿到了冠军。", "explanation": "这里应该用〈拼搏〉。作死指自招麻烦、自寻死路，含贬义，不能形容认真争取胜利的过程。"}, {"text": "他做事很作死，每一步都仔细检查。", "explanation": "这里应该用〈谨慎〉。作死指明知危险还偏要做，与“每一步都仔细检查”的态度正好相反。"}, {"text": "邻居很作死，常来看望我们。", "explanation": "这里应该用〈关心〉。作死含贬义，指自找麻烦，不能用来形容别人对我们的关心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作死", "is_correct": true, "explanation": "作死：自寻死路，去惹不该惹的人，所以结果被打。"}, {"text": "帮忙", "is_correct": false, "explanation": "搭配：“帮忙”是帮助他人，不能用来引出“去惹那群人”的行为。"}, {"text": "请客", "is_correct": false, "explanation": "语义：请客是款待他人，与“去惹那群人”、结果被打不相符。"}, {"text": "逛街", "is_correct": false, "explanation": "语义：逛街是悠闲的购物活动，与“惹那群人”、结果被打讲不通。"}], "explanations": {"作死": "作死：自寻死路，去惹不该惹的人，所以结果被打。", "帮忙": "搭配：“帮忙”是帮助他人，不能用来引出“去惹那群人”的行为。", "请客": "语义：请客是款待他人，与“去惹那群人”、结果被打不相符。", "逛街": "语义：逛街是悠闲的购物活动，与“惹那群人”、结果被打讲不通。"}, "sentence_index": 6, "correct_answer": "作死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天都作死练琴，成绩进步很快。", "explanation": "这里应该用〈努力〉。作死含贬义，指自寻死路；“努力练琴”是正当的学习态度，与“成绩进步”相符。"}, {"text": "他待人很作死，从不惹事。", "explanation": "这里应该用〈规矩〉。作死指自找麻烦，与“从不惹事”的为人风格正好相反。"}, {"text": "我们作死地为远方来的朋友准备了丰盛的晚餐。", "explanation": "这里应该用〈热情〉。作死指自找麻烦、自寻死路，含贬义，不能用来形容热情地招待朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明知危险还作死得往上爬。", "corrected_sentence": "他明知危险还作死地往上爬。", "error_description": "“作死”后修饰“往上爬”的应该用“地”，写成“得”是错的。“得”用在动词后作补语，“作死地”是状语，应写作“作死地往上爬”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被作死的，谁也拦不住。", "corrected_sentence": "他是自己作死的，谁也拦不住。", "error_description": "“被”表被动，但“作死”是自己找的麻烦，不能被动。应说“是自己作死的”，不说“被作死的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
