INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几天以前；前几天。", "primary_collocate": null, "pronunciation": "rì qián", "ipa": "ʐɨ˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "日前，市政府发布了一条新消息。", "target_word": "日前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他日前从北京回来了。", "target_word": "日前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日前下了一场大雨，路上到处是水。", "target_word": "日前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司日前宣布，明年会开新店。", "target_word": "日前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我日前收到了朋友寄来的信。", "target_word": "日前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日前，这个城市开了一家大书店。", "target_word": "日前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老师日前去了上海开会。", "target_word": "日前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者日前采访了这位运动员。", "target_word": "日前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日前天气很冷，现在已经暖和了。", "target_word": "日前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她日前在网上买了一台电脑。", "target_word": "日前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "日前：几天以前，前几天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ca222-7212-4bdc-9eea-f9ef5dd8b36e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92668, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "热钱", "is_correct": false, "explanation": "rè 与 rì 韵母不同（e/i），声调相同，意思是“热钱”，指短期流入的游资。"}, {"text": "日前", "is_correct": true, "explanation": "rì qián 指几天以前，是本题的正确答案。"}, {"text": "利钱", "is_correct": false, "explanation": "lì 与 rì 声母不同（l/r），声调相同，意思是“利息”。"}, {"text": "日浅", "is_correct": false, "explanation": "rì qiǎn 第二个字是第三声，与 qián（第二声）声调不同，意思是“时日不长”。"}], "explanations": {"热钱": "rè 与 rì 韵母不同（e/i），声调相同，意思是“热钱”，指短期流入的游资。", "日前": "rì qián 指几天以前，是本题的正确答案。", "利钱": "lì 与 rì 声母不同（l/r），声调相同，意思是“利息”。", "日浅": "rì qiǎn 第二个字是第三声，与 qián（第二声）声调不同，意思是“时日不长”。"}, "sentence_index": null, "correct_answer": "日前"}, "level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“发布了”表示已完成的动作矛盾。"}, {"text": "将来", "is_correct": false, "explanation": "体貌：“将来”指以后，与“发布了”的完成体不一致。"}, {"text": "日前", "is_correct": true, "explanation": "正确：“日前”指几天以前，与“发布了”的已完成事件相符。"}, {"text": "后天", "is_correct": false, "explanation": "语义：“后天”指两天之后，与“发布了”的已完成动作矛盾。"}], "explanations": {"明天": "语义：“明天”指将来，与“发布了”表示已完成的动作矛盾。", "将来": "体貌：“将来”指以后，与“发布了”的完成体不一致。", "日前": "正确：“日前”指几天以前，与“发布了”的已完成事件相符。", "后天": "语义：“后天”指两天之后，与“发布了”的已完成动作矛盾。"}, "sentence_index": 0, "correct_answer": "日前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事日前会有结果。", "explanation": "这里应该用〈日后〉。日前指几天以前，不能用于将来才会发生的事。"}, {"text": "我爷爷日前出生在北京。", "explanation": "这里应该用〈很多年前〉。日前只指几天以前，不能用于出生这种很久以前的一次性事件。"}, {"text": "这座老房子日前建于明朝。", "explanation": "这里应该用〈几百年前〉。日前只指几天以前，不能用于明朝这样遥远的年代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92668, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事前", "is_correct": false, "explanation": "shì 与 rì 声母不同（sh/r），声调相同，意思是“事先”。"}, {"text": "史前", "is_correct": false, "explanation": "shǐ 与 rì 声母、声调都不同（sh/r，第三声/第四声），意思是“有文字记载以前的时代”。"}, {"text": "日前", "is_correct": true, "explanation": "rì qián 指几天以前，是本题的正确答案。"}, {"text": "日见", "is_correct": false, "explanation": "rì jiàn 第二个字声母是 j，不是 q，意思是“一天比一天更加”。"}], "explanations": {"事前": "shì 与 rì 声母不同（sh/r），声调相同，意思是“事先”。", "史前": "shǐ 与 rì 声母、声调都不同（sh/r，第三声/第四声），意思是“有文字记载以前的时代”。", "日前": "rì qián 指几天以前，是本题的正确答案。", "日见": "rì jiàn 第二个字声母是 j，不是 q，意思是“一天比一天更加”。"}, "sentence_index": null, "correct_answer": "日前"}, "level_3": {"options": [{"text": "下周", "is_correct": false, "explanation": "语义：“下周”指未来一周，与“去了”表示已完成的动作矛盾。"}, {"text": "日前", "is_correct": true, "explanation": "正确：“日前”指几天以前，与“去了”的已完成动作相符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指未来的一年，与“去了”的已发生动作矛盾。"}, {"text": "今后", "is_correct": false, "explanation": "体貌：“今后”表示以后的时间，与“去了”的完成体不一致。"}], "explanations": {"下周": "语义：“下周”指未来一周，与“去了”表示已完成的动作矛盾。", "日前": "正确：“日前”指几天以前，与“去了”的已完成动作相符。", "明年": "语义：“明年”指未来的一年，与“去了”的已发生动作矛盾。", "今后": "体貌：“今后”表示以后的时间，与“去了”的完成体不一致。"}, "sentence_index": 6, "correct_answer": "日前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们日前认识了十年。", "explanation": "这里应该用〈已经〉。日前只指几天以前，不能与“认识了十年”这样的长时段搭配。"}, {"text": "他日前在唐朝做过官。", "explanation": "这里应该用〈一千多年前〉。日前只指几天以前，不能用于唐朝这样遥远的时代。"}, {"text": "这所寺庙日前已有三百年的历史。", "explanation": "这里应该用〈目前〉。日前只指几天以前，不能与“已有三百年的历史”这样表示现状的说法搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小明的日前搬到了新的公寓。", "corrected_sentence": "小明日前搬到了新的公寓。", "error_description": "错误：时间词“日前”作状语，前面不能加定语标记“的”，“小明的日前搬到了”不通。正确应为“小明日前搬到了新的公寓。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在日前在医院见到了老同学。", "corrected_sentence": "他日前在医院见到了老同学。", "error_description": "错误：时间词“日前”前多加了介词“在”。时间词直接作状语，不能加“在”，应说“他日前在医院见到了老同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
