INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92669, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92669, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保健是做一些事，让身体好好的，不容易生病。", "primary_collocate": null, "pronunciation": "bǎo jiàn", "ipa": "pau̯˨˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "为了不生病，奶奶每天打太极拳保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要学会保健，别总生病。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天容易感冒，大家要多保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝茶、散步，都是为了保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不抽烟，也很爱保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子的保健，妈妈最清楚。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡好觉是最简单的保健方法。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从年轻时就开始保健了。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保健不难，每天早睡早起就行。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们用热水泡脚保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保健操", "label": "复合"}, {"form": "保健品", "label": "复合"}], "register": "中性", "sense_fingerprint": "做些日常的事让身体好、少生病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保健", "is_correct": true, "explanation": "正确：“保健”指做些事让身体好、少生病，与“为了不生病”的目的一致。"}, {"text": "抽烟", "is_correct": false, "explanation": "语义：抽烟会伤身，与“为了不生病”的目的相反。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：熬夜不利于健康，与“为了不生病”相矛盾。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“打太极拳”之后接“吃饭”，两件事搭配不通，句子说不通。"}], "explanations": {"保健": "正确：“保健”指做些事让身体好、少生病，与“为了不生病”的目的一致。", "抽烟": "语义：抽烟会伤身，与“为了不生病”的目的相反。", "熬夜": "语义：熬夜不利于健康，与“为了不生病”相矛盾。", "吃饭": "搭配：“打太极拳”之后接“吃饭”，两件事搭配不通，句子说不通。"}, "sentence_index": 0, "correct_answer": "保健"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他住院三天，是为了保健。", "explanation": "这里应该用〈治病〉。住院是为了治疗疾病，“保健”指平时做事让身体好、少生病，不指住院治疗。"}, {"text": "他每天上班，是为了保健。", "explanation": "这里应该用〈谋生〉。上班是为了赚钱谋生，“保健”指做事让身体好、少生病，与工作无关。"}, {"text": "她每天染头发，是为了保健。", "explanation": "这里应该用〈美观〉。染发是为了改变外观、显得好看，“保健”指增进身体健康，不指外貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保健", "is_correct": true, "explanation": "正确：“保健方法”指增进健康、少生病的做法，符合“睡好觉”的语境。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病是要避免的情况，不能作“方法”。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧是生病的表现，不是保健的方法。"}, {"text": "醉酒", "is_correct": false, "explanation": "搭配：“方法”前不说“醉酒”这类有害的行为。"}], "explanations": {"保健": "正确：“保健方法”指增进健康、少生病的做法，符合“睡好觉”的语境。", "生病": "语义：生病是要避免的情况，不能作“方法”。", "发烧": "语义：发烧是生病的表现，不是保健的方法。", "醉酒": "搭配：“方法”前不说“醉酒”这类有害的行为。"}, "sentence_index": 6, "correct_answer": "保健"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把冰箱拿去保健，希望它不坏。", "explanation": "这里应该用〈保养〉。保健是人为了身体好而做的事，冰箱要维护应说“保养”。"}, {"text": "这间房子每天都要保健一次。", "explanation": "这里应该用〈维护〉。“保健”指增进人的身体健康，房子的日常维护要说“维护”。"}, {"text": "他每天擦洗钥匙，都是为了保健。", "explanation": "这里应该用〈清洁〉。擦洗钥匙是为了干净，“保健”指增进人的身体健康，不指清洁物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天早上跑步，希望能保健了。", "corrected_sentence": "我每天早上跑步，希望能保健。", "error_description": "“了”表示动作已经完成，与“希望能”所表达的尚未实现的愿望相矛盾，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天吃保健，身体一直很好。", "corrected_sentence": "他每天吃保健品，身体一直很好。", "error_description": "词语错误：“吃”的对象应是名词“保健品”，“保健”是动词，不能作“吃”的宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
