INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92670, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保护和增进身体健康。", "primary_collocate": null, "pronunciation": "bǎo jiàn", "ipa": "pau̯˨˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "冬天天冷，老人要注意保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后，很会保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，多喝水也是一种保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪大了，开始重视保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天散步半小时，就是为了保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保健要靠运动，也要靠吃得好。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作再忙，也不能忘了保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂保健，总是熬夜。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区医生教大家怎么保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变化大，我们更要保健。", "target_word": "保健", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保健操", "label": "复合"}, {"form": "保健品", "label": "复合"}], "register": "中性", "sense_fingerprint": "保护并增进身体健康", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保健", "is_correct": true, "explanation": "正确：“注意保健”指注意保护和增进健康，符合冬天天冷、老人要保暖的语境。"}, {"text": "开会", "is_correct": false, "explanation": "语义：开会与养生无关，「注意开会」讲不通，句子表达不出对健康的提醒。"}, {"text": "等待", "is_correct": false, "explanation": "语义：等待与对身体的照顾无关，「注意等待」讲不通，不能用来表示保健。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与天冷时的养生提醒无关，「注意唱歌」讲不通。"}], "explanations": {"保健": "正确：“注意保健”指注意保护和增进健康，符合冬天天冷、老人要保暖的语境。", "开会": "语义：开会与养生无关，「注意开会」讲不通，句子表达不出对健康的提醒。", "等待": "语义：等待与对身体的照顾无关，「注意等待」讲不通，不能用来表示保健。", "唱歌": "语义：唱歌与天冷时的养生提醒无关，「注意唱歌」讲不通。"}, "sentence_index": 0, "correct_answer": "保健"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去医院保健感冒。", "explanation": "这里应该用〈治疗〉。保健是保护和增进身体健康，治病要用“治疗”，不能说“保健感冒”。"}, {"text": "这些规定是为了保健安全。", "explanation": "这里应该用〈保障〉。保健指增进人的身体健康，维护安全要用“保障”。"}, {"text": "这种药可以保健流感。", "explanation": "这里应该用〈预防〉。保健侧重平时增进健康，防止疾病要用“预防”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保健", "is_correct": true, "explanation": "正确：“忘了保健”指忘记保护和增进健康，与“工作再忙”的语境相符。"}, {"text": "罢工", "is_correct": false, "explanation": "语义：罢工是停止工作，“也不能忘了罢工”说不通。"}, {"text": "失业", "is_correct": false, "explanation": "搭配：“忘了”后面不说“失业”这类失去工作的状态。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧是生病的表现，不是可以忘记的动作。"}], "explanations": {"保健": "正确：“忘了保健”指忘记保护和增进健康，与“工作再忙”的语境相符。", "罢工": "语义：罢工是停止工作，“也不能忘了罢工”说不通。", "失业": "搭配：“忘了”后面不说“失业”这类失去工作的状态。", "发烧": "语义：发烧是生病的表现，不是可以忘记的动作。"}, "sentence_index": 6, "correct_answer": "保健"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每周都给皮鞋保健一次。", "explanation": "这里应该用〈保养〉。保健的对象是人的身体，皮鞋是物品，维护它要用“保养”。"}, {"text": "他把存款拿去保健，希望它增值。", "explanation": "这里应该用〈保值〉。“保健”指增进人的身体健康，存款要维持价值应说“保值”。"}, {"text": "他每天都给电脑保健。", "explanation": "这里应该用〈维护〉。“保健”指增进人的身体健康，电脑是物品，日常照看要说“维护”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被保健，身体变好了。", "corrected_sentence": "他坚持保健，身体变好了。", "error_description": "“保健”是不及物动词，不能用“被”构成被动句；只需把“被”换成“坚持”，即“他坚持保健”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在认真保健了。", "corrected_sentence": "他正在认真保健。", "error_description": "时态错误：“正在”表示动作正在进行，不能同时用“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
