INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92673, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "偶然是没有想到，也没有安排，事情自己发生了。", "primary_collocate": null, "pronunciation": "ǒu rán", "ipa": "oʊ˨˩˦ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "我们是偶然认识的。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我偶然在书店遇到了老同学。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次见面纯属偶然。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他偶然发现了一家好吃的小店。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶然的机会让我学会了做饭。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的相遇不是计划好的，只是偶然。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她偶然听到了自己的名字。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很偶然，谁也没有安排。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是偶然看到这个广告的。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我偶然翻开这本旧书，发现里面有一张照片。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偶然地", "label": "状语形式"}, {"form": "偶然性", "label": "派生"}], "register": "中性", "sense_fingerprint": "偶然：没想到、没安排，事情自己发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11634477-b3a7-490b-8534-8c42b7d88671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92673, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶然", "is_correct": true, "explanation": "偶然：没想到、没安排而发生，符合「我们」是出于意外而认识的语境。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：「陌生」是不熟悉，与「认识」矛盾，不能说明两人是怎样认识的。"}, {"text": "熟练", "is_correct": false, "explanation": "搭配：「熟练」多用来形容技能，不能用来描述「认识」的经过。"}, {"text": "亲切", "is_correct": false, "explanation": "搭配：「亲切」形容态度或感觉，不能用来说明两人认识的方式。"}], "explanations": {"偶然": "偶然：没想到、没安排而发生，符合「我们」是出于意外而认识的语境。", "陌生": "语义：「陌生」是不熟悉，与「认识」矛盾，不能说明两人是怎样认识的。", "熟练": "搭配：「熟练」多用来形容技能，不能用来描述「认识」的经过。", "亲切": "搭配：「亲切」形容态度或感觉，不能用来说明两人认识的方式。"}, "sentence_index": 0, "correct_answer": "偶然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我偶然来这家店吃饭，已经坚持一年了。", "explanation": "这里应该用〈经常〉。偶然指没想到、没安排而发生，不能描述已经坚持一年的规律习惯；经常可以表示有规律地重复。"}, {"text": "我偶然早起，为了赶上第一班车。", "explanation": "这里应该用〈特意〉。偶然指没有预先安排，不能与「为了赶上」这种有目的的句子搭配；特意表示有意安排。"}, {"text": "我们早就约好了周五的会议，偶然在会议室见了面。", "explanation": "这里应该用〈如约〉。偶然指没想到、没安排而发生，与「早就约好了」的事先安排相矛盾；如约表示按照约定进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶然", "is_correct": true, "explanation": "偶然：没想到而听见，符合「她」突然听到自己名字的情境。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：「响亮」形容声音本身，不能说明「听到」的方式。"}, {"text": "缓慢", "is_correct": false, "explanation": "搭配：「缓慢」形容动作的速度，不能用来描述突然听到名字的情形。"}, {"text": "熟悉", "is_correct": false, "explanation": "语义：「熟悉」表示对人或事情了解，无法说明「听到名字」这一突然经历的方式。"}], "explanations": {"偶然": "偶然：没想到而听见，符合「她」突然听到自己名字的情境。", "响亮": "搭配：「响亮」形容声音本身，不能说明「听到」的方式。", "缓慢": "搭配：「缓慢」形容动作的速度，不能用来描述突然听到名字的情形。", "熟悉": "语义：「熟悉」表示对人或事情了解，无法说明「听到名字」这一突然经历的方式。"}, "sentence_index": 6, "correct_answer": "偶然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她偶然准备好了这次聚会，所有安排都提前定好了。", "explanation": "这里应该用〈预先〉。偶然指没想到、没安排，与「提前定好了」的意思相反；预先表示事先做好。"}, {"text": "他偶然把门关上，想让我生气。", "explanation": "这里应该用〈故意〉。偶然指无意中发生，不能与「想让我生气」这种有目的的行为搭配；故意表示有意为之。"}, {"text": "他是个很可靠的人，明天的会议他偶然一定会参加。", "explanation": "这里应该用〈必定〉。偶然指没想到、没安排而发生，不能与「一定会」这种确定的判断搭配；必定表示一定会如此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我偶然了在车站碰见了小学同学。", "corrected_sentence": "我偶然在车站碰见了小学同学。", "error_description": "错误形式：「我偶然了在车站碰见了小学同学」。「偶然」是形容词，后面不能直接加「了」，「了」应只放在动词「碰见」后。正确形式：「我偶然在车站碰见了小学同学」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天偶然一条小路。", "corrected_sentence": "我昨天偶然发现了一条小路。", "error_description": "错误形式：「偶然一条小路」，缺少动词「发现了」，「偶然」是形容词，不能直接带宾语。正确形式：「偶然发现了一条小路」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92674, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "必然", "is_correct": true, "explanation": "必然：一定会发生、不可避免，与「不是必然的」正好相反，是这一义项的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：明白、不模糊，与「偶然」没有反义关系。"}, {"text": "重要", "is_correct": false, "explanation": "重要：有很大作用或价值，与「偶然」没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：人多、有声响，与「偶然」没有反义关系。"}], "correct_answer": "必然", "explanations": {"必然": "必然：一定会发生、不可避免，与「不是必然的」正好相反，是这一义项的反义词。", "清楚": "清楚：明白、不模糊，与「偶然」没有反义关系。", "重要": "重要：有很大作用或价值，与「偶然」没有反义关系。", "热闹": "热闹：人多、有声响，与「偶然」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92674, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "必然", "is_correct": true, "explanation": "必然：一定会发生、不可避免，与「不是必然的」正好相反，是这一义项的反义词。"}, {"text": "简单", "is_correct": false, "explanation": "简单：不复杂，与「偶然」没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：没有声音、不吵闹，与「偶然」没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐：排列有序，与「偶然」没有反义关系。"}], "correct_answer": "必然", "explanations": {"必然": "必然：一定会发生、不可避免，与「不是必然的」正好相反，是这一义项的反义词。", "简单": "简单：不复杂，与「偶然」没有反义关系。", "安静": "安静：没有声音、不吵闹，与「偶然」没有反义关系。", "整齐": "整齐：排列有序，与「偶然」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92674, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事情的发生出于意料；不是必然的。", "primary_collocate": null, "pronunciation": "ǒu rán", "ipa": "oʊ˨˩˦ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "成功不是偶然的，是努力的结果。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是偶然的现象，不要太担心。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶然的错误可以原谅，常常出错就不行。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天迟到只是偶然。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不是偶然，而是必然。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶然发生一次，不能说明问题。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的胜利很偶然，我们还要努力。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结果看起来偶然，其实有原因。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次偶然的事故，改变了他的生活。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他能考第一，并不偶然，他一直很努力。", "target_word": "偶然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偶然地", "label": "状语形式"}, {"form": "偶然性", "label": "派生"}], "register": "中性", "sense_fingerprint": "偶然：出于意料，不是必然的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11634477-b3a7-490b-8534-8c42b7d88671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶然", "is_correct": true, "explanation": "偶然：不是必然的，符合「成功不是……，是努力的结果」的语意。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：「清晰」形容事物的明确程度，不能用来描述成功的性质。"}, {"text": "透明", "is_correct": false, "explanation": "语义：「透明」形容物体能透光，与成功的性质无关，句意不通。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：「陌生」是不熟悉，与「成功」的意思无关，句意不通。"}], "explanations": {"偶然": "偶然：不是必然的，符合「成功不是……，是努力的结果」的语意。", "清晰": "搭配：「清晰」形容事物的明确程度，不能用来描述成功的性质。", "透明": "语义：「透明」形容物体能透光，与成功的性质无关，句意不通。", "陌生": "语义：「陌生」是不熟悉，与「成功」的意思无关，句意不通。"}, "sentence_index": 0, "correct_answer": "偶然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "只要认真复习，他偶然能考好。", "explanation": "这里应该用〈必定〉。偶然表示没有必然性，与「只要认真复习」这种条件推断相矛盾；必定表示一定会如此。"}, {"text": "水在一百摄氏度时沸腾，这是偶然的现象。", "explanation": "这里应该用〈必然〉。偶然指不是必然的；水在一百摄氏度时沸腾是一定会发生的，不能说是偶然的。"}, {"text": "他每天都迟到，这是偶然的。", "explanation": "这里应该用〈必然〉。每天都发生的事不是偶然的，偶然与「每天都」矛盾；必然表示一定会发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶然", "is_correct": true, "explanation": "偶然：不是必然的，「很偶然」说明胜利并非稳定的必然结果，符合句意。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：「热闹」形容场面或气氛，不能用来形容胜利。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：「拥挤」形容空间或人群，不能用来形容胜利的性质。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：「幼稚」形容想法或行为不成熟，不能用来描述比赛胜利的性质。"}], "explanations": {"偶然": "偶然：不是必然的，「很偶然」说明胜利并非稳定的必然结果，符合句意。", "热闹": "搭配：「热闹」形容场面或气氛，不能用来形容胜利。", "拥挤": "搭配：「拥挤」形容空间或人群，不能用来形容胜利的性质。", "幼稚": "语义：「幼稚」形容想法或行为不成熟，不能用来描述比赛胜利的性质。"}, "sentence_index": 6, "correct_answer": "偶然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次的失败是偶然的，早有迹象。", "explanation": "这里应该用〈注定〉。偶然表示没有必然性，与「早有迹象」的推断矛盾；注定表示已经确定会如此。"}, {"text": "他偶然迟到，想让老师注意他。", "explanation": "这里应该用〈故意〉。偶然指出于意料、不是必然的，不能与「想让老师注意他」这种有目的的行为搭配；故意表示有意为之。"}, {"text": "这样努力下去，他偶然会成功。", "explanation": "这里应该用〈势必〉。偶然表示没有必然性，与「这样努力下去」的条件推断矛盾；势必表示按情况发展一定会如此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次失败是很偶然。", "corrected_sentence": "这次失败很偶然。", "error_description": "错误形式：「这次失败是很偶然」。形容词「偶然」受「很」修饰作谓语时不用「是」；若用「是」，须说「是偶然的」。正确形式：「这次失败很偶然」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他得第一不是偶然了。", "corrected_sentence": "他得第一不是偶然的。", "error_description": "错误形式：「不是偶然了」。「是……的」结构说明性质，应以「的」结尾，不能用「了」。正确形式：「不是偶然的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
