INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92675, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "月份是一年里的第几个月。", "primary_collocate": null, "pronunciation": "yuè fèn", "ipa": "ɥe˥˩ fən˥˩", "syllable_count": 2, "sentences": [{"text": "你是哪个月份出生的？", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三月份的时候，花都开了。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年里，二月份的天数最少。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的生日在六月份。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京十二月份很冷。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八月份是我们学校的假期。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最喜欢哪个月份？", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九月份我们开学。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是五月份来的。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个月份最热？", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一年十二个月中的第几个月，如三月份、十二月份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '465f594a-3aae-426d-a776-e288a89e9985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月份", "is_correct": true, "explanation": "月份指一年中的某一个月，“哪个月份出生”搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是时间，不能说“哪个颜色出生的”。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不是时间单位，“哪个动物出生的”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“出生”后不能接“身高”这类属性词，“哪个身高出生的”不成立。"}], "explanations": {"月份": "月份指一年中的某一个月，“哪个月份出生”搭配自然。", "颜色": "语义：颜色不是时间，不能说“哪个颜色出生的”。", "动物": "语义：动物不是时间单位，“哪个动物出生的”说不通。", "身高": "搭配：“出生”后不能接“身高”这类属性词，“哪个身高出生的”不成立。"}, "sentence_index": 0, "correct_answer": "月份"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的月份是三月二十号。", "explanation": "这里应该用〈生日〉。“月份”只能说一年中的第几个月，具体哪一天出生要用“生日”。"}, {"text": "我的假期只有两个月份。", "explanation": "这里应该用〈个月〉。“月份”指一年中的第几个月，表示假期的长短要用“两个月”，不能用“月份”。"}, {"text": "我们约好见面的月份是下午三点。", "explanation": "这里应该用〈时间〉。“月份”指一年中的第几个月，见面的具体时刻要用“时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月份", "is_correct": true, "explanation": "月份指某一个月，“你最喜欢哪个月份”语义和搭配都自然。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝不是可以被“喜欢”的时间单位，问句说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“喜欢”不与“体重”这类数值搭配，“哪个体重”不成立。"}, {"text": "脚趾", "is_correct": false, "explanation": "语义：脚趾不是时间，“你最喜欢哪个脚趾”与语境不符。"}], "explanations": {"月份": "月份指某一个月，“你最喜欢哪个月份”语义和搭配都自然。", "螺丝": "语义：螺丝不是可以被“喜欢”的时间单位，问句说不通。", "体重": "搭配：“喜欢”不与“体重”这类数值搭配，“哪个体重”不成立。", "脚趾": "语义：脚趾不是时间，“你最喜欢哪个脚趾”与语境不符。"}, "sentence_index": 6, "correct_answer": "月份"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的月份是八千块。", "explanation": "这里应该用〈月薪〉。“月份”指一年中的第几个月，每个月拿的钱要用“月薪”。"}, {"text": "我们开会的月份在三楼。", "explanation": "这里应该用〈地点〉。“月份”指一年中的第几个月，开会的地方要用“地点”。"}, {"text": "班上的月份有四十个人。", "explanation": "这里应该用〈人数〉。“月份”指一年中的第几个月，班上有多少人要用“人数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是三个月份出生的。", "corrected_sentence": "他是三月份出生的。", "error_description": "数量错误：某人出生只能在一个月份，不能说“三个月份”，应说“三月份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的生日是三个月份。", "corrected_sentence": "我的生日是三月份。", "error_description": "数量错误：生日是一个具体的日子，不能说“三个月份”，应说“三月份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
