INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指某一个月，或一年中的各个月。", "primary_collocate": null, "pronunciation": "yuè fèn", "ipa": "ɥe˥˩ fən˥˩", "syllable_count": 2, "sentences": [{"text": "各个月份的天气都不一样。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月份的工作很多。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的几个月份都很热。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每个月份都有活动。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同月份的水果不一样。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月份天气最好。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些月份我都在上海。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请写出每个月份的名字。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月份从一月到十二月，一共有十二个。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月份不同，价格也不同。", "target_word": "月份", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泛指某一个月或各个月，如这个月份、各个月份、不同月份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '465f594a-3aae-426d-a776-e288a89e9985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月份", "is_correct": true, "explanation": "月份指某个月或各个月，“各个月份的天气”搭配自然。"}, {"text": "人", "is_correct": false, "explanation": "语义：人没有“天气”，“各个人的天气”说不通。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指不会有“天气”，句子无法成立。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与书面的“各个……的天气”语境不合，且语义不通。"}], "explanations": {"月份": "月份指某个月或各个月，“各个月份的天气”搭配自然。", "人": "语义：人没有“天气”，“各个人的天气”说不通。", "手指": "语义：手指不会有“天气”，句子无法成立。", "玩意儿": "语域：“玩意儿”是口语，与书面的“各个……的天气”语境不合，且语义不通。"}, "sentence_index": 0, "correct_answer": "月份"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在国外住了三个月份。", "explanation": "这里应该用〈个月〉。表示时间长短要用“三个月”，“月份”不能表示时长。"}, {"text": "我每天坐地铁用的是月份，很方便。", "explanation": "这里应该用〈月票〉。“月份”指一年中的某个月，不是每月可以乘车的票，要用“月票”。"}, {"text": "我的月份已经二十岁了。", "explanation": "这里应该用〈年龄〉。“月份”指一年中的第几个月，人已经多少岁要用“年龄”，“月份”不能表示年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月份", "is_correct": true, "explanation": "月份指某个月，“这些月份我都在上海”指这些时段，语义通顺。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍不是时段，“这些书籍我都在上海”说不通。"}, {"text": "土豆", "is_correct": false, "explanation": "语义：土豆不能表示时段，句子无法成立。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“这些”指时段，“工资”不是时段，不能说“这些工资我都在上海”。"}], "explanations": {"月份": "月份指某个月，“这些月份我都在上海”指这些时段，语义通顺。", "书籍": "语义：书籍不是时段，“这些书籍我都在上海”说不通。", "土豆": "语义：土豆不能表示时段，句子无法成立。", "工资": "搭配：“这些”指时段，“工资”不是时段，不能说“这些工资我都在上海”。"}, "sentence_index": 6, "correct_answer": "月份"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月份是红色的，很好看。", "explanation": "这里应该用〈颜色〉。“月份”指一年中的某个月，说东西的颜色要用“颜色”，不能用“月份”。"}, {"text": "他在这家公司的月份已经有五年了。", "explanation": "这里应该用〈工龄〉。“月份”指一年中的某个月，在公司工作了多少年要用“工龄”。"}, {"text": "他的月份有一米八，很高。", "explanation": "这里应该用〈身高〉。“月份”指一年中的某个月，人的高矮要用“身高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每月份的天气都不同。", "corrected_sentence": "每个月份的天气都不同。", "error_description": "量词错误：“每”后应接量词“个”，应说“每个月份”，不能说“每月份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各个月份们都有不同的花。", "corrected_sentence": "各个月份都有不同的花。", "error_description": "词缀错误：“们”只用于指人的复数，“月份”是事物，不能加“们”，应说“各个月份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
