INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92677, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "传送是把东西从这里送到那里。", "primary_collocate": null, "pronunciation": "chuán sòng", "ipa": "ʈʂʰwan˧˥ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "工人用机器把箱子传送到楼上。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条长长的带子正在传送行李。", "target_word": "传送", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂里的机器把零件一件一件传送到下一个地方。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器每天把货物传送到仓库。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小车沿着轨道传送煤炭。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能把面包自动传送到包装的地方。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们用机器把砖头一块一块传送到楼上。", "target_word": "传送", "complexity_tier": "T3", "furigana": "gōng rén men yòng jī qì bǎ zhuān tou yí kuài yí kuài chuán sòng dào lóu shang", "sentence_source": "generated"}, {"text": "这个机器会把信件传送到不同的房间。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小车不停地传送着货物。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批行李已经传送到出口了。", "target_word": "传送", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "传送了", "label": "体标"}, {"form": "传送着", "label": "体标"}, {"form": "传送过", "label": "体标"}, {"form": "传送带", "label": "复合"}], "register": "中性", "sense_fingerprint": "把实物从一处送到另一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c6695f-4d15-45b9-91eb-7195eb7df105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92677, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传送", "is_correct": true, "explanation": "传送：机器把箱子从一处送到另一处，符合“用机器”“到楼上”的语境。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔指猛然落下或撞击，不能说把箱子摔到楼上。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：擦的对象是表面，不说“擦到楼上”。"}, {"text": "锁", "is_correct": false, "explanation": "配价：锁只带受事，不带“到楼上”这类去向补语。"}], "explanations": {"传送": "传送：机器把箱子从一处送到另一处，符合“用机器”“到楼上”的语境。", "摔": "语义：摔指猛然落下或撞击，不能说把箱子摔到楼上。", "擦": "搭配：擦的对象是表面，不说“擦到楼上”。", "锁": "配价：锁只带受事，不带“到楼上”这类去向补语。"}, "sentence_index": 0, "correct_answer": "传送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把生日礼物传送给妈妈。", "explanation": "这里应该用〈送〉。传送多指借助机器、管道或信号输送，亲手把礼物交给人要用送。"}, {"text": "这种病会通过空气传送。", "explanation": "这里应该用〈传染〉。传送指物品或信息被输送，疾病经空气扩散要用传染。"}, {"text": "流言很快就传送开了。", "explanation": "这里应该用〈传播〉。传送指定向输送，流言这类消息的扩散要用传播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传送", "is_correct": true, "explanation": "传送：机器把砖头从下面送到楼上，符合“用机器”“一块一块”“到楼上”的语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗的对象多是衣物、餐具，不说“洗到楼上”。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧指用火加热或焚毁，砖头不会被烧送到楼上。"}, {"text": "吃", "is_correct": false, "explanation": "配价：吃要求有生命的主体，机器不能吃砖头。"}], "explanations": {"传送": "传送：机器把砖头从下面送到楼上，符合“用机器”“一块一块”“到楼上”的语境。", "洗": "搭配：洗的对象多是衣物、餐具，不说“洗到楼上”。", "烧": "语义：烧指用火加热或焚毁，砖头不会被烧送到楼上。", "吃": "配价：吃要求有生命的主体，机器不能吃砖头。"}, "sentence_index": 6, "correct_answer": "传送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把弟弟传送到了学校门口。", "explanation": "这里应该用〈带〉。传送用于物品或信号，带人去某处要用带。"}, {"text": "他把老师传送到了办公室。", "explanation": "这里应该用〈请〉。传送不用于人，请人到某处要用请。"}, {"text": "他把小狗传送到了院子里。", "explanation": "这里应该用〈牵〉。传送用于物品，牵动物到某处要用牵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台设备把药品传送病房。", "corrected_sentence": "这台设备把药品传送到病房。", "error_description": "错误：“传送病房”；正确：“传送到病房”。“传送”后面引出去向要用“到”，这里漏掉了“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "传送带把箱子传送在楼下了。", "corrected_sentence": "传送带把箱子传送到楼下了。", "error_description": "错误：“传送”后引出去向要用“到”，不能用“在”；正确为“传送到楼下了”。“在”表示所在，不表示输送的去向。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
