INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92679, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92679, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "权益是每个人应该有、别人不能拿走的好处。", "primary_collocate": null, "pronunciation": "quán yì", "ipa": "tɕʰɥɛn˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "每个人都有自己的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人不能拿走你的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的权益要保护。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护自己的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不能不顾工人的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的权益也很重要。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时，要想到自己的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了同学的权益去找老师。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人可以伤害别人的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做会影响客人的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "權益", "label": "繁体"}, {"form": "合法权益", "label": "复合"}], "register": "正式", "sense_fingerprint": "每个人应有、不容他人侵占的好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '465f594a-3aae-426d-a776-e288a89e9985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92679, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "权益", "is_correct": true, "explanation": "正确。权益指每个人应有、不容他人侵占的好处。"}, {"text": "全力", "is_correct": false, "explanation": "全力（quán lì）与“权益”（quán yì）只有第二音节不同：yì 与 lì 声母不同。全力意思是竭尽全部力量。"}, {"text": "权宜", "is_correct": false, "explanation": "权宜（quán yí）与“权益”第二音节声调不同（第二声与第四声）。权宜意思是暂时适应当前情况的办法。"}, {"text": "传译", "is_correct": false, "explanation": "传译（chuán yì）与“权益”第一音节声母不同：ch 与 q。传译意思是口头翻译。"}], "explanations": {"权益": "正确。权益指每个人应有、不容他人侵占的好处。", "全力": "全力（quán lì）与“权益”（quán yì）只有第二音节不同：yì 与 lì 声母不同。全力意思是竭尽全部力量。", "权宜": "权宜（quán yí）与“权益”第二音节声调不同（第二声与第四声）。权宜意思是暂时适应当前情况的办法。", "传译": "传译（chuán yì）与“权益”第一音节声母不同：ch 与 q。传译意思是口头翻译。"}, "sentence_index": null, "correct_answer": "权益"}, "level_3": {"options": [{"text": "权益", "is_correct": true, "explanation": "正确。“自己的权益”指依法应有的利益，符合语境。"}, {"text": "政府", "is_correct": false, "explanation": "语义：“政府”是公共管理机构，不能被个人拥有，与“每个人都有自己的”不符。"}, {"text": "首都", "is_correct": false, "explanation": "语义：“首都”是国家的政治中心，不能属于某个人。"}, {"text": "时区", "is_correct": false, "explanation": "搭配：“有自己的”多用于可拥有之物，“时区”是地理划分，不说“自己的时区”。"}], "explanations": {"权益": "正确。“自己的权益”指依法应有的利益，符合语境。", "政府": "语义：“政府”是公共管理机构，不能被个人拥有，与“每个人都有自己的”不符。", "首都": "语义：“首都”是国家的政治中心，不能属于某个人。", "时区": "搭配：“有自己的”多用于可拥有之物，“时区”是地理划分，不说“自己的时区”。"}, "sentence_index": 0, "correct_answer": "权益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的权益比我高十厘米。", "explanation": "这里应该用〈身高〉。比较人的高矮要用“身高”，“权益”不能表示高矮。"}, {"text": "他有权益参加这次评选。", "explanation": "这里应该用〈资格〉。“有资格参加”指符合条件；权益指利益和好处，不能表示这种条件。"}, {"text": "他在单位里握有很大的权益。", "explanation": "这里应该用〈权力〉。“握有很大的权力”指支配他人的力量；权益指依法享有的利益，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92679, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权益", "is_correct": true, "explanation": "正确。“自己的权益”指应有的、不容他人侵占的好处，买东西时要想到的正是这个。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，买东西时不会想到它。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”与购物无关，买东西时不会去考虑。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是外貌特征，不是买东西时需要想到的内容。"}], "explanations": {"权益": "正确。“自己的权益”指应有的、不容他人侵占的好处，买东西时要想到的正是这个。", "作业": "语义：“作业”是学习任务，买东西时不会想到它。", "学历": "语义：“学历”与购物无关，买东西时不会去考虑。", "身高": "体貌：“身高”是外貌特征，不是买东西时需要想到的内容。"}, "sentence_index": 6, "correct_answer": "权益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在学术界很有权益。", "explanation": "这里应该用〈权威〉。“权威”指令人信服的地位或威望；权益指依法享有的利益，不能用来形容地位。"}, {"text": "这位老师在行业里的权益很高。", "explanation": "这里应该用〈声望〉。“声望很高”指受人敬重的名声；权益指依法享有的利益，不能用来形容名声。"}, {"text": "他有权益修改这份文件。", "explanation": "这里应该用〈权限〉。“有权限修改”指有资格去做某事；权益指利益和好处，不表示做事的资格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份合同保障了员工的一只权益。", "corrected_sentence": "这份合同保障了员工的一项权益。", "error_description": "量词错误：“权益”是抽象名词，计量用“项”，应说“一项权益”，不能说“一只权益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个人都有一只合法权益。", "corrected_sentence": "每个人都有一项合法权益。", "error_description": "量词错误：“权益”是抽象名词，计量用“项”，应说“一项合法权益”，不能说“一只合法权益”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
