INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "依法享有的权利和利益。", "primary_collocate": null, "pronunciation": "quán yì", "ipa": "tɕʰɥɛn˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "法律保护消费者的合法权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律保护员工的合法权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请律师保护自己的合法权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要依法保护股东的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费者的权益受到了侵害。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部法律保护妇女的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房人的合法权益也要保护。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要保护学生的合法权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不发工资，就是侵害员工的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买到坏东西，可以依法维护自己的权益。", "target_word": "权益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "權益", "label": "繁体"}, {"form": "消费者权益", "label": "复合"}], "register": "正式", "sense_fingerprint": "法律规定的权利和利益，如消费者权益、合法权益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '465f594a-3aae-426d-a776-e288a89e9985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "权益", "is_correct": true, "explanation": "正确。权益指依法享有的权利和利益。"}, {"text": "全力", "is_correct": false, "explanation": "全力（quán lì）与“权益”（quán yì）只有第二音节不同：yì 与 lì 声母不同。全力意思是竭尽全部力量。"}, {"text": "权宜", "is_correct": false, "explanation": "权宜（quán yí）与“权益”第二音节声调不同（第二声与第四声）。权宜意思是暂时适应当前情况的办法。"}, {"text": "传译", "is_correct": false, "explanation": "传译（chuán yì）与“权益”第一音节声母不同：ch 与 q。传译意思是口头翻译。"}, {"text": "前议", "is_correct": false, "explanation": "前议（qián yì）与“权益”第一音节韵母不同：i 与 u。前议意思是之前的讨论。"}], "explanations": {"权益": "正确。权益指依法享有的权利和利益。", "全力": "全力（quán lì）与“权益”（quán yì）只有第二音节不同：yì 与 lì 声母不同。全力意思是竭尽全部力量。", "权宜": "权宜（quán yí）与“权益”第二音节声调不同（第二声与第四声）。权宜意思是暂时适应当前情况的办法。", "传译": "传译（chuán yì）与“权益”第一音节声母不同：ch 与 q。传译意思是口头翻译。", "前议": "前议（qián yì）与“权益”第一音节韵母不同：i 与 u。前议意思是之前的讨论。"}, "sentence_index": null, "correct_answer": "权益"}, "level_3": {"options": [{"text": "权益", "is_correct": true, "explanation": "正确。“合法权益”指法律规定的权利和利益，与“法律保护”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是法律保护的对象，“合法天气”不成立。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与“法律保护”的正式语域不协调。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外貌特征，不能说“合法身高”。"}], "explanations": {"权益": "正确。“合法权益”指法律规定的权利和利益，与“法律保护”搭配。", "天气": "语义：“天气”是自然现象，不是法律保护的对象，“合法天气”不成立。", "玩意儿": "语域：“玩意儿”是口语，与“法律保护”的正式语域不协调。", "身高": "体貌：“身高”是人的外貌特征，不能说“合法身高”。"}, "sentence_index": 0, "correct_answer": "权益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布的权益是两毫米。", "explanation": "这里应该用〈厚度〉。布料的厚薄要用“厚度”，“权益”不能用来量度厚薄。"}, {"text": "这条路的权益有三公里。", "explanation": "这里应该用〈长度〉。路有多长要用“长度”，“权益”不能表示长度。"}, {"text": "他的权益是三十岁。", "explanation": "这里应该用〈年龄〉。人几岁要用“年龄”，“权益”不能表示年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权益", "is_correct": true, "explanation": "正确。“合法权益”指法律保护的权利和利益，符合语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“合法作业”不成立，“作业”与法律保护无关。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”不是法律保护的对象，与“合法”不搭。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”是外貌或神情，不是可以被法律保护的事物。"}], "explanations": {"权益": "正确。“合法权益”指法律保护的权利和利益，符合语境。", "作业": "语义：“合法作业”不成立，“作业”与法律保护无关。", "学历": "语义：“学历”不是法律保护的对象，与“合法”不搭。", "脸色": "体貌：“脸色”是外貌或神情，不是可以被法律保护的事物。"}, "sentence_index": 6, "correct_answer": "权益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的权益是五公斤。", "explanation": "这里应该用〈重量〉。物体的轻重要用“重量”，“权益”不能表示重量。"}, {"text": "这家店的权益开到晚上十点。", "explanation": "这里应该用〈营业时间〉。店铺开到几点要用“营业时间”，“权益”不能表示时间。"}, {"text": "这条河的权益很深。", "explanation": "这里应该用〈深度〉。河水的深浅要用“深度”，“权益”不能描述深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消费者的一只合法权益受到了法律保护。", "corrected_sentence": "消费者的一项合法权益受到了法律保护。", "error_description": "量词错误：“权益”计量用“项”，应说“一项合法权益”，不能说“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "退货是消费者的一只合法权益。", "corrected_sentence": "退货是消费者的一项合法权益。", "error_description": "量词错误：“权益”是抽象名词，计量用“项”，应说“一项合法权益”，不能说“一只合法权益”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
