INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92681, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公元前是很久很久以前，在一个叫公元的年份开始之前。", "primary_collocate": null, "pronunciation": "gōng yuán qián", "ipa": "kʊŋ˥ ɥɛn˧˥ tɕʰiɛn˧˥", "syllable_count": 3, "sentences": [{"text": "在公元前，这里还没有城市。", "target_word": "公元前", "complexity_tier": "T3", "furigana": "gōng yuán qián", "sentence_source": "generated"}, {"text": "他读到了许多公元前的故事。", "target_word": "公元前", "complexity_tier": "T3", "furigana": "gōng yuán qián", "sentence_source": "generated"}, {"text": "公元前的人，怎么记时间呢？", "target_word": "公元前", "complexity_tier": "T3", "furigana": "gōng yuán qián", "sentence_source": "generated"}, {"text": "我们看到的这块石头，来自公元前。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公元前的时代，离我们很远很远。", "target_word": "公元前", "complexity_tier": "T3", "furigana": "gōng yuán qián", "sentence_source": "generated"}, {"text": "课本上写着，这位国王生活在公元前。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公元前的一天，那时还没有文字，有个人走进了森林。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时是公元前，人们还没有手机。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友问：公元前是多久以前？", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐龙生活的年代比公元前还早很多。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "公元开始之前很久很久以前的时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c39e31-92d1-407d-a2da-901a9781bb50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公元前", "is_correct": true, "explanation": "正确。“在公元前”指很久远的古代，与“还没有城市”的语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是场所，不能表示时间，与句意不符。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“在”后需接时间词，“汽车”不能表示时间。"}, {"text": "地震", "is_correct": false, "explanation": "搭配：“在”后要接时间词，“地震”不能表示时间。"}], "explanations": {"公元前": "正确。“在公元前”指很久远的古代，与“还没有城市”的语境相符。", "厨房": "语义：“厨房”是场所，不能表示时间，与句意不符。", "汽车": "搭配：“在”后需接时间词，“汽车”不能表示时间。", "地震": "搭配：“在”后要接时间词，“地震”不能表示时间。"}, "sentence_index": 0, "correct_answer": "公元前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我公元前买了一本字典。", "explanation": "这里应该用〈去年〉。公元前指公元元年以前，不能用于说最近买的东西。"}, {"text": "他公元前见过我。", "explanation": "这里应该用〈前天〉。公元前是远古纪年，不能用于说最近几天的事。"}, {"text": "我公元前喝了茶。", "explanation": "这里应该用〈刚才〉。公元前指远古时期，不能用于说刚发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公元前", "is_correct": true, "explanation": "正确。“公元前的一天”指远古时期的某一天，与后文的远古叙述相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指未来，与“有个人走进了森林”的远古叙述不符。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“大海”不能作时间定语修饰“一天”。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是场所，与“那时还没有文字”的远古语境冲突。"}], "explanations": {"公元前": "正确。“公元前的一天”指远古时期的某一天，与后文的远古叙述相符。", "明天": "语义：“明天”指未来，与“有个人走进了森林”的远古叙述不符。", "大海": "搭配：“大海”不能作时间定语修饰“一天”。", "食堂": "语义：“食堂”是场所，与“那时还没有文字”的远古语境冲突。"}, "sentence_index": 6, "correct_answer": "公元前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我公元前去了超市。", "explanation": "这里应该用〈昨天〉。公元前指很久远的古代，不能用于说最近发生的事。"}, {"text": "我公元前吃了面包。", "explanation": "这里应该用〈早上〉。公元前是古代纪年，不能用于说当天的事。"}, {"text": "他公元前打了电话。", "explanation": "这里应该用〈刚才〉。公元前指远古时期，不能用于说刚发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在公元前前，人们还不知道种田。", "corrected_sentence": "在公元前，人们还不知道种田。", "error_description": "错误形式“公元前前”，正确形式“公元前”。“公元前”已经含有“前”字，后面不能再加“前”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在公元前里，人们还不会写字。", "corrected_sentence": "在公元前，人们还不会写字。", "error_description": "错误形式“公元前里”，正确形式“公元前”。“公元前”是时间词，后面不能加方位词“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
