INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92682, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公元纪年开始之前的时期，年份从公元元年向前倒数。", "primary_collocate": null, "pronunciation": "gōng yuán qián", "ipa": "kʊŋ˥ ɥɛn˧˥ tɕʰiɛn˧˥", "syllable_count": 3, "sentences": [{"text": "秦始皇在公元前221年统一了中国。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孔子生活在公元前五世纪左右。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城建于公元前五世纪，已经有两千多年了。", "target_word": "公元前", "complexity_tier": "T3", "furigana": "gōng yuán qián", "sentence_source": "generated"}, {"text": "公元前的人们已经会种水稻了。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一面公元前的铜镜。", "target_word": "公元前", "complexity_tier": "T3", "furigana": "gōng yuán qián", "sentence_source": "generated"}, {"text": "老师说，公元前和公元后的年份算法不一样。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是公元前的希腊历史。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公元前776年，古代奥运会开始了。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究的是公元前的文字。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些壁画是公元前留下来的。", "target_word": "公元前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "公元元年以前的纪年时期，年份向前倒数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c39e31-92d1-407d-a2da-901a9781bb50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公元前", "is_correct": true, "explanation": "正确。“公元前”表示公元元年以前的时期，与“221年”搭配，指秦始皇统一中国的年代。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指近一年，与“221年”矛盾，秦始皇统一中国不可能发生在去年。"}, {"text": "民国", "is_correct": false, "explanation": "语义：民国是1912年以后的时期，与秦始皇的年代冲突。"}, {"text": "第二年", "is_correct": false, "explanation": "搭配：“第二年”不能直接接具体年份“221年”，两者组合不成立。"}], "explanations": {"公元前": "正确。“公元前”表示公元元年以前的时期，与“221年”搭配，指秦始皇统一中国的年代。", "去年": "语义：“去年”指近一年，与“221年”矛盾，秦始皇统一中国不可能发生在去年。", "民国": "语义：民国是1912年以后的时期，与秦始皇的年代冲突。", "第二年": "搭配：“第二年”不能直接接具体年份“221年”，两者组合不成立。"}, "sentence_index": 0, "correct_answer": "公元前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我公元前去了北京。", "explanation": "这里应该用〈前年〉。公元前指公元元年以前的古代，不能指近几年的事。"}, {"text": "我公元前住在上海。", "explanation": "这里应该用〈以前〉。公元前指很久远的古代时期，不能指个人的过去经历。"}, {"text": "我们公元前一起爬了山。", "explanation": "这里应该用〈去年〉。公元前指公元元年以前，不能用于最近一年的事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公元前", "is_correct": true, "explanation": "正确。“公元前的希腊历史”指公元元年以前的希腊历史。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指未来，与“希腊历史”指古代事件冲突。"}, {"text": "清朝", "is_correct": false, "explanation": "语义：清朝是中国的朝代，与古希腊的历史不相关。"}, {"text": "前", "is_correct": false, "explanation": "搭配：“前”作名词时不能单独修饰“的希腊历史”，需要完整的时间词。"}], "explanations": {"公元前": "正确。“公元前的希腊历史”指公元元年以前的希腊历史。", "明天": "语义：“明天”指未来，与“希腊历史”指古代事件冲突。", "清朝": "语义：清朝是中国的朝代，与古希腊的历史不相关。", "前": "搭配：“前”作名词时不能单独修饰“的希腊历史”，需要完整的时间词。"}, "sentence_index": 6, "correct_answer": "公元前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我公元前过了生日。", "explanation": "这里应该用〈昨天〉。公元前指很久远的古代，不能用于说昨天发生的事。"}, {"text": "公元前我很累。", "explanation": "这里应该用〈今天〉。公元前是古代纪年，不能用于说自己当天的状态。"}, {"text": "我们公元前常一起玩。", "explanation": "这里应该用〈小时候〉。公元前指远古时期，不能指个人的童年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
